        if (is_start_with(path)) {
            return true
        }
        match (get_jwt_user(request)) {
            case Some(user) =>
                set_current_user_info_and_log(user)
                true
            case _ =>
                false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.slice(0, 4) == "/api" || request_uri.slice(0, 6) == "/login"
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as? HashMap<String, Any>
        let auth = headers?["Authorization"] as? HashMap<String, Any>
        let user = auth?["user"] as? HashMap<String, Any>
        let jwt = auth?["jwt"] as? String
        let today = DateTime.now().format("yyyy-MM-dd")
        match (user, jwt) {
            case (Some(u), Some(token)) if (token == (u["name"] ?? "") + today) => Some(u)
            case _ => None
        }
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user["name"] ?? "unknown"
        let addr = user["address"] ?? "0.0.0.0"
        println("Access by ${name} from ${addr}")
    }
}

