class AccessGatewayFilter {
    public init() {}

    public func filter(request: HashMap<String, Any>): Bool {
        // Allow /api/* and /login/*
        let path: String = request["path"] ?? ""
        if (is_start_with(path)) {
            return true
        }
        // Otherwise require valid JWT user
        let user = get_jwt_user(request)
        match (user) {
            case Some(u) =>
                set_current_user_info_and_log(u)
                return true
            case _ => return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers: HashMap<String, Any> = request["headers"] ?? HashMap<String, Any>()
        let auth: HashMap<String, Any> = headers["Authorization"] ?? HashMap<String, Any>()
        let user: HashMap<String, Any> = auth["user"] ?? HashMap<String, Any>()
        let jwt: String = auth["jwt"] ?? ""
        // Simple check: jwt exists and contains today's date
        let today = DateTime.now().format("yyyy-MM-dd")
        if (jwt.contains(today) && user.size > 0) {
            return Some(user)
        }
        None
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name: String = user["name"] ?? "unknown"
        let addr: String = user["address"] ?? "0.0.0.0"
        println("Access: user=${name} from ${addr}")
    }
}

import std.collection.*
import std.time.*
