class AccessGatewayFilter {

    public init() {}

    public func filter(request: HashMap<String, Any>): Bool {
        let pathOpt = request.get("path") ?? None<Any>
        let methodOpt = request.get("method") ?? None<Any>

        if (pathOpt is None<Any> || methodOpt is None<Any>) {
            return false
        }
        let path = pathOpt.getOrThrow() as String
        let method = methodOpt.getOrThrow() as String

        if (is_start_with(path)) {
            return true
        }

        let userOpt = get_jwt_user(request)
        if (userOpt is None<HashMap<String, Any>>) {
            return false
        }
        let user = userOpt.getOrThrow()
        set_current_user_info_and_log(user)
        return true
    }

    public func is_start_with(request_uri: String): Bool {
        return request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headersOpt = request.get("headers") ?? None<Any>
        if (headersOpt is None<Any>) {
            return None<HashMap<String, Any>>
        }
        let authOpt = (headersOpt.getOrThrow() as HashMap<String, Any>).get("Authorization") ?? None<Any>
        if (authOpt is None<Any>) {
            return None<HashMap<String, Any>>
        }
        let auth = authOpt.getOrThrow() as HashMap<String, Any>
        let jwtOpt = auth.get("jwt") ?? None<Any>
        if (jwtOpt is None<Any>) {
            return None<HashMap<String, Any>>
        }
        let jwt = jwtOpt.getOrThrow() as String
        let today = DateTime.now().format("yyyy-MM-dd")
        if (jwt.size < today.size || jwt.substring(jwt.size - today.size) != today) {
            return None<HashMap<String, Any>>
        }
        let userOpt = auth.get("user") ?? None<Any>
        if (userOpt is None<Any>) {
            return None<HashMap<String, Any>>
        }
        return Some<HashMap<String, Any>>(userOpt.getOrThrow() as HashMap<String, Any>)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let nameOpt = user.get("name") ?? None<Any>
        let addrOpt = user.get("address") ?? None<Any>
        let name = nameOpt is None<Any> ? "unknown" : nameOpt.getOrThrow() as String
        let addr = addrOpt is None<Any> ? "0.0.0.0" : addrOpt.getOrThrow() as String
        println("User: ${name}, Address: ${addr}")
    }
}

import std.math.*

class AreaCalculator {
    /*
    This is a class for calculating the area of different shapes, including circle, sphere, cylinder, sector and annulus.
    */

    let radius: Float64

    public init(radius: Float64) {
        /*
        Initialize the radius for shapes.
        :param radius: Float64
        */
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        /*
        calculate the area of circle based on this.radius
        :return: area of circle, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_circle_area()
        12.566370614359172
        */
        Float64.pi * this.radius * this.radius
    }

    public func calculate_sphere_area(): Float64 {
        /*
        calculate the area of sphere based on this.radius
        :return: area of sphere, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sphere_area()
        50.26548245743669
        */
        4.0 * Float64.pi * this.radius * this.radius
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        /*
        calculate the area of cylinder based on this.radius and height
        :param height: height of cylinder, Float64
        :return: area of cylinder, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_cylinder_area(3.0)
        62.83185307179586
        */
        2.0 * Float64.pi * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        /*
        calculate the area of sector based on this.radius and angle
        :param angle: angle of sector, Float64
        :return: area of sector, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sector_area(3.1415926)
        6.283185307179586
        */
        0.5 * angle * this.radius * this.radius
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        /*
        calculate the area of annulus based on inner_radius and out_radius
        :param inner_radius: inner radius of sector, Float64
        :param outer_radius: outer radius of sector, Float64
        :return: area of annulus, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_annulus_area(2.0, 3.0)
        15.707963267948966
        */
        Float64.pi * (outer_radius * outer_radius - inner_radius * inner_radius)
    }
}

