    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ").filter({s => s.size > 0})
        var i = 0
        while (i < parts.size) {
            let token = parts[i]
            if (token.startsWith("--")) {
                if (token.contains("=")) {
                    let kv = token.split("=", 1)
                    let key = kv[0].substring(2)
                    let value = kv[1]
                    let converted = convert_type(key, value)
                    arguments.add(key, converted)
                } else {
                    let key = token.substring(2)
                    arguments.add(key, true)
                }
            }
            else if (token.startsWith("-") && token.size > 1) {
                let key = token.substring(1)
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    let value = parts[i + 1]
                    let converted = convert_type(key, value)
                    arguments.add(key, converted)
                    i += 1
                } else {
                    arguments.add(key, true)
                }
            }
            i += 1
        }
        let missing = HashSet<String>()
        for (req in required) {
            if (!arguments.contains(req)) {
                missing.add(req)
            }
        }
        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments[key]
        }
        return None
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        if (types.contains(arg)) {
            let t = types[arg]
            match (t.name) {
                case "Int8"     => return Int8.fromString(value).getOrThrow()
                case "Int16"    => return Int16.fromString(value).getOrThrow()
                case "Int32"    => return Int32.fromString(value).getOrThrow()
                case "Int64"    => return Int64.fromString(value).getOrThrow()
                case "UInt8"    => return UInt8.fromString(value).getOrThrow()
                case "UInt16"   => return UInt16.fromString(value).getOrThrow()
                case "UInt32"   => return UInt32.fromString(value).getOrThrow()
                case "UInt64"   => return UInt64.fromString(value).getOrThrow()
                case "Float32"  => return Float32.fromString(value).getOrThrow()
                case "Float64"  => return Float64.fromString(value).getOrThrow()
                case "Bool"     => return value == "true"
                case _          => return value
            }
        }
        return value
    }
}

import std.collection.*
import std.reflect.*
import std.convert.*
import std.regex.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        // Split by whitespace, but keep quoted substrings intact
        let parts = splitRespectingQuotes(command_string)
        var i = 1   // skip script name
        while (i < parts.size) {
            var key = ""
            var value = ""
            let part = parts[i]
            if (part.startsWith("--")) {
                let eq = part.indexOf("=")
                if (eq >= 0) {
                    key = part.substring(2, eq)
                    value = part.substring(eq + 1)
                } else {
                    key = part.substring(2)
                    if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                        value = parts[i + 1]
                        i += 1
                    } else {
                        value = "true"  // flag
                    }
                }
            } else if (part.startsWith("-")) {
                key = part.substring(1)
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    value = parts[i + 1]
                    i += 1
                } else {
                    value = "true"
                }
            } else {
                i += 1
                continue
            }
            let converted = convert_type(key, value)
            arguments[key] = converted
            i += 1
        }

        let missing = HashSet<String>()
        for (r in required) {
            if (!arguments.contains(r)) {
                missing.add(r)
            }
        }
        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments[key]
        }
        return None
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types[arg] = arg_type
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value
        }
        let ti = types[arg]
        if (ti == TypeInfo.of<Int64>()) {
            return Int64.parse(value)
        } else if (ti == TypeInfo.of<Bool>()) {
            return value == "true"
        } else if (ti == TypeInfo.of<Float64>()) {
            return Float64.parse(value)
        } else {
            return value
        }
    }

    private func splitRespectingQuotes(s: String): Array<String> {
        let res = ArrayList<String>()
        let cur = StringBuilder()
        var inQuotes = false
        var quoteChar: Rune = r'"'
        for (c in s.runes()) {
            if (!inQuotes && (c == r'"' || c == r'\'')) {
                inQuotes = true
                quoteChar = c
                continue
            }
            if (inQuotes && c == quoteChar) {
                inQuotes = false
                continue
            }
            if (!inQuotes && c == r' ') {
                if (cur.size() > 0) {
                    res.append(cur.toString())
                    cur.clear()
                }
            } else {
                cur.append(Rune.toString(c))
            }
        }
        if (cur.size() > 0) {
            res.append(cur.toString())
        }
        return res.toArray()
    }
}

