class ArgumentParser {
    // Storage
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func add_argument(
        arg: String,
        required!: Bool = false,
        arg_type!: TypeInfo = TypeInfo.of<String>()
    ): Unit {
        types.add(arg, arg_type)
        if (required) {
            required.add(arg)
        }
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments[key]
        }
        return None<String>() // return None<Any> is impossible, use Any-compatible None
    }

    // Helper to convert a string value to the declared type for the argument
    private func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value // no declared type -> keep as String
        }
        let ti = types[arg]
        match (ti) {
            case TypeInfo.of<Int64>()  => return Int64.parse(value)
            case TypeInfo.of<Float64>() => return Float64.parse(value)
            case TypeInfo.of<Bool>()    => return value == "true"
            // Add more primitives as needed
            case _ => return value // fallback
        }
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ").filter({s => s.size > 0})
        let missing = HashSet<String>()
        let i = 0

        while (i < parts.size) {
            let tok = parts[i]
            if (!tok.startsWith("-")) {
                i += 1
                continue // skip non-option tokens (e.g. program name)
            }
            let key: String
            let value: String
            if (tok.contains("=")) {
                let kv = tok.split("=", 2)
                key = kv[0].stripPrefix("--").stripPrefix("-")
                value = kv[1]
            } else {
                key = tok.stripPrefix("--").stripPrefix("-")
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    value = parts[i + 1]
                    i += 1
                } else {
                    value = "true" // flag style
                }
            }
            let converted = convert_type(key, value)
            arguments.add(key, converted)
            i += 1
        }

        // Check required
        for (r in required) {
            if (!arguments.contains(r)) {
                missing.add(r)
            }
        }

        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None<HashSet<String>>())
    }
}

import std.collection.*
import std.convert.*
import std.reflect.*
import std.string.*

class ArgumentParser {
    /*  Command-line parser that supports:
           --key=value      long form (option with value)
           --key            long form (boolean option)
           -key value       short form (option with value)
           -key             short form (boolean option)
        All unparsed positional tokens are dropped by this simple version.
    */

    let arguments: HashMap<String, Any>
    let required:  HashSet<String>
    let types:     HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required  = HashSet<String>()
        types     = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let tokens = command_string.split(" ").filter({s => s.size > 0}).toArray()
        var i: Int64 = 0
        while (i < tokens.size) {
            let tok = tokens[i]
            /*  --- long form -------------------------------------------------- */
            if (tok.startsWith("--")) {
                let rest = tok[2..]
                let kv   = rest.split("=")
                if (kv.size == 2) {                /* --key=value             */
                    let key = kv[0]
                    let raw = kv[1]
                    arguments[key] = convert_type(key, raw)
                } else {                           /* --key                  */
                    let key = rest
                    arguments[key] = convert_type(key, "true")
                }
            }
            /*  --- short form ------------------------------------------------- */
            else if (tok.startsWith("-") && tok.size > 1) {
                let key  = tok[1..]
                let next = if (i + 1 < tokens.size) { tokens[i + 1] } else { "" }
                /* if next token looks like a new option, treat as switch */
                if (next.startsWith("-") || next.size == 0) {
                    arguments[key] = convert_type(key, "true")
                } else {                           /* -key value             */
                    arguments[key] = convert_type(key, next)
                    i += 1          /* extra consume value token */
                }
            }
            /*  --- skip anything else (script name, free arguments, etc.) ---- */
            i += 1
        }

        let missing = HashSet<String>()
        for (r in required) {
            if (!arguments.contains(r)) {
                missing.add(r)
            }
        }
        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            arguments[key]!
        } else {
            None<String>()   /* any 'none-like' value works because caller
                                  receives Any; using None<String> for brevity */
        }
    }

    public func add_argument(arg: String,
                             required!: Bool = false,
                             arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types[arg] = arg_type
        if (required) { required.add(arg) }
    }

    public func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value
        }
        let ti = types[arg]!
        let target = ti.typeName

        if (target == "Int64")   { return value.toInt64() }
        if (target == "Float64") { return value.toFloat64() }
        if (target == "Bool")    { if (value == "true") { return true } else { return false } }
        /* default: leave as received */
        value
    }
}

