        types[arg] = arg_type
    }

    public func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value
        }
        let t = types[arg]
        if (t == TypeInfo.of<Int64>()) {
            return Int64.parse(value)
        } else if (t == TypeInfo.of<Bool>()) {
            return value == "true"
        } else if (t == TypeInfo.of<Float64>()) {
            return Float64.parse(value)
        } else if (t == TypeInfo.of<String>()) {
            return value
        }
        return value
    }
}

import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ").filter({s => s.size > 0})
        var i = 0
        // skip script name
        if (i < parts.size && !parts[i].startsWith("-")) {
            i += 1
        }
        while (i < parts.size) {
            let token = parts[i]
            if (token.startsWith("--")) {
                let eq = token.indexOf("=")
                if (eq >= 0) {
                    let key = token.substring(2, eq)
                    let value = token.substring(eq + 1)
                    arguments[key] = convert_type(key, value)
                } else {
                    let key = token.substring(2)
                    arguments[key] = true
                }
                i += 1
            } else if (token.startsWith("-")) {
                let key = token.substring(1)
                if (i + 1 < parts.size && !parts[i+1].startsWith("-")) {
                    let value = parts[i+1]
                    arguments[key] = convert_type(key, value)
                    i += 2
                } else {
                    arguments[key] = true
                    i += 1
                }
            } else {
                i += 1
            }
        }
        let missing = HashSet<String>()
        for (req in required) {
            if (!arguments.contains(req)) {
                missing.add(req)
            }
        }
        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments[key]
        }
        return None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types[arg] = arg_type
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        if (types.contains(arg)) {
            let t = types[arg]
            let name = t.name
            if (name == "Int64") {
                return Int64.parse(value)
            } else if (name == "Int32") {
                return Int32.parse(value)
            } else if (name == "Float64") {
                return Float64.parse(value)
            } else if (name == "Bool") {
                return value == "true"
            } else {
                return value
            }
        }
        return value
    }
}

