            case _ => this.datas.size
        }
        let result = ArrayList<ArrayList<Int64>>()
        if (k <= 0 || k > this.datas.size) {
            return result
        }
        select_permutations(ArrayList<Int64>(), this.datas, k, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (k in 1..this.datas.size + 1) {
            let partial = select(Some(k))
            for (arr in partial) {
                result.add(arr)
            }
        }
        return result
    }

