import std.collection.ArrayList

class AvgPartition {

    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        let n = this.lst.size
        let size = n / this.limit
        let rem = n % this.limit
        (size, rem)
    }

    public func get(index: Int64): ArrayList<Int64> {
        let (size, rem) = this.setNum()
        let start = index * size + (if (index < rem) { index } else { rem })
        let end = start + size + (if (index < rem) { 1 } else { 0 })
        var out = ArrayList<Int64>()
        for (i in start..end) {
            out.append(this.lst[i])
        }
        out
    }
}

