import std.collection.ArrayList

class AvgPartition {

    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        if (limit <= 0) {
            throw "limit must be > 0"
        }
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        let n = lst.size
        (n / limit, n % limit)
    }

    public func get(index: Int64): ArrayList<Int64> {
        let (blockSize, rem) = setNum()
        if (index < 0 || index >= limit) {
            throw "index out of range"
        }
        let start = index * blockSize + (if (index < rem) { index } else { rem })
        let size = blockSize + if (index < rem) { 1 } else { 0 }
        let res = ArrayList<Int64>()
        for (i in start..(start + size)) {
            res.add(lst[i])
        }
        res
    }
}

