import std.collection.*

class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let a = num1.runes().toArray().map({r => r - r'0'})
        let b = num2.runes().toArray().map({r => r - r'0'})
        let (longer, shorter) = if (a.size > b.size) { (a, b) } else { (b, a) }

        var carry = 0
        var res = ArrayList<Rune>()
        var i = longer.size - 1
        var j = shorter.size - 1

        while (i >= 0) {
            let sum = longer[i] + (j >= 0 ? shorter[j] : 0) + carry
            carry = sum / 10
            res.add((sum % 10 + r'0').toRune())
            i -= 1
            if (j >= 0) { j -= 1 }
        }
        if (carry > 0) {
            res.add((carry + r'0').toRune())
        }
        return String(res.reverse().map({r => r}).toArray())
    }

    public static func subtract(num1: String, num2: String): String {
        let neg = num1.size < num2.size || (num1.size == num2.size && num1 < num2)
        let (big, small) = if (!neg) { (num1, num2) } else { (num2, num1) }
        let a = big.runes().toArray().map({r => r - r'0'})
        let b = small.runes().toArray().map({r => r - r'0'})

        var borrow = 0
        var i = a.size - 1
        var j = b.size - 1
        var res = ArrayList<Rune>()

        while (i >= 0) {
            let sub = a[i] - (j >= 0 ? b[j] : 0) - borrow
            borrow = if (sub < 0) { 1 } else { 0 }
            res.add((if (sub < 0) { sub + 10 } else { sub } + r'0').toRune())
            i -= 1
            if (j >= 0) { j -= 1 }
        }
        while (res.size > 1 && res[res.size - 1] == r'0') {
            res.remove(at: res.size - 1)
        }
        let digits = String(res.reverse().map({r => r}).toArray())
        return if (neg && digits != "0") { "-" + digits } else { digits }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") { return "0" }
        let a = num1.runes().toArray().map({r => r - r'0'})
        let b = num2.runes().toArray().map({r => r - r'0'})
        var res = Array<Int64>(a.size + b.size, item: 0)

        for (i in 0..a.size) {
            var carry = 0
            for (j in 0..b.size) {
                let prod = a[a.size - 1 - i] * b[b.size - 1 - j] + res[res.size - 1 - i - j] + carry
                carry = prod / 10
                res[res.size - 1 - i - j] = prod % 10
            }
            res[res.size - 1 - i - b.size] += carry
        }
        var start = 0
        while (start < res.size && res[start] == 0) { start += 1 }
        return String(res[start..].map({n => (n + r'0').toRune()}).toArray())
    }
}

