class BigNumCalculator {
    public static func add(num1: String, num2: String): String {
        let a = num1.runes().toArray().map({r: Rune => Int64(r.codePoint - 48)}).reverse()
        let b = num2.runes().toArray().map({r: Rune => Int64(r.codePoint - 48)}).reverse()
        let maxLen = a.size > b.size ? a.size : b.size
        var res = ArrayList<Int64>()
        var carry: Int64 = 0
        for (i in 0..maxLen) {
            let da = i < a.size ? a[i] : 0
            let db = i < b.size ? b[i] : 0
            let sum = da + db + carry
            res.add(sum % 10)
            carry = sum / 10
        }
        if (carry > 0) res.add(carry)
        let sb = StringBuilder()
        let arr = res.toArray().reverse()
        for (d in arr) sb.append("${d}")
        return sb.toString()
    }

    public static func subtract(num1: String, num2: String): String {
        let neg = {s: String => "-${s}"}
        let cmp = {x: Array<Int64>, y: Array<Int64> =>
            if (x.size != y.size) x.size > y.size else {
                var i = x.size - 1
                while (i >= 0 && x[i] == y[i]) { i -= 1 }
                if (i < 0) 0 else if (x[i] > y[i]) 1 else -1
            }
        }
        let a = num1.runes().toArray().map({r: Rune => Int64(r.codePoint - 48)}).reverse()
        let b = num2.runes().toArray().map({r: Rune => Int64(r.codePoint - 48)}).reverse()
        var sign = ""
        var x = a
        var y = b
        if (cmp(a, b) < 0) { sign = "-"; x = b; y = a }
        var res = ArrayList<Int64>()
        var borrow: Int64 = 0
        for (i in 0..x.size) {
            let dx = x[i] - borrow
            let dy = i < y.size ? y[i] : 0
            borrow = 0
            var d = dx - dy
            if (d < 0) { d += 10; borrow = 1 }
            res.add(d)
        }
        while (res.size > 1 && res[res.size - 1] == 0) res.remove(at: res.size - 1)
        let sb = StringBuilder()
        let arr = res.toArray().reverse()
        for (d in arr) sb.append("${d}")
        return sign + sb.toString()
    }

    public static func multiply(num1: String, num2: String): String {
        let a = num1.runes().toArray().map({r: Rune => Int64(r.codePoint - 48)}).reverse()
        let b = num2.runes().toArray().map({r: Rune => Int64(r.codePoint - 48)}).reverse()
        var res = Array<Int64>(a.size + b.size, {_ => 0})
        for (i in 0..a.size) {
            var carry: Int64 = 0
            for (j in 0..b.size) {
                let p = a[i] * b[j] + res[i + j] + carry
                res[i + j] = p % 10
                carry = p / 10
            }
            res[i + b.size] += carry
        }
        while (res.size > 1 && res[res.size - 1] == 0) res.remove(at: res.size - 1)
        let sb = StringBuilder()
        let arr = res.reverse()
        for (d in arr) sb.append("${d}")
        return sb.toString()
    }
}

