class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        if (num1 == "0") { return num2 }
        if (num2 == "0") { return num1 }
        let neg1 = num1[0] == '-'
        let neg2 = num2[0] == '-'
        let n1 = if (neg1) { num1[1..] } else { num1 }
        let n2 = if (neg2) { num2[1..] } else { num2 }

        if (neg1 == neg2) {
            let sum = addPositive(n1, n2)
            return if (neg1) { "-${sum}" } else { sum }
        } else if (comparePositive(n1, n2) >= 0) {
            let diff = subtractPositive(n1, n2)
            return if (neg1) { "-${diff}" } else { diff }
        } else {
            let diff = subtractPositive(n2, n1)
            return if (neg2) { "-${diff}" } else { diff }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        let neg2 = num2[0] == '-'
        let n2 = if (neg2) { num2[1..] } else { "-${num2}" }
        return add(num1, n2)
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") { return "0" }
        let neg1 = num1[0] == '-'
        let neg2 = num2[0] == '-'
        let n1 = if (neg1) { num1[1..] } else { num1 }
        let n2 = if (neg2) { num2[1..] } else { num2 }
        let prod = multiplyPositive(n1, n2)
        return if (neg1 != neg2) { "-${prod}" } else { prod }
    }

    private static func addPositive(a: String, b: String): String {
        let i = a.size - 1
        let j = b.size - 1
        var carry = 0
        let res = ArrayList<Rune>([])
        while (i >= 0 || j >= 0 || carry > 0) {
            let da = if (i >= 0) { a[i].toString().toInt64() } else { 0 }
            let db = if (j >= 0) { b[j].toString().toInt64() } else { 0 }
            let sum = da + db + carry
            res.add((48 + sum % 10).toRune())
            carry = sum / 10
            i -= 1
            j -= 1
        }
        let arr = res.toArray()
        arr.reverse()
        return String.fromRunes(arr)
    }

    private static func subtractPositive(a: String, b: String): String {
        let cmp = comparePositive(a, b)
        if (cmp == 0) { return "0" }
        let (big, small) = if (cmp > 0) { (a, b) } else { (b, a) }
        let i = big.size - 1
        let j = small.size - 1
        var borrow = 0
        let res = ArrayList<Rune>([])
        while (i >= 0) {
            let da = big[i].toString().toInt64()
            let db = if (j >= 0) { small[j].toString().toInt64() } else { 0 }
            let diff = da - db - borrow
            let (d, b) = if (diff < 0) { (diff + 10, 1) } else { (diff, 0) }
            res.add((48 + d).toRune())
            borrow = b
            i -= 1
            j -= 1
        }
        let arr = res.toArray()
        arr.reverse()
        let s = String.fromRunes(arr)
        let idx = 0
        while (idx < s.size - 1 && s[idx] == '0') {
            idx += 1
        }
        let out = s[idx..]
        return if (cmp > 0) { out } else { "-${out}" }
    }

    private static func multiplyPositive(a: String, b: String): String {
        let m = a.size
        let n = b.size
        let prod = Array<Int64>(m + n, item: 0)
        for (i in 0..m) {
            let da = a[m - 1 - i].toString().toInt64()
            var carry = 0
            for (j in 0..n) {
                let db = b[n - 1 - j].toString().toInt64()
                let tmp = da * db + prod[i + j] + carry
                prod[i + j] = tmp % 10
                carry = tmp / 10
            }
            prod[i + n] += carry
        }
        let last = m + n - 1
        var leading = last
        while (leading > 0 && prod[leading] == 0) {
            leading -= 1
        }
        let runes = Array<Rune>(leading + 1, item: '0')
        for (k in 0..leading + 1) {
            runes[leading - k] = (48 + prod[k]).toRune()
        }
        return String.fromRunes(runes)
    }

    private static func comparePositive(a: String, b: String): Int64 {
        if (a.size != b.size) { return if (a.size > b.size) { 1 } else { -1 } }
        for (i in 0..a.size) {
            let da = a[i].toString().toInt64()
            let db = b[i].toString().toInt64()
            if (da != db) { return if (da > db) { 1 } else { -1 } }
        }
        return 0
    }
}

