/* --------------- helpers --------------- */

// Reverse a string so the least-significant digit is first.
func reverse(s: String): String {
    var t = StringBuilder()
    for (i in 0..s.size) {
        t.append(s[s.size - 1 - i])
    }
    return t.toString()
}

// Pad the shorter string with zeros on the right to make them same length.
func padZeros(a: String, b: String): (String, String) {
    let diff = a.size - b.size
    if (diff > 0) {
        return (a, b + "0".repeat(diff))
    } else if (diff < 0) {
        return (a + "0".repeat(-diff), b)
    } else {
        return (a, b)
    }
}

/* --------------- add --------------- */
public static func add(num1: String, num2: String): String {
    let (a, b) = padZeros(num1, num2)
    let n = a.size
    var carry = 0
    var res = ArrayList<Rune>()

    for (i in (n - 1)..(-1): -1) {
        let d1 = Int64(a[i].toString().toInt64())
        let d2 = Int64(b[i].toString().toInt64())
        let sum = d1 + d2 + carry
        res.add(Rune(Char(sum % 10 + 48)))
        carry = sum / 10
    }
    if (carry > 0) {
        res.add(Rune(Char(carry + 48)))
    }

    // build result in correct order
    var ans = StringBuilder()
    for (j in (res.size - 1)..(-1): -1) {
        ans.append(res[j])
    }
    return ans.toString()
}

/* --------------- subtract (a >= b) --------------- */
public static func subtract(num1: String, num2: String): String {
    let neg = num1.size < num2.size ||
              (num1.size == num2.size && num1 < num2)
    let (big, small) = if (neg) { (num2, num1) } else { (num1, num2) }
    let (a, b) = padZeros(big, small)
    let n = a.size
    var borrow = 0
    var res = ArrayList<Rune>()

    for (i in (n - 1)..(-1): -1) {
        let d1 = Int64(a[i].toString().toInt64())
        let d2 = Int64(b[i].toString().toInt64()) + borrow
        borrow = 0
        var diff = d1 - d2
        if (diff < 0) {
            diff += 10
            borrow = 1
        }
        res.add(Rune(Char(diff + 48)))
    }
    // strip leading zeros
    while (res.size > 1 && res[res.size - 1].toString() == "0") {
        res.remove(at: res.size - 1)
    }
    var ans = StringBuilder()
    if (neg) { ans.append("-") }
    for (j in (res.size - 1)..(-1): -1) {
        ans.append(res[j])
    }
    return ans.toString()
}

/* --------------- multiply --------------- */
public static func multiply(num1: String, num2: String): String {
    if (num1 == "0" || num2 == "0") { return "0" }
    let a = reverse(num1)
    let b = reverse(num2)
    var prod = Array<Int64>(a.size + b.size, item: 0)

    for (i in 0..a.size) {
        let d1 = Int64(a[i].toString().toInt64())
        var carry = 0
        for (j in 0..b.size) {
            let d2 = Int64(b[j].toString().toInt64())
            let temp = prod[i + j] + d1 * d2 + carry
            prod[i + j] = temp % 10
            carry = temp / 10
        }
        prod[i + b.size] += carry
    }

    // build result
    var ans = StringBuilder()
    var leading = true
    for (k in (prod.size - 1)..(-1): -1) {
        if (leading && prod[k] == 0) { continue }
        leading = false
        ans.append(Char(prod[k] + 48))
    }
    return ans.toString()
}

