// Helper: reverse a string
func reverse(s: String): String {
    let r = ArrayList<Rune>()
    for (c in s.runes()) {
        r.insert(c, at: 0)
    }
    String(r.toRuneArray())
}

// Helper: trim leading zeros
func trimLeadingZeros(s: String): String {
    let runes = s.toRuneArray()
    var start = 0
    while (start < runes.size && runes[start] == r'0') {
        start += 1
    }
    if (start == runes.size) {
        return "0"
    }
    String(runes[start..])
}

class BigNumCalculator {
    public static func add(num1: String, num2: String): String {
        let a = reverse(num1)
        let b = reverse(num2)
        let res = ArrayList<Rune>()
        var carry = 0
        let maxLen = a.toRuneArray().size > b.toRuneArray().size ? a.toRuneArray().size : b.toRuneArray().size
        for (i in 0..maxLen) {
            let da = i < a.toRuneArray().size ? Int64(a.toRuneArray()[i].toString()) : 0
            let db = i < b.toRuneArray().size ? Int64(b.toRuneArray()[i].toString()) : 0
            let sum = da + db + carry
            carry = sum / 10
            res.add(Rune((sum % 10).toString()))
        }
        if (carry > 0) {
            res.add(Rune(carry.toString()))
        }
        trimLeadingZeros(reverse(String(res.toRuneArray())))
    }

    public static func subtract(num1: String, num2: String): String {
        let neg = false
        let (a, b) = if (num1.size < num2.size || (num1.size == num2.size && num1 < num2)) {
            neg = true
            (num2, num1)
        } else {
            (num1, num2)
        }
        let ra = reverse(a)
        let rb = reverse(b)
        let res = ArrayList<Rune>()
        var borrow = 0
        for (i in 0..ra.toRuneArray().size) {
            let da = Int64(ra.toRuneArray()[i].toString())
            let db = i < rb.toRuneArray().size ? Int64(rb.toRuneArray()[i].toString()) : 0
            var diff = da - db - borrow
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            res.add(Rune(diff.toString()))
        }
        let raw = trimLeadingZeros(reverse(String(res.toRuneArray())))
        if (neg && raw != "0") {
            "-${raw}"
        } else {
            raw
        }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }
        let a = num1.toRuneArray()
        let b = num2.toRuneArray()
        var res = Array<Int64>(a.size + b.size, item: 0)
        for (i in 0..a.size) {
            for (j in 0..b.size) {
                let prod = Int64(a[a.size - 1 - i].toString()) * Int64(b[b.size - 1 - j].toString())
                res[i + j] += prod
                res[i + j + 1] += res[i + j] / 10
                res[i + j] = res[i + j] % 10
            }
        }
        let out = ArrayList<Rune>()
        var leading = true
        for (i in 0..res.size) {
            let digit = res[res.size - 1 - i]
            if (leading && digit == 0) {
                continue
            }
            leading = false
            out.add(Rune(digit.toString()))
        }
        String(out.toRuneArray())
    }
}

