class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let a = num1.reversed()
        let b = num2.reversed()
        var carry = 0
        var res = ArrayList<Rune>([])
        let len = max(a.size, b.size)
        for (i in 0..len) {
            let d1 = if (i < a.size) { Int64(a[i].toString().toInt64()) } else { 0 }
            let d2 = if (i < b.size) { Int64(b[i].toString().toInt64()) } else { 0 }
            let sum = d1 + d2 + carry
            res.add(Rune((sum % 10 + 48).toRune()))
            carry = sum / 10
        }
        if (carry > 0) {
            res.add(Rune((carry + 48).toRune()))
        }
        return String(res.toArray().reversed())
    }

    public static func subtract(num1: String, num2: String): String {
        let neg = num2.size > num1.size || (num2.size == num1.size && num2 > num1)
        let (a, b) = if (neg) { (num2.reversed(), num1.reversed()) } else { (num1.reversed(), num2.reversed()) }
        var borrow = 0
        var res = ArrayList<Rune>([])
        for (i in 0..a.size) {
            let d1 = Int64(a[i].toString().toInt64())
            let d2 = if (i < b.size) { Int64(b[i].toString().toInt64()) } else { 0 }
            var sub = d1 - d2 - borrow
            borrow = 0
            if (sub < 0) {
                sub += 10
                borrow = 1
            }
            res.add(Rune((sub + 48).toRune()))
        }
        while (res.size > 1 && res[res.size - 1] == r'0') {
            res.remove(at: res.size - 1)
        }
        let ans = String(res.toArray().reversed())
        return if (neg && ans != "0") { "-${ans}" } else { ans }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") { return "0" }
        let a = num1.reversed()
        let b = num2.reversed()
        var prod = Array<Int64>([0] * (a.size + b.size))
        for (i in 0..a.size) {
            let d1 = Int64(a[i].toString().toInt64())
            var carry = 0
            for (j in 0..b.size) {
                let d2 = Int64(b[j].toString().toInt64())
                prod[i + j] += d1 * d2 + carry
                carry = prod[i + j] / 10
                prod[i + j] %= 10
            }
            prod[i + b.size] += carry
        }
        var res = ArrayList<Rune>([])
        var leading = true
        for (d in prod.reversed()) {
            if (leading && d == 0) { continue }
            leading = false
            res.add(Rune((d + 48).toRune()))
        }
        return String(res.toArray())
    }
}

