class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let a = num1.toRuneArray()
        let b = num2.toRuneArray()
        var i = a.size - 1
        var j = b.size - 1
        var carry = 0
        let res = ArrayList<Rune>()

        while (i >= 0 || j >= 0 || carry > 0) {
            let da = if (i >= 0) { Int64(a[i].toString().toInt64()) } else { 0 }
            let db = if (j >= 0) { Int64(b[j].toString().toInt64()) } else { 0 }
            let sum = da + db + carry
            carry = sum / 10
            res.add(Rune((sum % 10).toString()[0]))
            i -= 1
            j -= 1
        }

        let ans = ArrayList<Rune>()
        for (k in res.size - 1..0:-1) {
            ans.add(res[k])
        }
        String(ans.toArray())
    }

    public static func subtract(num1: String, num2: String): String {
        let neg = isLarger(num2, num1)
        let (larger, smaller) = if (neg) { (num2, num1) } else { (num1, num2) }
        let a = larger.toRuneArray()
        let b = smaller.toRuneArray()
        var i = a.size - 1
        var j = b.size - 1
        var borrow = 0
        let res = ArrayList<Rune>()

        while (i >= 0) {
            let da = Int64(a[i].toString().toInt64())
            let db = if (j >= 0) { Int64(b[j].toString().toInt64()) } else { 0 }
            var diff = da - db - borrow
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            res.add(Rune(diff.toString()[0]))
            i -= 1
            j -= 1
        }

        let ans = ArrayList<Rune>()
        var lead = true
        for (k in res.size - 1..0:-1) {
            if (lead && res[k] == r'0') { continue }
            lead = false
            ans.add(res[k])
        }
        if (ans.size == 0) { return "0" }
        let raw = String(ans.toArray())
        if (neg) { "-${raw}" } else { raw }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") { return "0" }
        let a = num1.toRuneArray()
        let b = num2.toRuneArray()
        let m = a.size
        let n = b.size
        let prod = Array<Int64>(m + n, item: 0)

        for (i in m - 1..0:-1) {
            let da = Int64(a[i].toString().toInt64())
            var carry = 0
            for (j in n - 1..0:-1) {
                let db = Int64(b[j].toString().toInt64())
                let sum = da * db + prod[i + j + 1] + carry
                prod[i + j + 1] = sum % 10
                carry = sum / 10
            }
            prod[i] += carry
        }

        let ans = ArrayList<Rune>()
        var lead = true
        for (v in prod) {
            if (lead && v == 0) { continue }
            lead = false
            ans.add(Rune(v.toString()[0]))
        }
        String(ans.toArray())
    }

    private static func isLarger(a: String, b: String): Bool {
        if (a.size != b.size) { return a.size > b.size }
        let ra = a.toRuneArray()
        let rb = b.toRuneArray()
        for (i in 0..ra.size) {
            if (ra[i] != rb[i]) { return ra[i] > rb[i] }
        }
        false
    }
}

