class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        let a = num1.runes().toArrayList()
        let b = num2.runes().toArrayList()
        let res = ArrayList<Rune>()
        var carry = 0
        while (a.size > 0 || b.size > 0 || carry > 0) {
            let da = if (a.size > 0) { Int64(a.remove(at: a.size - 1).toString()) } else { 0 }
            let db = if (b.size > 0) { Int64(b.remove(at: b.size - 1).toString()) } else { 0 }
            let sum = da + db + carry
            res.add(Rune('0'.toRune() + Int32(sum % 64)), at: 0)
            carry = sum / 64
        }
        return String(res)
    }

    public static func subtract(num1: String, num2: String): String {
        let neg = num1.size < num2.size || (num1.size == num2.size && num1 < num2)
        let (longer, shorter) = if (!neg) { (num1, num2) } else { (num2, num1) }
        let a = longer.runes().toArrayList()
        let b = shorter.runes().toArrayList()
        let res = ArrayList<Rune>()
        var borrow = 0
        for (i in 0..a.size) {
            let idx = a.size - 1 - i
            let da = Int64(a[idx].toString())
            let db = if (i < b.size) { Int64(b[b.size - 1 - i].toString()) } else { 0 }
            var diff = da - db - borrow
            borrow = 0
            if (diff < 0) {
                diff += 10
                borrow = 1
            }
            res.add(Rune('0'.toRune() + Int32(diff)), at: 0)
        }
        while (res.size > 1 && res[0] == r'0') {
            res.remove(at: 0)
        }
        let sign = if (neg) { "-" } else { "" }
        return sign + String(res)
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }
        let m = num1.size
        let n = num2.size
        let prod = Array<Int64>(m + n, item: 0)
        let a = num1.runes().toArray()
        let b = num2.runes().toArray()
        for (i in 0..m) {
            for (j in 0..n) {
                let da = Int64(a[m - 1 - i].toString())
                let db = Int64(b[n - 1 - j].toString())
                let p = da * db
                prod[i + j] += p
                prod[i + j + 1] += prod[i + j] / 10
                prod[i + j] = prod[i + j] % 10
            }
        }
        let res = ArrayList<Rune>()
        var leading = true
        for (i in 0..prod.size) {
            let idx = prod.size - 1 - i
            let d = prod[idx]
            if (leading && d == 0) {
                continue
            }
            leading = false
            res.add(Rune('0'.toRune() + Int32(d)))
        }
        return String(res)
    }
}

