// helpers: two private static functions to reverse a Rune list and to strip leading zeros
class BigNumCalculator {
    // reverse rune list in place
    private static func reverse(runes: ArrayList<Rune>): Unit {
        var i = 0
        var j = runes.size - 1
        while (i < j) {
            let tmp = runes[i]
            runes[i] = runes[j]
            runes[j] = tmp
            i += 1
            j -= 1
        }
    }

    // drop leading zeros, return "0" if all zeros
    private static func stripLeadingZeros(runes: ArrayList<Rune>): String {
        var leading = 0
        while (leading < runes.size && runes[leading] == r'0') {
            leading += 1
        }
        if (leading == runes.size) {
            return "0"
        }
        let res = StringBuilder()
        for (i in leading..runes.size) {
            res.append(runes[i])
        }
        res.toString()
    }

    public static func add(num1: String, num2: String): String {
        let a = ArrayList<Rune>(num1.runes())
        let b = ArrayList<Rune>(num2.runes())
        reverse(a)
        reverse(b)
        let maxLen = a.size > b.size ? a.size : b.size
        var carry = 0
        let res = ArrayList<Rune>()
        for (i in 0..maxLen) {
            let da = i < a.size ? (a[i].toInt64() - 48) : 0
            let db = i < b.size ? (b[i].toInt64() - 48) : 0
            let sum = da + db + carry
            carry = sum / 10
            res.add(Rune((sum % 10) + 48))
        }
        if (carry > 0) {
            res.add(Rune(carry + 48))
        }
        reverse(res)
        stripLeadingZeros(res)
    }

    public static func subtract(num1: String, num2: String): String {
        // determine sign: if num1 < num2, swap and remember negative result
        var neg = false
        var a = num1
        var b = num2
        if (a.size < b.size || (a.size == b.size && a < b)) {
            neg = true
            let tmp = a
            a = b
            b = tmp
        }
        let ar = ArrayList<Rune>(a.runes())
        let br = ArrayList<Rune>(b.runes())
        reverse(ar)
        reverse(br)
        var borrow = 0
        let res = ArrayList<Rune>()
        for (i in 0..ar.size) {
            let da = ar[i].toInt64() - 48
            let db = (i < br.size ? br[i].toInt64() - 48 : 0) + borrow
            var diff = da - db
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            res.add(Rune(diff + 48))
        }
        reverse(res)
        let stripped = stripLeadingZeros(res)
        if (neg && stripped != "0") {
            "-${stripped}"
        } else {
            stripped
        }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }
        let a = ArrayList<Rune>(num1.runes())
        let b = ArrayList<Rune>(num2.runes())
        reverse(a)
        reverse(b)
        let resSize = a.size + b.size
        var res = ArrayList<Int64>()
        for (i in 0..resSize) {
            res.add(0)
        }
        for (i in 0..a.size) {
            let da = a[i].toInt64() - 48
            var carry = 0
            for (j in 0..b.size) {
                let db = b[j].toInt64() - 48
                let prod = da * db + res[i + j] + carry
                res[i + j] = prod % 10
                carry = prod / 10
            }
            res[i + b.size] += carry
        }
        // convert back to runes, skipping leading zeros
        let runeRes = ArrayList<Rune>()
        var start = resSize - 1
        while (start >= 0 && res[start] == 0) {
            start -= 1
        }
        for (i in 0..start + 1) {
            runeRes.add(Rune(res[start - i] + 48))
        }
        stripLeadingZeros(runeRes)
    }
}

