class BigNumCalculator {

    // Helper: compare two numeric strings (returns -1, 0, 1)
    private static func cmp(a: String, b: String): Int64 {
        if (a.size != b.size) {
            return a.size < b.size ? -1 : 1
        }
        for (i in 0..a.size) {
            if (a[i] != b[i]) {
                return a[i] < b[i] ? -1 : 1
            }
        }
        return 0
    }

    // Helper: remove leading zeros
    private static func stripZeros(s: String): String {
        let firstNonZero = 0
        while (firstNonZero < s.size && s[firstNonZero] == r'0') {
            firstNonZero += 1
        }
        if (firstNonZero == s.size) {
            return "0"
        }
        return s.substring(firstNonZero, s.size - firstNonZero)
    }

    // Add two non-negative numeric strings
    private static func addPos(a: String, b: String): String {
        let res = ArrayList<Rune>([])
        var carry = 0
        var i = a.size - 1
        var j = b.size - 1
        while (i >= 0 || j >= 0 || carry > 0) {
            let da = if (i >= 0) { Int64(a[i].code - r'0'.code) } else { 0 }
            let db = if (j >= 0) { Int64(b[j].code - r'0'.code) } else { 0 }
            let sum = da + db + carry
            carry = sum / 10
            res.add(Rune(sum % 10 + r'0'.code))
            i -= 1
            j -= 1
        }
        var ans = ""
        for (k in res.size - 1..-1:-1) {
            ans = ans + String(res[k])
        }
        stripZeros(ans)
    }

    // Subtract two non-negative numeric strings (a >= b)
    private static func subPos(a: String, b: String): String {
        let res = ArrayList<Rune>([])
        var borrow = 0
        var i = a.size - 1
        var j = b.size - 1
        while (i >= 0) {
            let da = Int64(a[i].code - r'0'.code) - borrow
            let db = if (j >= 0) { Int64(b[j].code - r'0'.code) } else { 0 }
            borrow = 0
            var diff = da - db
            if (diff < 0) {
                diff += 10
                borrow = 1
            }
            res.add(Rune(diff + r'0'.code))
            i -= 1
            j -= 1
        }
        var ans = ""
        for (k in res.size - 1..-1:-1) {
            ans = ans + String(res[k])
        }
        stripZeros(ans)
    }

    public static func add(num1: String, num2: String): String {
        let neg1 = num1[0] == r'-'
        let neg2 = num2[0] == r'-'
        let a = if (neg1) { num1.substring(1, num1.size - 1) } else { num1 }
        let b = if (neg2) { num2.substring(1, num2.size - 1) } else { num2 }

        if (neg1 == neg2) {
            let sum = addPos(a, b)
            if (neg1 && sum != "0") {
                "-" + sum
            } else {
                sum
            }
        } else {
            let cmp_ab = cmp(a, b)
            if (cmp_ab == 0) {
                "0"
            } else if (cmp_ab > 0) {
                let diff = subPos(a, b)
                if (neg1) { "-" + diff } else { diff }
            } else {
                let diff = subPos(b, a)
                if (neg2) { "-" + diff } else { diff }
            }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        let neg2 = num2[0] == r'-'
        let alt = if (neg2) { num2.substring(1, num2.size - 1) } else { "-" + num2 }
        add(num1, alt)
    }

    public static func multiply(num1: String, num2: String): String {
        let neg1 = num1[0] == r'-'
        let neg2 = num2[0] == r'-'
        let a = if (neg1) { num1.substring(1, num1.size - 1) } else { num1 }
        let b = if (neg2) { num2.substring(1, num2.size - 1) } else { num2 }

        if (a == "0" || b == "0") {
            return "0"
        }

        let res = ArrayList<Int64>(Array<Int64>(a.size + b.size, { _ => 0 }))

        for (i in a.size - 1..-1:-1) {
            let da = Int64(a[i].code - r'0'.code)
            var carry = 0
            for (j in b.size - 1..-1:-1) {
                let db = Int64(b[j].code - r'0'.code)
                let idx = i + j + 1
                let prod = da * db + res[idx] + carry
                carry = prod / 10
                res[idx] = prod % 10
            }
            res[i] = res[i] + carry
        }

        var ans = ""
        var lead = true
        for (v in res) {
            if (lead && v == 0) {
                continue
            }
            lead = false
            ans = ans + String(Rune(v + r'0'.code))
        }

        let sign = if (neg1 != neg2) { "-" } else { "" }
        sign + ans
    }
}

