class BinaryDataProcessor {

    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = ""
        for (c in this.binary_string) {
            if (c == '0' || c == '1') {
                cleaned = cleaned + "${c}"
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let total = Float64(this.binary_string.size)
        var zeros = 0.0
        for (c in this.binary_string) {
            if (c == '0') {
                zeros += 1.0
            }
        }
        let ones = total - zeros
        let map = HashMap<String, Float64>()
        map.add("Zeroes", zeros / total)
        map.add("Ones", ones / total)
        map.add("Bit length", total)
        return map
    }

    public func convert_to_ascii(): String {
        var result = ""
        let n = this.binary_string.size
        var i = 0
        while (i + 8 <= n) {
            let byteStr = this.binary_string[i..i+8]
            let byte = Int64.parse(byteStr, radix: 2)
            result = result + "${Rune(byte)}"
            i += 8
        }
        return result
    }

    public func convert_to_utf8(): String {
        // Same implementation as ASCII for this 8-bit-clean input
        return this.convert_to_ascii()
    }
}

