        map["Ones"]   = ones.toFloat64()  / len.toFloat64()
        map["Bit length"] = len.toFloat64()
        return map
    }

    public func convert_to_ascii(): String {
        return this.binary_to_string(8)
    }

    public func convert_to_utf8(): String {
        return this.binary_to_string(8)
    }

    private func binary_to_string(bitsPerChar: Int64): String {
        let chars = ArrayList<Rune>()
        let len = this.binary_string.size
        var i = 0
        while (i + bitsPerChar <= len) {
            let chunk = this.binary_string[i..i + bitsPerChar]
            let num = Int64.parse(chunk, radix: 2)
            chars.add(Rune.fromInt(num))
            i += bitsPerChar
        }
        return String.fromRunes(chars)
    }
}

