        let runes = this.binary_string.toRuneArray()
        var i = 0
        while (i + 8 <= runes.size) {
            var byte: UInt8 = 0
            for (j in 0..8) {
                byte = byte * 2 + (if (runes[i + j] == r'1') { 1 } else { 0 })
            }
            bytes.add(byte)
            i += 8
        }
        return String.fromUtf8(bytes)
    }

    public func convert_to_utf8(): String {
        return this.convert_to_ascii()
    }
}

