public func calculate(expression: String): Option<Float64> {
    let operand_stack  = ArrayList<Float64>()
    let operator_stack = ArrayList<String>()
    let i = 0
    let n = expression.size

    while (i < n) {
        let c = expression[i]
        if (c == ' ') {
            i += 1
            continue
        }
        if (c >= '0' && c <= '9' || c == '.') {
            var j = i
            while (j < n && ((expression[j] >= '0' && expression[j] <= '9') || expression[j] == '.')) {
                j += 1
            }
            let num = Float64.parse(expression[i..j]).getOrThrow()
            operand_stack.add(num)
            i = j
            continue
        }
        if (c == '(') {
            operator_stack.add("(")
            i += 1
            continue
        }
        if (c == ')') {
            while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
            }
            if (operator_stack.size == 0) { return None<Float64> }
            operator_stack.remove(at: operator_stack.size - 1) // pop '('
            i += 1
            continue
        }
        // operator
        let op = String(c)
        while (operator_stack.size > 0 && precedence(operator_stack[operator_stack.size - 1]) >= precedence(op)) {
            (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
        }
        operator_stack.add(op)
        i += 1
    }

    while (operator_stack.size > 0) {
        if (operator_stack[operator_stack.size - 1] == "(") { return None<Float64> }
        (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
    }
    if (operand_stack.size != 1) { return None<Float64> }
