public func isDigit(c: Rune): Bool {
    return c >= r'0' && c <= r'9'
}

public func parseNumber(expr: String, offset: Int64): (Float64, Int64) {
    var i = offset
    var number = 0.0
    var frac = 0.1
    var isFrac = false
    while (i < expr.size) {
        let c = expr[i]
        if (!isDigit(c) && c != r'.') {
            break
        }
        if (c == r'.') {
            isFrac = true
        } else if (!isFrac) {
            number = number * 10.0 + Float64(Int64(c) - Int64(r'0'))
        } else {
            number = number + Float64(Int64(c) - Int64(r'0')) * frac
            frac = frac * 0.1
        }
        i = i + 1
    }
    return (number, i)
}

