        var i = 0
        let operand_stack = ArrayList<Float64>([])
        let operator_stack = ArrayList<String>([])

        while (i < n) {
            let c = expression[i]
            if (c == r' ') {
                i = i + 1
                continue
            }
            if (isDigit(c) || c == r'.') {
                let (num, next) = parseNumber(expression, i)
                operand_stack.add(num)
                i = next
                continue
            }
            if (c == r'+' || c == r'-' || c == r'*' || c == r'/' || c == r'^') {
                let op = String(c)
                while (operator_stack.size > 0 &&
                       precedence(operator_stack[operator_stack.size - 1]) >= precedence(op)) {
                    (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
                }
                operator_stack.add(op)
                i = i + 1
                continue
            }
            return None<Float64>
        }

        while (operator_stack.size > 0) {
            (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
        }

        if (operand_stack.size != 1) {
            return None<Float64>
        } else {
            return Some<Float64>(operand_stack[0])
        }
