class Calculator {
    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let tokens = tokenize(expression)
        var operandStack = ArrayList<Float64>()
        var operatorStack = ArrayList<String>()

        for (token in tokens) {
            match (isNumber(token)) {
                case true  => operandStack.add(Float64.parse(token))
                case false => {
                    if (token == "(") {
                        operatorStack.add(token)
                    } else if (token == ")") {
                        while (operatorStack.size > 0 && operatorStack[operatorStack.size - 1] != "(") {
                            let (os, op) = apply_operator(operandStack, operatorStack)
                            operandStack = os
                            operatorStack = op
                        }
                        if (operatorStack.size > 0) {
                            operatorStack.remove(at: operatorStack.size - 1)
                        }
                    } else {
                        while (operatorStack.size > 0 && precedence(operatorStack[operatorStack.size - 1]) >= precedence(token)) {
                            let (os, op) = apply_operator(operandStack, operatorStack)
                            operandStack = os
                            operatorStack = op
                        }
                        operatorStack.add(token)
                    }
                }
            }
        }

        while (operatorStack.size > 0) {
            let (os, op) = apply_operator(operandStack, operatorStack)
            operandStack = os
            operatorStack = op
        }

        if (operandStack.size == 1) {
            return Some<Float64>(operandStack[0])
        } else {
            return None<Float64>
        }
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" | "-" => 1
            case "*" | "/" => 2
            case "^"       => 3
            case _         => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let right = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let left = operand_stack[operand_stack.size - 1]
        operand_stack.remove(at: operand_stack.size - 1)
        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)

        let fn = operators[op]
        let res = fn(left, right)
        operand_stack.add(res)
        (operand_stack, operator_stack)
    }

    private func tokenize(expr: String): ArrayList<String> {
        let tokens = ArrayList<String>()
        var i = 0
        let runes = expr.toRuneArray()
        while (i < runes.size) {
            let c = runes[i]
            if (c == r' ' || c == r'\t') {
                i++
                continue
            }
            if (c == r'+' || c == r'-' || c == r'*' || c == r'/' || c == r'^' || c == r'(' || c == r')') {
                tokens.add(String([c]))
                i++
            } else if (c >= r'0' && c <= r'9') {
                var num = ArrayList<Rune>()
                while (i < runes.size && ((runes[i] >= r'0' && runes[i] <= r'9') || runes[i] == r'.')) {
                    num.add(runes[i])
                    i++
                }
                tokens.add(String(num))
            } else {
                i++
            }
        }
        tokens
    }

    private func isNumber(s: String): Bool {
        var hasDot = false
        for (c in s.runes()) {
            if (c == r'.') {
                if (hasDot) return false
                hasDot = true
            } else if (c < r'0' || c > r'9') {
                return false
            }
        }
        true
    }
}

