        let op = operator_stack[operator_stack.size - 1]
        operator_stack.remove(at: operator_stack.size - 1)

        let f = operators.get(op).getOrThrow()
        let res = f(lhs, rhs)
        operand_stack.add(res)
        (operand_stack, operator_stack)
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable
import std.collection.ArrayList
import std.collection.HashMap

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        var operand_stack = ArrayList<Float64>()
        var operator_stack = ArrayList<String>()
        var i = 0
        let n = expression.size
        while (i < n) {
            let c = expression[i]
            if (c == ' ') {
                i += 1
                continue
            }
            if (c == '(') {
                operator_stack.add("(")
                i += 1
                continue
            }
            if (c == ')') {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
                }
                operator_stack.remove(at: operator_stack.size - 1)
                i += 1
                continue
            }
            if (c >=48 && c <=57 || c ==46) {
                var value = 0.0
                var dot = false
                var scale = 0.1
                while (i < n && ((c >=48 && c <=57) || c ==46)) {
                    if (c ==46) {
                        dot = true
                    } else {
                        let digit = (c - 48).toFloat64()
                        if (!dot) {
                            value = value * 10.0 + digit
                        } else {
                            value = value + digit * scale
                            scale = scale * 0.1
                        }
                    }
                    i += 1
                    if (i < n) {
                        c = expression[i]
                    }
                }
                operand_stack.add(value)
                continue
            }
            let op = String([c])
            while (operator_stack.size > 0 && 
                   precedence(operator_stack[operator_stack.size - 1]) >= precedence(op)) {
                (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
            }
            operator_stack.add(op)
            i += 1
        }
        while (operator_stack.size > 0) {
            (operand_stack, operator_stack) = apply_operator(operand_stack, operator_stack)
        }
        if (operand_stack.size == 1) {
            return Some<Float64>(operand_stack[0])
        }
        return None<Float64>
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _   => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack.remove(at: operator_stack.size - 1)
        let right = operand_stack.remove(at: operand_stack.size - 1)
        let left = operand_stack.remove(at: operand_stack.size - 1)
        let op_func = operators[op]
        let result = op_func(left, right)
        operand_stack.add(result)
        (operand_stack, operator_stack)
    }
}

