    public init() { this.events = ArrayList<Event>() }

    public func add_event(event: Event): Unit {
        events.add(event)
    }

    public func remove_event(event: Event): Unit {
        for (i in 0..events.size) {
            if (events[i] == event) {
                events.remove(at: i)
                break
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let out = ArrayList<Event>()
        for (e in events) {
            if (e.date == date) { out.add(e) }
        }
        return out
    }

