        let dayStart = DateTime.of(year: date.year,
                                   month: date.month,
                                   dayOfMonth: date.dayOfMonth,
                                   hour: 0, minute: 0)
        let dayEnd   = DateTime.of(year: date.year,
                                   month: date.month,
                                   dayOfMonth: date.dayOfMonth + 1,
                                   hour: 0, minute: 0)
        let slots = ArrayList<(DateTime, DateTime)>()
        var current = dayStart

        let todayEvents = this.get_events(date)
        sort(todayEvents, key: { e: Event => e.start_time })

        for (e in todayEvents) {
            if (current < e.start_time) {
                slots.add((current, e.start_time))
            }
            if (e.end_time > current) { current = e.end_time }
        }
