        let now = DateTime.now()
        let future = ArrayList<Event>()
        for (e in events) {
            if (e.start_time >= now) { future.add(e) }
        }
        sort(future, key: { ev: Event => ev.start_time })
        let out = ArrayList<Event>()
        for (i in 0..min(num_events, future.size)) {
            out.add(future[i])
        }
        return out
    }
