class CamelCaseMap {

    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        let camel = CamelCaseMap._to_camel_case(key)
        match (_data.get(camel)) {
            case Some(v) => v
            case None    => throw Exception("Key not found")
        }
    }

    public func __setitem__(key: String, value: Any): Unit {
        let camel = CamelCaseMap._to_camel_case(key)
        _data.add(camel, value)
