/* Converts an underscore separated string to camelCase. */
func toCamelCase(s: String): String {
    let runes = s.toRuneArray()
    var out = Array<Rune>()
    var upperNext = false

    for (r in runes) {
        if (r == '_') {
            upperNext = true
        } else {
            if (upperNext) {
                out.append((r >= r'a' && r <= r'z') ? (r - r'a' + r'A') : r)
                upperNext = false
            } else {
                out.append(r)
            }
        }
    }
    String.fromRuneArray(out)
}

/* A small helper to normalise keys: String keys are camel-cased,
   everything else is returned as-is. */
func normaliseKey(key: Any): Any {
    match (key) {
        case s: String => toCamelCase(s)
        case _        => key
    }
}

class CamelCaseMap {
    let data: HashMap<Any, Any>          // stores camel-cased keys

    public init() { data = HashMap<Any, Any>() }

    public func get(key: Any): Any {                           // __getitem__
        let k = normaliseKey(key)
        data.get(k).getOrThrow()
    }

    public func put(key: Any, value: Any): Unit {              // __setitem__
        let k = normaliseKey(key)
        data.add(k, value)
    }

    public func remove(key: Any): Unit {                       // __delitem__
        let k = normaliseKey(key)
        data.remove(k)
    }

    public func size(): Int64 {                                // __len__
        data.size
    }

    /* exposed helpers for tests */
    public func _convertKey(key: Any): Any { normaliseKey(key) }

    public static func _toCamelCase(key: String): String { toCamelCase(key) }
}

