class ChandrasekharSieve {
    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (n < 2) {
            return ArrayList<Int64>()
        }
        var sieve = ArrayList<Bool>([])
        for (i in 0..n+1) {
            sieve.add(true)
        }
        sieve[0] = false
        sieve[1] = false

        let limit = Int64(sqrt(Float64(n))).toInt64()
        for (p in 2..limit+1) {
            if (sieve[p]) {
                for (multiple in p*p..n+1:p) {
                    sieve[multiple] = false
                }
            }
        }

        var result = ArrayList<Int64>()
        for (i in 2..n+1) {
            if (sieve[i]) {
                result.add(i)
            }
        }
        return result
    }

    public func get_primes(): ArrayList<Int64> {
        return primes
    }
}

