class ChandrasekharSieve {

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (n < 2) {
            return ArrayList<Int64>()
        }

        var is_prime = ArrayList<Bool>([])
        for (i in 0..n+1) {
            is_prime.add(true)
        }
        is_prime[0] = false
        is_prime[1] = false

        for (p in 2..n+1) {
            if (is_prime[p]) {
                var multiple = p * p
                while (multiple <= n) {
                    is_prime[multiple] = false
                    multiple += p
                }
            }
