/* ---------- helper: parse "yyyy/MM/dd HH:mm" into DateTime ---------- */
func parseDateTime(dt: String): DateTime {
    let parts = dt.split(" ")
    let date  = parts[0].split("/")
    let time  = parts[1].split(":")
    let year  = Int64.parse(date[0])
    let month = Int64.parse(date[1])
    let day   = Int64.parse(date[2])
    let hour  = Int64.parse(time[0])
    let min   = Int64.parse(time[1])
    return DateTime(year, month, day, hour, min, 0, 0)
}

/* ---------- helper: overlap test (inclusive boundaries) ---------- */
func hasOverlap(aStart: String, aEnd: String,
                bStart: String, bEnd: String): Bool {
    let a1 = parseDateTime(aStart)
    let a2 = parseDateTime(aEnd)
    let b1 = parseDateTime(bStart)
    let b2 = parseDateTime(bEnd)
    return !(a2 <= b1 || a1 >= b2)
}

class Classroom {
    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if (!courses.contains(course)) {
            courses.add(course)
        }
    }

    public func remove_course(course: Course): Unit {
        let idx = courses.indexOf(course)
        if (idx >= 0) {
            courses.remove(at: idx)
        }
    }

    public func is_free_at(check_time: String): Bool {
        let t = parseDateTime(check_time)
        for (c in courses) {
            let start = parseDateTime(c.start_time)
            let end   = parseDateTime(c.end_time)
            if (t >= start && t < end) {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        for (c in courses) {
            if (hasOverlap(c.start_time, c.end_time,
                           new_course.start_time, new_course.end_time)) {
                return false
            }
        }
        return true
    }
}

