import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        for (s in this.students) {
            if (s["name"] == student["name"]) {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if (!this.students_registration_classes.contains(student_name)) {
            this.students_registration_classes.add(student_name, ArrayList<String>())
        }
        let classes = this.students_registration_classes[student_name]
        if (!classes.contains(class_name)) {
            classes.add(class_name)
        }
        classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let res = ArrayList<String>()
        for (s in this.students) {
            if (s["major"] == major) {
                res.add(s["name"])
            }
        }
        res
    }

    public func get_all_major(): ArrayList<String> {
        let res = ArrayList<String>()
        for (s in this.students) {
            let m = s["major"]
            if (!res.contains(m)) {
                res.add(m)
            }
        }
        res
    }

    public func get_most_popular_class_in_major(major: String): String {
        let classCount = HashMap<String, Int64>()
        for (s in this.students) {
            if (s["major"] == major) {
                let name = s["name"]
                if (this.students_registration_classes.contains(name)) {
                    for (cls in this.students_registration_classes[name]) {
                        if (classCount.contains(cls)) {
                            classCount[cls] = classCount[cls] + 1
                        } else {
                            classCount.add(cls, 1)
                        }
                    }
                }
            }
        }
        var maxCount = 0
        var popular = ""
        for (cls in classCount) {
            if (classCount[cls] > maxCount) {
                maxCount = classCount[cls]
                popular = cls
            }
        }
        popular
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student["name"] ?? ""
        for (s in this.students) {
            if (s["name"] == name) {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if (!this.students_registration_classes.contains(student_name)) {
            this.students_registration_classes[student_name] = ArrayList<String>()
        }
        let classes = this.students_registration_classes[student_name]
        if (!classes.contains(class_name)) {
            classes.add(class_name)
        }
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let res = ArrayList<String>()
        for (s in this.students) {
            if (s["major"] == major) {
                res.add(s["name"] ?? "")
            }
        }
        return res
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashMap<String, Int64>()
        for (s in this.students) {
            let m = s["major"] ?? ""
            majors[m] = 1
        }
        return ArrayList<String>(majors.keys)
    }

    public func get_most_popular_class_in_major(major: String): String {
        let majorStudents = this.get_students_by_major(major)
        let classCount = HashMap<String, Int64>()
        for (name in majorStudents) {
            let classes = this.students_registration_classes.get(name)
            match (classes) {
                case Some(c) =>
                    for (cls in c) {
                        let cnt = classCount.get(cls) ?? 0
                        classCount[cls] = cnt + 1
                    }
                case _ => continue
            }
        }
        var maxCount = 0
        var popular = ""
        for (kv in classCount) {
            if (kv.1 > maxCount) {
                maxCount = kv.1
                popular = kv.0
            }
        }
        return popular
    }
}

