import std.collection.ArrayList
import std.math.*

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) { return 0 }
        let num = factorial(n)
        let den = factorial(m) * factorial(n - m)
        return num / den
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (k in 1..n + 1) {
            total += count(n, k)
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        let current = ArrayList<String>()
        _select(0, m, current, result)
        return result
    }

    private func _select(start: Int64, m: Int64, current: ArrayList<String>, result: ArrayList<ArrayList<String>>): Unit {
        if (current.size == m) {
            result.add(ArrayList<String>(current))
            return
        }
        for (i in start..datas.size) {
            current.add(datas[i])
            _select(i + 1, m, current, result)
            current.remove(at: current.size - 1)
        }
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (k in 1..datas.size + 1) {
            let combos = select(k)
            for (c in combos) {
                result.add(c)
            }
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        if (resultIndex == resultList.size) {
            result.add(ArrayList<String>(resultList))
            return
        }
        for (i in dataIndex..datas.size - (resultList.size - resultIndex - 1)) {
            resultList[resultIndex] = datas[i]
            _select(i + 1, resultList, resultIndex + 1, result)
        }
    }
}

