class CombinationCalculator {
    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    /* n!/(m! (n-m)!) */
    public static func count(n: Int64, m: Int64): Int64 {
        CombinationCalculator.factorial(n) /
        (CombinationCalculator.factorial(m) * CombinationCalculator.factorial(n - m))
    }

    /* 2^n-1 */
    public static func count_all(n: Int64): Int64 {
        if (n > 62) {                      // 2^63-1 max
            return Int64.Max
        }
        var acc = 1
        for (i in 1..n + 1) {
            acc *= 2
        }
        acc - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let n = this.datas.size
        var result = ArrayList<ArrayList<String>>()
        var curr = ArrayList<String>()
        selectRec(0, m, curr, result)
        result
    }
    private func selectRec(pos: Int64,
                           m: Int64,
                           curr: ArrayList<String>,
                           result: ArrayList<ArrayList<String>>): Unit {
        if (curr.size == m) {
            result.add(ArrayList<String>(curr))
            return
        }
        let n = this.datas.size
        for (i in pos..n - (m - curr.size) + 1) {
            curr.add(this.datas[i])
            selectRec(i + 1, m, curr, result)
            curr.remove(at: curr.size - 1)
        }
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        var all = ArrayList<ArrayList<String>>()
        let n = this.datas.size
        for (k in 1..n + 1) {
            for (comb in select(k)) {
                all.add(ArrayList<String>(comb))
            }
        }
        all
    }

    public func _select(dataIndex: Int64,
                        resultList: ArrayList<String>,
                        resultIndex: Int64,
                        result: ArrayList<ArrayList<String>>): Unit {
        let m = resultList.size
        if (resultIndex == m) {
            result.add(ArrayList<String>(resultList))
            return
        }
        let last = this.datas.size - m + resultIndex
        for (j in dataIndex..last + 1) {
            resultList[resultIndex] = this.datas[j]
            _select(j + 1, resultList, resultIndex + 1, result)
        }
    }
}

