    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (k in 1..n + 1) {
            let c = count(n, k)
            if (total > Int64.Max - c) { return Int64.Max }
            total += c
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        let temp   = ArrayList<String>(Array<String>(m, repeat: ""))
        _select(0, temp, 0, result)
        return result
    }

