        let result = ArrayList<ArrayList<String>>()
        for (m in 1..datas.size + 1) {
            let part = select(m)
            for (comb in part) {
                result.append(comb)
            }
        }
        return result
    }

    public func _select(dataIndex: Int64,
                        resultList: ArrayList<String>,
                        resultIndex: Int64,
                        result: ArrayList<ArrayList<String>>): Unit {
        let m = resultList.size
        if (resultIndex == m) {
            result.append(ArrayList<String>(resultList))
            return
        }
        if (dataIndex >= datas.size) { return }
        // choose current element
        resultList[resultIndex] = datas[dataIndex]
        _select(dataIndex + 1, resultList, resultIndex + 1, result)
        // skip current element
        _select(dataIndex + 1, resultList, resultIndex, result)
    }
