        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) { return 0 }
        // C(n, m) = n! / (m! * (n-m)!)
        let num = factorial(n)
        let den = factorial(m) * factorial(n - m)
        return num / den
    }

    public static func count_all(n: Int64): Int64 {
        // sum_{k=1..n} C(n, k) = 2^n - 1
        var total: Int64 = 0
        for (k in 1..n + 1) {
            total += count(n, k)
            if (total < 0) { // overflow
                return Int64.Max
            }
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let res = ArrayList<ArrayList<String>>()
        let path = ArrayList<String>()
        dfs(0, m, path, res)
        return res
    }

    private func dfs(start: Int64, left: Int64, path: ArrayList<String>, res: ArrayList<ArrayList<String>>): Unit {
        if (left == 0) {
            res.add(path.clone())
            return
        }
        for (i in start..datas.size) {
            path.add(datas[i])
            dfs(i + 1, left - 1, path, res)
            path.remove(at: path.size - 1)
        }
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let res = ArrayList<ArrayList<String>>()
        for (k in 1..datas.size + 1) {
            let part = select(k)
            for (item in part) {
                res.add(item)
            }
        }
        return res
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        let m = resultList.size
        if (resultIndex == m) {
            result.add(resultList.clone())
            return
        }
        let maxStart = datas.size - (m - resultIndex)
        for (i in dataIndex..maxStart + 1) {
            resultList[resultIndex] = datas[i]
            _select(i + 1, resultList, resultIndex + 1, result)
        }
    }
