    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) { return 0 }
        // n! / (m!*(n-m)!)
        let nf = this.factorial(n)
        let mf = this.factorial(m)
        let nmf = this.factorial(n - m)
        return nf / (mf * nmf)
    }

    public static func count_all(n: Int64): Int64 {
        // sum choose(n,k) for k=1..n = (2^n)-1,
        // capped at Int64 max if overflow.
        try {
            var pow2 = 1
            var sum: Int64 = 0
            // (2^n)-1
            var res: Int64 = if (n >= 63) { Int64.Max } else { (1 << n) - 1 }
            res
        } catch (_) { Int64.Max }
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let res = ArrayList<ArrayList<String>>()
        let n = this.datas.size
        if (m < 0 || m > n) { return res }
        let comb = ArrayList<String>(Array<String>(m, repeat: ""))
        helper(0, 0, comb, res, m)
        res
    }
    func helper(idx: Int64, chosen: Int64, comb: ArrayList<String>,
                 res: ArrayList<ArrayList<String>>, m: Int64): Unit {
        let n = this.datas.size
        if (chosen == m) {
            res.add(ArrayList<String>(comb))
            return
        }
        for (i in idx..n) {
            comb[chosen] = this.datas[i]
            helper(i + 1, chosen + 1, comb, res, m)
        }
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let res = ArrayList<ArrayList<ArrayList<String>>>()
        for (k in 1..this.datas.size + 1) {
            res.add(this.select(k))
        }
        let flat = ArrayList<ArrayList<String>>()
        for (row in res) {
            flat.extend(row)
        }
        flat
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>,
                        resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        let target = resultList.size
        let n = this.datas.size
        if (resultIndex == target) {
            // reached wanted size
            result.add(ArrayList<String>(resultList))
            return
        }
        for (i in dataIndex..n - (target - resultIndex) + 1) {
            resultList[resultIndex] = this.datas[i]
            this._select(i + 1, resultList, resultIndex + 1, result)
        }
    }
}

