class CSVProcessor {
    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = FileSystem.open(file_name, "r")
        let title = ArrayList<String>()
        let data  = ArrayList<ArrayList<String>>()

        // read header (first line)
        let header_line = file.readln()
        let header_parts = header_line.split(",")
        for (part in header_parts) {
            title.add(part.strip())
        }

        // read data lines
        while (!file.isAtEnd()) {
            let line = file.readln()
            if (line.size == 0) { continue }
            let parts = line.split(",")
            let row = ArrayList<String>()
            for (part in parts) {
                row.add(part.strip())
            }
            data.add(row)
        }

        file.close()
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = FileSystem.open(file_name, "w")
        for (i in 0..data.size) {
            let row = data[i]
            let parts = ArrayList<String>()
            for (j in 0..row.size) {
                parts.add(row[j])
            }
            file.write(parts.join(","))
            if (i < data.size - 1) {
                file.write("\n")
            }
        }
        file.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        let new_data = ArrayList<ArrayList<String>>()

        for (row in data) {
            let new_row = ArrayList<String>()
            if (N < row.size) {
                let cell = row[N].upper()
                new_row.add(cell)
            }
            new_data.add(new_row)
        }

        let base_name = save_file_name.split(".csv")[0]
        let out_name = base_name + "_process.csv"
        write_csv(new_data, out_name)
        return 1
    }
}

