        let lines = content.split("\n")
        let title = ArrayList(lines[0].split(",").map({ s => s.trim() }))
        let data = ArrayList<ArrayList<String>>()
        for (i in 1..lines.size) {
            if (lines[i].size == 0) { continue }
            let fields = lines[i].split(",").map({ s => s.trim() })
            data.append(ArrayList(fields))
        }
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let sb = StringBuilder()
        for (row in data) {
            sb.append(join(row, ","))
            sb.append("\n")
        }
        try {
            File.writeText(file_name, sb.toString())
            return 1
        } catch (_) {
            return 0
        }
    }

    private func join(a: ArrayList<String>, sep: String): String {
        if (a.size == 0) { return "" }
        var res = a[0]
        for (i in 1..a.size) {
            res += sep + a[i]
        }
        return res
    }

    private func capitalize(s: String): String {
        let rus = s.trim().toUpperCase()
        return rus
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (origTitle, origData) = read_csv(save_file_name)
        let newTitle = ArrayList([origTitle[N]])
        let newData = ArrayList<ArrayList<String>>()
        for (row in origData) {
            let colVal = row[N]
            newData.append(ArrayList([capitalize(colVal)]))
        }
        let newName = save_file_name+"_process"
        return write_csv(ArrayList([newTitle]) + newData, newName)
    }
}

