class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File(file_name, mode: "r")
        let content = file.readLines()
        let title = split_line(content[0])
        let data = ArrayList<ArrayList<String>>()
        var i = 1
        while (i < content.size) {
            data.append(split_line(content[i]))
            i += 1
        }
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File(file_name, mode: "w")
            for (row in data) {
                var first = true
                for (cell in row) {
                    if (!first) {
                        file.write(",")
                    }
                    file.write(cell)
                    first = false
                }
                file.write("\n")
            }
            file.close()
            return 1
        } catch (_) {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, oldData) = read_csv(save_file_name)
        let newData = ArrayList<ArrayList<String>>()
        for (row in oldData) {
            let newRow = ArrayList<String>()
            newRow.append(capitalize(row[N]))
            newData.append(newRow)
        }
        let newFileName = save_file_name[0..save_file_name.lastIndexOf(".")] + "_process" + save_file_name[save_file_name.lastIndexOf(".")..]
        return write_csv(newData, newFileName)
    }

    private func split_line(line: String): ArrayList<String> {
        let parts = line.split(",")
        let result = ArrayList<String>()
        for (part in parts) {
            result.append(part)
        }
        return result
    }

    private func capitalize(s: String): String {
        let runes = s.toRuneArray()
        if (runes.size == 0) {
            return ""
        }
        let first = if (runes[0] == r'a') { r'A' }
                    else if (runes[0] == r'b') { r'B' }
                    else if (runes[0] == r'c') { r'C' }
                    else if (runes[0] == r'd') { r'D' }
                    else if (runes[0] == r'e') { r'E' }
                    else if (runes[0] == r'f') { r'F' }
                    else if (runes[0] == r'g') { r'G' }
                    else if (runes[0] == r'h') { r'H' }
                    else if (runes[0] == r'i') { r'I' }
                    else if (runes[0] == r'j') { r'J' }
                    else if (runes[0] == r'k') { r'K' }
                    else if (runes[0] == r'l') { r'L' }
                    else if (runes[0] == r'm') { r'M' }
                    else if (runes[0] == r'n') { r'N' }
                    else if (runes[0] == r'o') { r'O' }
                    else if (runes[0] == r'p') { r'P' }
                    else if (runes[0] == r'q') { r'Q' }
                    else if (runes[0] == r'r') { r'R' }
                    else if (runes[0] == r's') { r'S' }
                    else if (runes[0] == r't') { r'T' }
                    else if (runes[0] == r'u') { r'U' }
                    else if (runes[0] == r'v') { r'V' }
                    else if (runes[0] == r'w') { r'W' }
                    else if (runes[0] == r'x') { r'X' }
                    else if (runes[0] == r'y') { r'Y' }
                    else if (runes[0] == r'z') { r'Z' }
                    else { runes[0] }
        let buf = StringBuilder()
        buf.append(first)
        var i = 1
        while (i < runes.size) {
            buf.append(runes[i])
            i += 1
        }
        return buf.toString()
    }
}

