import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {
    public func mean(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        var sum: Float64 = 0.0
        for (x in data) {
            sum += x.toFloat64()
        }
        round(sum / data.size.toFloat64(), digits: 2)
    }

    public func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return round(sorted[(n - 1) / 2].toFloat64(), digits: 2)
        } else {
            let mid = (sorted[n / 2 - 1].toFloat64() + sorted[n / 2].toFloat64()) / 2.0
            return round(mid, digits: 2)
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        var freq = HashMap<Int64, Int64>()
        for (x in data) {
            let old = freq.get(x) ?? 0
            freq.add(x, old + 1)
        }
        var maxFreq: Int64 = 0
        for ((_, cnt) in freq) {
            if (cnt > maxFreq) {
                maxFreq = cnt
            }
        }
        var modes = ArrayList<Int64>()
        for ((v, cnt) in freq) {
            if (cnt == maxFreq) {
                modes.add(v)
            }
        }
        sort(modes)
        modes
    }
}

