        for (x in this.data) {
            sum += x
        }
        return sum
    }

    public func get_min(): Float64 {
        var minVal = this.data[0]
        for (x in this.data) {
            if (x < minVal) {
                minVal = x
            }
        }
        return minVal
    }

    public func get_max(): Float64 {
        var maxVal = this.data[0]
        for (x in this.data) {
            if (x > maxVal) {
                maxVal = x
            }
        }
        return maxVal
    }

    public func get_variance(): Float64 {
        let n = this.data.size
        if (n <= 1) {
            return 0.0
        }
        let mean = this.get_sum() / Float64(n)
        var sumSq = 0.0
        for (x in this.data) {
            let diff = x - mean
            sumSq += diff * diff
        }
        let v = sumSq / Float64(n - 1)
        return round(v * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        let v = this.get_variance()
        let s = sqrt(v)
        return round(s * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        let n = this.data.size
        if (n <= 1) {
            return 1.0
        }
        var sumX = 0.0
        var sumY = 0.0
        var sumXY = 0.0
        var sumX2 = 0.0
        var sumY2 = 0.0
        for (i in 0..n) {
            let x = this.data[i]
            let y = this.data[i]
            sumX += x
            sumY += y
            sumXY += x * y
            sumX2 += x * x
            sumY2 += y * y
        }
        let num = Float64(n) * sumXY - sumX * sumY
        let den = sqrt((Float64(n) * sumX2 - sumX * sumX) * (Float64(n) * sumY2 - sumY * sumY))
        if (den == 0.0) {
            return 1.0
        }
        return num / den
    }
}

