import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.sort.*

class DataStatistics4 {

    private static func mean(data: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        sum / data.size
    }

    private static func stdDev(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        var sum = 0.0
        for (x in data) {
            let d = x - m
            sum += d * d
        }
        sqrt(sum / data.size)
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        if (n != data2.size || n == 0) {
            return 0.0
        }
        let mean1 = mean(data1)
        let mean2 = mean(data2)
        var num = 0.0
        var den1 = 0.0
        var den2 = 0.0
        for (i in 0..n) {
            let dx = data1[i] - mean1
            let dy = data2[i] - mean2
            num += dx * dy
            den1 += dx * dx
            den2 += dy * dy
        }
        num / (sqrt(den1) * sqrt(den2))
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n <= 2) {
            return 0.0
        }
        let m = mean(data)
        let s = stdDev(data)
        var sum = 0.0
        for (x in data) {
            sum += (x - m) ** 3.0
        }
        sum / (n * (s ** 3.0))
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n <= 3) {
            return 0.0
        }
        let m = mean(data)
        let s = stdDev(data)
        var sum = 0.0
        for (x in data) {
            sum += (x - m) ** 4.0
        }
        sum / (n * (s ** 4.0)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coef = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let pdfList = ArrayList<Float64>()
        for (x in data) {
            let exponent = -0.5 * ((x - mu) / sigma) ** 2.0
            pdfList.add(coef * exp(exponent))
        }
        pdfList
    }
}

