class DataStatistics4 {
    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        if (n != data2.size || n == 0) {
            return 0.0
        }
        var sum1 = 0.0
        var sum2 = 0.0
        for (i in 0..n) {
            sum1 += data1[i]
            sum2 += data2[i]
        }
        let mean1 = sum1 / (n.toFloat64())
        let mean2 = sum2 / (n.toFloat64())
        var num = 0.0
        var den1 = 0.0
        var den2 = 0.0
        for (i in 0..n) {
            let dx = data1[i] - mean1
            let dy = data2[i] - mean2
            num += dx * dy
            den1 += dx * dx
            den2 += dy * dy
        }
        if (den1 == 0.0 || den2 == 0.0) {
            return 0.0
        }
        return num / (sqrt(den1) * sqrt(den2))
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 3) {
            return 0.0
        }
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / (n.toFloat64())
        var m2 = 0.0
        var m3 = 0.0
        for (x in data) {
            let d = x - mean
            m2 += d * d
            m3 += d * d * d
        }
        m2 = m2 / (n.toFloat64())
        let sd = sqrt(m2)
        if (sd == 0.0) {
            return 0.0
        }
        m3 = m3 / (n.toFloat64())
        return m3 / (sd * sd * sd)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 4) {
            return 0.0
        }
        var sum = 0.0
        for (x in data) {
            sum += x
        }
        let mean = sum / (n.toFloat64())
        var m2 = 0.0
        var m4 = 0.0
        for (x in data) {
            let d = x - mean
            let d2 = d * d
            m2 += d2
            m4 += d2 * d2
        }
        m2 = m2 / (n.toFloat64())
        if (m2 == 0.0) {
            return 0.0
        }
        m4 = m4 / (n.toFloat64())
        return m4 / (m2 * m2) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let res = ArrayList<Float64>()
        if (sigma <= 0.0) {
            for (_ in data) {
                res.add(0.0)
            }
            return res
        }
        let coef = 1.0 / (sqrt(2.0 * 3.141592653589793) * sigma)
        let denom = 2.0 * sigma * sigma
        for (x in data) {
            let d = x - mu
            let pdf = coef * exp(-(d * d) / denom)
            res.add(pdf)
        }
        return res
    }
}

