    }

    public static func stddev(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        var sum = 0.0
        for (v in data) {
            let d = v - m
            sum += d * d
        }
        return sqrt(sum / Float64(data.size))
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        if (n != data2.size || n == 0) {
            return 0.0
        }
        let m1 = mean(data1)
        let m2 = mean(data2)
        var num = 0.0
        var den1 = 0.0
        var den2 = 0.0
        for (i in 0..n) {
            let dx = data1[i] - m1
            let dy = data2[i] - m2
            num += dx * dy
            den1 += dx * dx
            den2 += dy * dy
        }
        return num / sqrt(den1 * den2)
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 3) {
            return 0.0
        }
        let m = mean(data)
        let s = stddev(data)
        var sum = 0.0
        for (v in data) {
            sum += pow((v - m) / s, 3.0)
        }
        return sum * Float64(n) / (Float64(n - 1) * Float64(n - 2))
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 4) {
            return 0.0
        }
        let m = mean(data)
        let s = stddev(data)
        var sum = 0.0
        for (v in data) {
            sum += pow((v - m) / s, 4.0)
        }
        let term = sum * Float64(n) * Float64(n + 1) / (Float64(n - 1) * Float64(n - 2) * Float64(n - 3))
        let adjust = 3.0 * Float64(n - 1) * Float64(n - 1) / (Float64(n - 2) * Float64(n - 3))
        return term - adjust
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let denom = 2.0 * sigma * sigma
        let out = ArrayList<Float64>([])
        for (x in data) {
            let diff = x - mu
