class DataStatistics4 {

    /* 计算样本均值 */
    private static func mean(data: ArrayList<Float64>): Float64 {
        var sum = 0.0
        for (x in data) { sum += x }
        return sum / data.size.toFloat64()
    }

    /* 计算样本标准差 */
    private static func stdDev(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        var sq = 0.0
        for (x in data) {
            let d = x - m
            sq += d * d
        }
        return sqrt(sq / (data.size.toFloat64() - 1.0))
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        if (data1.size != data2.size || data1.size < 2) {
            return 0.0 / 0.0   // NaN
        }
        let m1 = mean(data1)
        let m2 = mean(data2)
        var num = 0.0
        var den1 = 0.0
        var den2 = 0.0
        for (i in 0..data1.size) {
            let dx = data1[i] - m1
            let dy = data2[i] - m2
            num += dx * dy
            den1 += dx * dx
            den2 += dy * dy
        }
        return num / sqrt(den1 * den2)
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        if (data.size < 3) { return 0.0 / 0.0 }
        let m  = mean(data)
        let sd = stdDev(data)
        var sum3 = 0.0
        for (x in data) {
            let t = (x - m) / sd
            sum3 += t * t * t
        }
        return sum3 * data.size.toFloat64() /
               ((data.size.toFloat64() - 1.0) * (data.size.toFloat64() - 2.0))
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        if (data.size < 4) { return 0.0 / 0.0 }
        let m  = mean(data)
        let sd = stdDev(data)
        var sum4 = 0.0
        for (x in data) {
            let t = (x - m) / sd
            sum4 += t * t * t * t
        }
        let n = data.size.toFloat64()
        return sum4 * n * (n + 1.0) / ((n - 1.0) * (n - 2.0) * (n - 3.0)) -
               3.0 * (n - 1.0) * (n - 1.0) / ((n - 2.0) * (n - 3.0))
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        if (sigma <= 0.0) { return ArrayList<Float64>() }
        let coef = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let res = ArrayList<Float64>()
        for (x in data) {
            let z = (x - mu) / sigma
            let d = coef * exp(-0.5 * z * z)
            res.add(d)
        }
        return res
    }
}

