import std.collection.ArrayList

class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        var out = ""
        for (ch in ciphertext.runes()) {
            if ('a' <= ch && ch <= 'z') {
                let base = r'a'
                let off = (ch - base + 26 - (shift % 26)) % 26
                out += Rune(off + base.toUInt32())
            } else if ('A' <= ch && ch <= 'Z') {
                let base = r'A'
                let off = (ch - base + 26 - (shift % 26)) % 26
                out += Rune(off + base.toUInt32())
            } else {
                out += ch
            }
        }
        return out
    }

    public func vigenere_decipher(ciphertext: String): String {
        var out = ""
        let keyRunes = key.toRuneArray()
        var ki = 0
        for (ch in ciphertext.runes()) {
            if ('a' <= ch && ch <= 'z') {
                let k = keyRunes[ki % keyRunes.size] - r'a'
                let base = r'a'
                let off = (ch - base + 26 - (k % 26)) % 26
                out += Rune(off + base.toUInt32())
                ki += 1
            } else if ('A' <= ch && ch <= 'Z') {
                let k = (keyRunes[ki % keyRunes.size] | 32) - r'a'
                let base = r'A'
                let off = (ch - base + 26 - (k % 26)) % 26
                out += Rune(off + base.toUInt32())
                ki += 1
            } else {
                out += ch
            }
        }
        return out
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if (rails <= 1) { return encrypted_text }
        var fence = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            fence.append(ArrayList<Rune>())
        }
        let n = encrypted_text.size
