    let key: String
    public init(key: String) { this.key = key }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let runes = ciphertext.toRuneArray()
        var out = ArrayList<Rune>()
        for (r in runes) {
            if ('a' <= r && r <= 'z') {
                let base = Int64(r'A')
                let off  = (Int64(r) - base - shift + 26) % 26
                out.add(Rune((base + off).toUInt32()))
            } else if ('A' <= r && r <= 'Z') {
                let base = Int64(r'a')
                let off  = (Int64(r) - base - shift + 26) % 26
                out.add(Rune((base + off).toUInt32()))
            } else { out.add(r) }
        }
        String.fromRuneArray(out.toArray())
    }

    public func vigenere_decipher(ciphertext: String): String {
        let cipherRunes = ciphertext.toRuneArray()
        let keyRunes    = key.toRuneArray()
        var plain = ArrayList<Rune>()
        for (i in 0..cipherRunes.size) {
            let c = cipherRunes[i]
            let k = keyRunes[i % keyRunes.size]
            if ('A' <= c && c <= 'Z') {
                let off = (Int64(c) - Int64('A') - (Int64(k) - Int64('A')) + 26) % 26
                plain.add(Rune(Int64('A') + off))
            } else if ('a' <= c && c <= 'z') {
                let off = (Int64(c) - Int64('a') - (Int64(k) - Int64('a')) + 26) % 26
                plain.add(Rune(Int64('a') + off))
            } else { plain.add(c) }
        }
        String.fromRuneArray(plain.toArray())
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if (rails <= 1) { return encrypted_text }
        let runes = encrypted_text.toRuneArray()
        let n = runes.size
        var indices = Array<Int64>(n, item: 0)

        // build original indices
        var pos = 0
        for (r in 0..rails) {
            var i = r
            var down = true
            while (i < n) {
                indices[i] = pos
                pos += 1
                if (r == 0 || r == rails - 1) {
                    i += 2 * (rails - 1)
                } else {
                    let step = if (down) { 2 * (rails - 1 - r) } else { 2 * r }
                    i += step
                    down = !down
                }
            }
        }

        // fill plain runes
        var plain = Array<Rune>(n, item: r' ')
        for (i in 0..n) { plain[indices[i]] = runes[i] }
        String.fromRuneArray(plain)
    }
}

