class EightPuzzle {
    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (Int64(i), Int64(j))
                }
            }
        }
        return (0, 0) // should never reach here for valid input
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (bi, bj) = this.find_blank(state)
        var ni = bi
        var nj = bj
        if (direction == "up")   { ni = bi - 1 }
        if (direction == "down") { ni = bi + 1 }
        if (direction == "left") { nj = bj - 1 }
        if (direction == "right"){ nj = bj + 1 }

        // create deep copy
        var new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.add(ArrayList<Int64>(row))
        }
        // swap blank with adjacent tile
        let temp = new_state[bi][bj]
        new_state[bi][bj] = new_state[ni][nj]
        new_state[ni][nj] = temp
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (bi, bj) = this.find_blank(state)
        var moves = ArrayList<String>()
        if (bi > 0)       { moves.add("up")    }
        if (bi < 2)       { moves.add("down")  }
        if (bj > 0)       { moves.add("left")  }
        if (bj < 2)       { moves.add("right") }
        return moves
    }

    private func state_to_key(state: ArrayList<ArrayList<Int64>>): String {
        var key = ""
        for (row in state) {
            for (v in row) {
                key += "${v},"
            }
        }
        return key
    }

    public func solve(): ArrayList<String> {
        if (this.initial_state == this.goal_state) {
            return ArrayList<String>()
        }

        // queue entry: (state, path)
        var open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        var visited = HashSet<String>()

        open_list.add((this.initial_state, ArrayList<String>()))
        visited.add(this.state_to_key(this.initial_state))

        while (open_list.size > 0) {
            let (current, path) = open_list.remove(at: 0)
            let moves = this.get_possible_moves(current)
            for (m in moves) {
                let next_state = this.move(current, m)
                let key = this.state_to_key(next_state)
                if (visited.contains(key)) {
                    continue
                }
                var new_path = ArrayList<String>(path)
                new_path.add(m)
                if (next_state == this.goal_state) {
                    return new_path
                }
                visited.add(key)
                open_list.add((next_state, new_path))
            }
        }
        return ArrayList<String>() // no solution
    }
}

