class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (row, col) = this.find_blank(state)
        let new_state = ArrayList<ArrayList<Int64>>()

        for (i in 0..3) {
            let new_row = ArrayList<Int64>()
            for (j in 0..3) {
                new_row.add(state[i][j])
            }
            new_state.add(new_row)
        }

        var new_row = row
        var new_col = col

        match (direction) {
            case "up" => new_row = row - 1
            case "down" => new_row = row + 1
            case "left" => new_col = col - 1
            case "right" => new_col = col + 1
            case _ => return new_state
        }

        if (new_row >= 0 && new_row < 3 && new_col >= 0 && new_col < 3) {
            let temp = new_state[row][col]
            new_state[row][col] = new_state[new_row][new_col]
            new_state[new_row][new_col] = temp
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (row, col) = this.find_blank(state)
        let moves = ArrayList<String>()

        if (row > 0) {
            moves.add("up")
        }
        if (row < 2) {
            moves.add("down")
        }
        if (col > 0) {
            moves.add("left")
        }
        if (col < 2) {
            moves.add("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        var open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        var visited = ArrayList<ArrayList<ArrayList<Int64>>>()

        open_list.add((this.initial_state, ArrayList<String>()))

        while (open_list.size > 0) {
            let (current_state, current_path) = open_list.remove(at: 0)

            if (this.is_goal_state(current_state)) {
                return current_path
            }

            if (this.contains_state(visited, current_state)) {
                continue
            }
            visited.add(current_state)

            let possible_moves = this.get_possible_moves(current_state)
            for (move in possible_moves) {
                let new_state = this.move(current_state, move)
                if (!this.contains_state(visited, new_state)) {
                    var new_path = ArrayList<String>()
                    for (m in current_path) {
                        new_path.add(m)
                    }
                    new_path.add(move)
                    open_list.add((new_state, new_path))
                }
            }
        }

        return ArrayList<String>()
    }

    private func is_goal_state(state: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] != this.goal_state[i][j]) {
                    return false
                }
            }
        }
        return true
    }

    private func contains_state(list: ArrayList<ArrayList<ArrayList<Int64>>>, state: ArrayList<ArrayList<Int64>>): Bool {
        for (s in list) {
            var equal = true
            for (i in 0..3) {
                for (j in 0..3) {
                    if (s[i][j] != state[i][j]) {
                        equal = false
                        break
                    }
                }
                if (!equal) {
                    break
                }
            }
            if (equal) {
                return true
            }
        }
        return false
    }
}

