                return path
            }

            let moves = get_possible_moves(current)
            for (d in moves) {
                let next = move(current, d)
                if (!visited.contains(state_to_string(next))) {
                    let new_path = ArrayList<String>()
                    for (step in path) { new_path.add(step) }
                    new_path.add(d)
                    queue.add((next, new_path))
                }
            }
        }
        return ArrayList<String>() // no solution
    }

    // helper: convert state to unique string key
    private func state_to_string(state: ArrayList<ArrayList<Int64>>): String {
        var s = ""
        for (row in state) {
            for (v in row) {
                s = "${s}${v}"
            }
        }
        return s
    }

    // helper: check if state equals goal
    private func is_goal(state: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] != goal_state[i][j]) {
