        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        // check if receiver has enough space
        if (recv.is_full_with_one_more_email(size)) {
            return false
        }
        // compose and append email
        let email = HashMap<String, Any>([
            ("sender", this.addr),
            ("receiver", recv.addr),
            ("content", content),
            ("size", size),
            ("time", DateTime.now().format("yyyy-MM-dd HH:mm:ss")),
            ("state", "unread")
        ])
