import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let shiftNorm = ((shift % 26) + 26) % 26
        let out = StringBuilder()
        for (ch in plaintext.runes()) {
            if (ch >= 'a' && ch <= 'z') {
                let base = 'a'
                let idx = ((ch - base + shiftNorm) % 26)
                out.append(Rune(base + idx))
            } else if (ch >= 'A' && ch <= 'Z') {
                let base = 'A'
                let idx = ((ch - base + shiftNorm) % 26)
                out.append(Rune(base + idx))
            } else {
                out.append(ch)
            }
        }
        out.toString()
    }

    public func vigenere_cipher(plain_text: String): String {
        let keyRunes = this.key.toRuneArray()
        let keyLen = keyRunes.size
        let textRunes = plain_text.toRuneArray()
        let out = StringBuilder()
        var keyIdx = 0
        for (ch in textRunes) {
            if (ch >= 'a' && ch <= 'z') {
                let base = 'a'
                let shift = (keyRunes[keyIdx % keyLen] - base) % 26
                let idx = ((ch - base + shift) % 26)
                out.append(Rune(base + idx))
                keyIdx += 1
            } else if (ch >= 'A' && ch <= 'Z') {
                let base = 'A'
                let shift = (keyRunes[keyIdx % keyLen] - 'a') % 26
                let idx = ((ch - base + shift) % 26)
                out.append(Rune(base + idx))
                keyIdx += 1
            } else {
                out.append(ch)
            }
        }
        out.toString()
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if (rails <= 1) {
            return plain_text
        }
        let text = plain_text.toRuneArray()
        let n = text.size
        let fence = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            fence.add(ArrayList<Rune>())
        }
        var rail = 0
        var down = true
        for (i in 0..n) {
            fence[rail].add(text[i])
