        let runes = plaintext.toRuneArray()
        let out = ArrayList<Rune>([])
        for (r in runes) {
            if ('a' <= r && r <= 'z') {
                let base = r'0' + (r - r'a')     // 0-based
                let moved = (base + shift) % 26
                if (moved < 0) { moved += 26 }
                out.add(r'a' + moved)
            } else if ('A' <= r && r <= 'Z') {
                let base = r'0' + (r - r'A')
                let moved = (base + shift) % 26
                if (moved < 0) { moved += 26 }
                out.add(r'A' + moved)
            } else {
                out.add(r)                       // non-alphabetic unchanged
            }
        }
        String.fromRuneArray(out)
    }

