                rail += 1
                if (rail == rails - 1) { down = false }
            } else {
                rail -= 1
                if (rail == 0) { down = true }
            }
        }

        let out = ArrayList<Rune>([])
        for (row in fence) {
            for (ch in row) { out.add(ch) }
