import std.math.numeric.Decimal
import std.collection.ArrayList

class ExpressionCalculator {
    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        let stack = ArrayList<Float64>()
        for (token in postfix_stack) {
            if (!ExpressionCalculator.is_operator(token)) {
                stack.add(Float64.parse(token))
            } else {
                let b = stack.remove(at: stack.size - 1)
                let a = stack.remove(at: stack.size - 1)
                switch (token) {
                    case "+" => stack.add(a + b)
                    case "-" => stack.add(a - b)
                    case "*" => stack.add(a * b)
                    case "/" => stack.add(a / b)
                    case "%" => stack.add(a % b)
                }
            }
        }
        return stack[0]
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let clean = ExpressionCalculator.transform(expression)
        let ops = ArrayList<String>()
        let i = 0
        while (i < clean.size) {
            let c = clean[i].toString()
            if (c == " ") {
                i++
                continue
            }
            if (!ExpressionCalculator.is_operator(c)) {
                var num = c
                while (i + 1 < clean.size && !ExpressionCalculator.is_operator(clean[i + 1].toString())) {
                    i++
                    num += clean[i].toString()
                }
                postfix_stack.add(num)
            } else if (c == "(") {
                ops.add(c)
            } else if (c == ")") {
                while (ops.size > 0 && ops[ops.size - 1] != "(") {
                    postfix_stack.add(ops.remove(at: ops.size - 1))
                }
                ops.remove(at: ops.size - 1)
            } else {
                while (ops.size > 0 && compare(c, ops[ops.size - 1])) {
                    postfix_stack.add(ops.remove(at: ops.size - 1))
                }
                ops.add(c)
            }
            i++
        }
        while (ops.size > 0) {
            postfix_stack.add(ops.remove(at: ops.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        let curP = priority(cur)
        let peekP = priority(peek)
        return curP <= peekP
    }

    private func priority(op: String): Int64 {
        switch (op) {
            case "+" => return 1
            case "-" => return 1
            case "*" => return 2
            case "/" => return 2
            case "%" => return 2
            case "(" => return 0
            case _   => return -1
        }
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        switch (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => return first_value / second_value
            case "%" => return first_value % second_value
            case _   => return Decimal("0")
        }
    }

    public static func transform(expression: String): String {
        return expression.replace(" ", "")
    }
}

