                stack.add(res)
            }
        }
        stack[0]
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let transformed = ExpressionCalculator.transform(expression)
        let tokens = Regex("\\s+").split(transformed)
        let op_stack = ArrayList<String>()
        for (token in tokens) {
            if (!ExpressionCalculator.is_operator(token)) {
                postfix_stack.add(token)
            } else if (token == "(") {
                op_stack.add(token)
            } else if (token == ")") {
                while (op_stack.size > 0 && op_stack[op_stack.size - 1] != "(") {
                    postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                }
                op_stack.remove(at: op_stack.size - 1)
            } else {
                while (op_stack.size > 0 && compare(token, op_stack[op_stack.size - 1])) {
                    postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                }
                op_stack.add(token)
            }
        }
        while (op_stack.size > 0) {
            postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let curIndex  = ["+", "-", "*", "/", "(", ")", "%"].indexOf(cur).getOrThrow()
        let peekIndex = ["+", "-", "*", "/", "(", ")", "%"].indexOf(peek).getOrThrow()
        operat_priority[curIndex] >= operat_priority[peekIndex]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _   => Decimal(0.0)
        }
    }

