    }

    public func calculate(expression: String): Float64 {
        let tokens = expression.split(" ").filter({s => s != ""})
        let stack = ArrayList<Float64>()
        for (tok in tokens) {
            if (tok == "+" || tok == "-" || tok == "*" || tok == "/" || tok == "%") {
                let b = stack.remove(at: stack.size - 1)
                let a = stack.remove(at: stack.size - 1)
                match (tok) {
                    case "+" => stack.add(a + b)
                    case "-" => stack.add(a - b)
                    case "*" => stack.add(a * b)
                    case "/" => stack.add(a / b)
                    case "%" => stack.add(a % b)
                    case _   => stack.add(0.0)
                }
            } else {
                stack.add(Float64.parse(tok))
            }
        }
        return stack[0]
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let ops = ArrayList<String>()
        let cleaned = transform(expression)
        let tokens = Regex("([0-9]+|[\\+\\-\\*\\/%\\(\\)])").findAll(cleaned).map({m => m.matched})
        for (tok in tokens) {
            if (Regex("^[0-9]+$").matches(tok)) {
                postfix_stack.add(tok)
            } else if (tok == "(") {
                ops.add(tok)
            } else if (tok == ")") {
                while (ops.size > 0 && ops[ops.size - 1] != "(") {
                    postfix_stack.add(ops.remove(at: ops.size - 1))
                }
                ops.remove(at: ops.size - 1)
            } else if (is_operator(tok)) {
                while (ops.size > 0 && ops[ops.size - 1] != "(" && compare(tok, ops[ops.size - 1])) {
                    postfix_stack.add(ops.remove(at: ops.size - 1))
                }
                ops.add(tok)
            }
        }
        while (ops.size > 0) {
            postfix_stack.add(ops.remove(at: ops.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" | "-" | "*" | "/" | "(" | ")" | "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let prio: (String) -> Int64 = { op =>
            match (op) {
                case "+" => operat_priority[0]
                case "-" => operat_priority[1]
                case "*" => operat_priority[2]
                case "/" => operat_priority[3]
                case "(" => operat_priority[4]
                case ")" => operat_priority[5]
                case "%" => operat_priority[6]
                case _   => operat_priority[7]
            }
        }
        prio(cur) <= prio(peek)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
