                    case "-" => stack.add(a - b)
                    case "*" => stack.add(a * b)
                    case "/" => stack.add(a / b)
                    case "%" => stack.add(a % b)
                    case _   => throw Exception("Invalid operator")
                }
            }
        }
        return stack[0]
    }

    public func prepare(expression: String): Unit {
        postfix_stack.removeAll()
        let ops = ArrayList<String>()
        let tokens = transform(expression).split("").filter({s => s != ""})
        var i = 0
        while (i < tokens.size) {
            let token = tokens[i]
            if (!is_operator(token)) {
                var num = ""
                while (i < tokens.size && !is_operator(tokens[i])) {
                    num = num + tokens[i]
                    i += 1
                }
                postfix_stack.add(num)
                continue
            } else {
                match (token) {
                    case "(" => ops.add(token)
                    case ")" => {
                        while (ops.size > 0 && ops[ops.size - 1] != "(") {
                            postfix_stack.add(ops.remove(at: ops.size - 1))
                        }
                        ops.remove(at: ops.size - 1)
                    }
                    case _ => {
                        while (ops.size > 0 && compare(token, ops[ops.size - 1])) {
                            postfix_stack.add(ops.remove(at: ops.size - 1))
                        }
                        ops.add(token)
                    }
                }
            }
            i += 1
        }
        while (ops.size > 0) {
            postfix_stack.add(ops.remove(at: ops.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        let ops = ["+", "-", "*", "/", "(", ")", "%"]
        return ops.contains(c)
    }

