        let map = HashMap<String, Int64>([
            ("+", 0), ("-", 1), ("*", 2), ("/", 3), ("(", 4), (")", 5), ("%", 6), ("#", 7)
        ])
        let curP = operat_priority[map.get(cur).getOrThrow()]
        let peekP = operat_priority[map.get(peek).getOrThrow()]
        return curP <= peekP && peek != "("
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _   => throw Exception("Invalid operator")
        }
    }

    public static func transform(expression: String): String {
        return expression.replace(" ", "")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.collection.ArrayDeque  // stack

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([-1, 3, 3, 2, 2, 1, 1, -1]) // order: 0 dummy, + - * / % ( )
    }

    public func calculate(expression: String): Float64 {
        let tokens = transform(expression).split(" ").filter { s => s != "" }
        let stack = ArrayList<Decimal>()
        for (tok in tokens) {
            if (!is_operator(tok)) {
                stack.add(Decimal(tok))
            } else {
                let rhs = stack.remove(at: stack.size - 1)
                let lhs = stack.remove(at: stack.size - 1)
                stack.add(_calculate(lhs, rhs, tok))
            }
        }
        return stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let cleaned = transform(expression)
        let tokenRxs = [
            Regex(r"[ \t\r\n]"),  // whitespace
            Regex(r"[()]"),
            Regex(r"[+\-*/]"),
            Regex(r"\d+(\.\d+)?")
        ]
        let tokens = ArrayList<String>()
        var i = 0
        while (i < cleaned.size) {
            let c = cleaned[i]
            var matched = false
            for (rx in tokenRxs) {
                let m = rx.firstMatch(cleaned[i..])
                if (m != None<RegexMatch>) {
                    let mm = m.getOrThrow()
                    let s = cleaned[i..i + mm.match.size]
                    if (!Regex(r"^\s*$").test(s)) { tokens.add(s) }
                    i += mm.match.size
                    matched = true
                    break
                }
            }
            if (!matched) { i += 1 }
        }

        let ops = ArrayDeque<String>() // stack
        for (tok in tokens) {
            if (!is_operator(tok)) { postfix_stack.add(tok) }
            else if (tok == "(") { ops.push(tok) }
            else if (tok == ")") {
                while (ops.size > 0 && ops.back() != "(") { postfix_stack.add(ops.popBack()) }
                if (ops.size > 0) { ops.popBack() } // pop "("
            } else { // operator
                let idx = "+-*/%()".find(tok).get(0)
                if (ops.size > 0) {
                    while (!ops.isEmpty() && compare(tok, ops.back())) { postfix_stack.add(ops.popBack()) }
                }
                ops.push(tok)
            }
        }
        while (ops.size > 0) { postfix_stack.add(ops.popBack()) }
    }

    public static func is_operator(c: String): Bool { "+-*/()".contains(c) }

    public func compare(cur: String, peek: String): Bool {
        if (peek == "(") { return false }
        let p = "+-*/%()".find(cur).get(0)
        let q = "+-*/%()".find(peek).get(0)
        operat_priority[p] >= operat_priority[q]
    }

    public static func _calculate(first: Decimal, second: Decimal, op: String): Decimal {
        if (op == "+") { return first + second }
        else if (op == "-") { return first - second }
        else if (op == "*") { return first * second }
        else if (op == "/") { return first / second }
        else if (op == "%") { return first % second }
        else { return first } // fallback
    }

    public static func transform(expression: String): String { expression.replace("\n", "").replace(" ", "") }
}

