import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    /*  Basic four-function (+ − * / %) calculator for infix expressions. */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        /* indices correspond to "+-*/%()"  */
        operat_priority = ArrayList<Int64>([0, 0, 1, 1, 1, -1, -1])
    }

    /* ---------- public API -------------------------------------------------- */

    /*  Evaluate a complete infix expression. */
    public func calculate(expression: String): Float64 {
        let clean = transform(expression)
        prepare(clean)
        return evalPostfix()
    }

    /*  Convert infix → postfix, store result in postfix_stack. */
    public func prepare(expression: String): Unit {
        let tokens = tokenize(expression)
        postfix_stack.clear()
        var opStack = ArrayList<String>()

        for (tok in tokens) {
            if (!isOperator(tok)) {          // number
                postfix_stack.add(tok)
            } else if (tok == "(") {
                opStack.add(tok)
            } else if (tok == ")") {
                while (opStack.size > 0 && opStack[opStack.size - 1] != "(") {
                    postfix_stack.add(opStack.remove(at: opStack.size - 1))
                }
                if (opStack.size > 0) { opStack.remove(at: opStack.size - 1) } // pop "("
            } else {                         // operator
                while (opStack.size > 0 && precedenceOf(tok) <= precedenceOf(opStack[opStack.size - 1])) {
                    postfix_stack.add(opStack.remove(at: opStack.size - 1))
                }
                opStack.add(tok)
            }
        }
        while (opStack.size > 0) {
            postfix_stack.add(opStack.remove(at: opStack.size - 1))
        }
    }

    /* ---------- helpers ----------------------------------------------------- */

    /*  Strip blanks and ensure valid characters. */
    public static func transform(expression: String): String {
        let b = StringBuilder()
        for (ch in expression.runes()) {
            if (ch != r' ') { b.append(ch) }
        }
        b.toString()
    }

    /*  Membership in operator set. */
    public static func is_operator(c: String): Bool {
        let ops = ["+","-","*","/","%","(",")"]
        for (op in ops) { if (c == op) { return true } }
        false
    }

    /*  Simple precedence comparison (public wrapper). */
    public func compare(cur: String, peek: String): Bool {
        precedenceOf(cur) <= precedenceOf(peek)
    }

    /* ---------- private ----------------------------------------------------- */

    /*  Tokenise into numbers & operators respecting signs. */
    private func tokenize(expr: String): ArrayList<String> {
        var res = ArrayList<String>()
        var i = 0
        let n = expr.size
        while (i < n) {
            let ch = expr[i]
            if (ch == '+' || ch == '-' ||
                ch == '*' || ch == '/' ||
                ch == '%' || ch == '(' || ch == ')') {
                res.add(String(ch))
                i += 1
            } else if (ch >= '0' && ch <= '9') {
                var j = i + 1
                while (j < n && ((expr[j] >= '0' && expr[j] <= '9') || expr[j] == '.')) { j += 1 }
                res.add(expr[i..j])
                i = j
            } else {
                i += 1   // skip unexpected char
            }
        }
        res
    }

    /*  Precedence lookup. */
    private func precedenceOf(op: String): Int64 {
        let map = ["+": 0, "-": 0, "*": 1, "/": 1, "%": 1, "(": -1, ")": -1]
        map.getOrDefault(op, -2)
    }

    /*  Evaluate the postfix sequence in postfix_stack. */
    private func evalPostfix(): Float64 {
        var st = ArrayList<Float64>()
        for (tok in postfix_stack) {
            if (!is_operator(tok)) {
                st.add(Float64.parse(tok))
            } else {
                let b = st.remove(at: st.size - 1)
                let a = st.remove(at: st.size - 1)
                st.add(applyOp(a, b, tok))
            }
        }
        st[0]
    }

    /*  Apply single binary operator. */
    private func applyOp(x: Float64, y: Float64, op: String): Float64 {
        match (op) {
            case "+" => x + y
            case "-" => x - y
            case "*" => x * y
            case "/" => x / y
            case "%" => x % y
            case _   => 0.0
        }
    }
}

