    }

    public func compare(cur: String, peek: String): Bool {
        let map = HashMap<String, Int64>([("+", 1), ("-", 1), ("*", 2), ("/", 2), ("%", 2), ("(", 0)])
        if (peek == "(") {
            return false
        }
        return map[cur]! <= map[peek]!
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _   => Decimal(0.0)
        }
    }

    public static func transform(expression: String): String {
        Regex("\\s+").replace(expression, "")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        let stack = ArrayList<Float64>()
        for (s in postfix_stack) {
            if (!ExpressionCalculator.is_operator(s)) {
                stack.add(Float64.parse(s))
            } else {
                let b = stack.remove(at: stack.size - 1)
                let a = stack.remove(at: stack.size - 1)
                let res = match (s) {
                    case "+" => a + b
                    case "-" => a - b
                    case "*" => a * b
                    case "/" => a / b
                    case "%" => a % b
                    case _   => 0.0
                }
                stack.add(res)
            }
        }
        return stack[0]
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let expr = ExpressionCalculator.transform(expression)
        let opStack = ArrayList<String>()
        let i = 0
        while (i < expr.size) {
            let c = expr[i]
            if (c >= '0' && c <= '9') {
                let num = ""
                while (i < expr.size && ((expr[i] >= '0' && expr[i] <= '9') || expr[i] == '.')) {
                    num = "${num}${expr[i]}"
                    i += 1
                }
                postfix_stack.add(num)
                continue
            }
            if (c == ' ') { i += 1; continue }
            if (c == '(') {
                opStack.add("(")
            } else if (c == ')') {
                while (opStack.size > 0 && opStack[opStack.size - 1] != "(") {
                    postfix_stack.add(opStack.remove(at: opStack.size - 1))
                }
                opStack.remove(at: opStack.size - 1)
            } else if (ExpressionCalculator.is_operator("${c}")) {
                while (opStack.size > 0 && compare("${c}", opStack[opStack.size - 1])) {
                    postfix_stack.add(opStack.remove(at: opStack.size - 1))
                }
                opStack.add("${c}")
            }
            i += 1
        }
        while (opStack.size > 0) {
            postfix_stack.add(opStack.remove(at: opStack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        let ops = ["+", "-", "*", "/", "(", ")", "%"]
        for (op in ops) {
            if (c == op) { return true }
        }
        return false
    }

    public func compare(cur: String, peek: String): Bool {
        let map = HashMap<String, Int64>([
            ("+", 1), ("-", 1), ("*", 2), ("/", 2), ("%", 2), ("(", 0)
        ])
        let c = map.get(cur) ?? 0
        let p = map.get(peek) ?? 0
        return c <= p
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _   => Decimal(0.0)
        }
    }

    public static func transform(expression: String): String {
        let re = Regex("\\s+")
        re.replaceAll(expression, "")
    }
}

