            return -1
        } else if (bmi > Float64(high)) {
            return 1
        } else {
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        let bmr: Float64 = if (this.sex == "male") {
            Float64(10) * this.weight + Float64(6.25) * this.height * Float64(100) - Float64(5) * Float64(this.age) + Float64(5)
        } else {
