import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let res = ArrayList<Float64>([])
        for (xi in x_interp) {
            if (xi <= x[0]) {
                res.add(y[0])
                continue
            }
            if (xi >= x[x.size - 1]) {
                res.add(y[y.size - 1])
                continue
            }
            var i = 0
            while (i < x.size - 1 && x[i + 1] < xi) {
                i += 1
            }
            let t = (xi - x[i]) / (x[i + 1] - x[i])
            res.add(y[i] + t * (y[i + 1] - y[i]))
        }
        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let res = ArrayList<Float64>([])
        for (k in 0..x_interp.size) {
            let xi = x_interp[k]
            let yi = y_interp[k]
            // find x segment
            var ix = 0
            if (xi <= x[0]) {
                ix = 0
            } else if (xi >= x[x.size - 1]) {
                ix = x.size - 2
            } else {
                while (ix < x.size - 2 && x[ix + 1] < xi) {
                    ix += 1
                }
            }
            // find y segment
            var iy = 0
            if (yi <= y[0]) {
                iy = 0
            } else if (yi >= y[y.size - 1]) {
                iy = y.size - 2
            } else {
                while (iy < y.size - 2 && y[iy + 1] < yi) {
                    iy += 1
                }
            }
            // bilinear interpolation
            let x1 = x[ix]
            let x2 = x[ix + 1]
            let y1 = y[iy]
            let y2 = y[iy + 1]
            let fx1y1 = z[ix][iy]
            let fx2y1 = z[ix + 1][iy]
            let fx1y2 = z[ix][iy + 1]
            let fx2y2 = z[ix + 1][iy + 1]
            let t = (xi - x1) / (x2 - x1)
            let u = (yi - y1) / (y2 - y1)
            let fx_y1 = fx1y1 + t * (fx2y1 - fx1y1)
            let fx_y2 = fx1y2 + t * (fx2y2 - fx1y2)
            let fx_y  = fx_y1 + u * (fx_y2 - fx_y1)
            res.add(fx_y)
        }
        return res
    }
}

import std.collection.ArrayList
import std.math.*

class Interpolation {

    /* 1-D linear interpolation */
    public static func interpolate_1d(
        x:     ArrayList<Float64>,
        y:     ArrayList<Float64>,
        x_int: ArrayList<Float64>
    ): ArrayList<Float64> {
        // trivial bounds checks
        if (x.size != y.size || x.size < 2) {
            return ArrayList<Float64>()
        }
        let n = x.size
        let res = ArrayList<Float64>([])

        for (xi in x_int) {
            // out-of-bounds left
            if (xi <= x[0]) {
                res.add(y[0])
                continue
            }
            // out-of-bounds right
            if (xi >= x[n - 1]) {
                res.add(y[n - 1])
                continue
            }
            // locate bracket
            var m = n - 1
            for (i in 1..n) {
                if (x[i] >= xi) {
                    m = i
                    break
                }
            }
            let x0 = x[m - 1]
            let x1 = x[m]
            let y0 = y[m - 1]
            let y1 = y[m]
            // linear interpolation
            let t = (xi - x0) / (x1 - x0)
            res.add(y0 + t * (y1 - y0))
        }
        res
    }

    /* 2-D bilinear interpolation (treating z[y][x]) */
    public static func interpolate_2d(
        x:     ArrayList<Float64>,
        y:     ArrayList<Float64>,
        z:     ArrayList<ArrayList<Float64>>,
        x_int: ArrayList<Float64>,
        y_int: ArrayList<Float64>
    ): ArrayList<Float64> {
        // basic consistency checks
        if (x.size < 2 || y.size < 2) {
            return ArrayList<Float64>()
        }
        let ny = y.size
        let nx = x.size
        if (z.size != ny) {
            return ArrayList<Float64>()
        }
        for (row in z) {
            if (row.size != nx) {
                return ArrayList<Float64>()
            }
        }

        let res = ArrayList<Float64>([])
        for (i in 0..x_int.size) {
            let xi = x_int[i]
            let yi = y_int[i]

            // indices and weights in x-direction
            let (ix, tx) = locate(x, xi)
            // indices and weights in y-direction
            let (iy, ty) = locate(y, yi)

            // retrieve four surrounding grid values
            let f00 = z[iy][ix]
            let f10 = z[iy][ix + 1]
            let f01 = z[iy + 1][ix]
            let f11 = z[iy + 1][ix + 1]

            // bilinear interpolation
            let f = (1.0 - tx) * (1.0 - ty) * f00 +
                    tx       * (1.0 - ty) * f10 +
                    (1.0 - tx) * ty       * f01 +
                    tx       * ty       * f11
            res.add(f)
        }
        res
    }

    /* helper: locate bracket and local interpolation weight 0<=t<1 */
    private static func locate(xs: ArrayList<Float64>, v: Float64): (Int64, Float64) {
        let n = xs.size - 1
        if (v <= xs[0]) {
            return (0, 0.0)
        }
        if (v >= xs[n]) {
            return (n - 1, 1.0)
        }
        var ix = n - 1
        for (i in 1..n) {
            if (xs[i] >= v) {
                ix = i - 1
                break
            }
        }
        let x0 = xs[ix]
        let x1 = xs[ix + 1]
        let t = (v - x0) / (x1 - x0)
        (ix, t)
    }
}

