class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size
        let m = x_interp.size
        let res = ArrayList<Float64>()
        for (i in 0..m) {
            let xi = x_interp[i]
            if (xi <= x[0]) {
                res.add(y[0])
                continue
            }
            if (xi >= x[n-1]) {
                res.add(y[n-1])
                continue
            }
            for (j in 0..n-1) {
                if (xi >= x[j] && xi <= x[j+1]) {
                    let dx = x[j+1] - x[j]
                    let dy = y[j+1] - y[j]
                    let yi = y[j] + (xi - x[j]) * dy / dx
                    res.add(yi)
                    break
                }
            }
        }
        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let nx = x.size
        let ny = y.size
        let m = x_interp.size
        let res = ArrayList<Float64>()
        for (k in 0..m) {
            let xi = x_interp[k]
            let yi = y_interp[k]
            // find x segment
            let ix = if (xi <= x[0]) { 0 } else if (xi >= x[nx-1]) { nx-2 } else {
                var idx = 0
                for (i in 0..nx-1) {
                    if (xi >= x[i] && xi <= x[i+1]) {
                        idx = i
                        break
                    }
                }
                idx
            }
            // find y segment
            let iy = if (yi <= y[0]) { 0 } else if (yi >= y[ny-1]) { ny-2 } else {
                var idy = 0
                for (j in 0..ny-1) {
                    if (yi >= y[j] && yi <= y[j+1]) {
                        idy = j
                        break
                    }
                }
                idy
            }
            // bilinear interpolation
            let x1 = x[ix]
            let x2 = x[ix+1]
            let y1 = y[iy]
            let y2 = y[iy+1]
            let z11 = z[ix][iy]
            let z12 = z[ix][iy+1]
            let z21 = z[ix+1][iy]
            let z22 = z[ix+1][iy+1]
            let t = (xi - x1) / (x2 - x1)
            let u = (yi - y1) / (y2 - y1)
            let zi = (1.0 - t) * (1.0 - u) * z11 +
                     t * (1.0 - u) * z21 +
                     (1.0 - t) * u * z12 +
                     t * u * z22
            res.add(zi)
        }
        return res
    }
}

