class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size
        let m = x_interp.size
        let res = ArrayList<Float64>()
        for (i in 0..m) {
            let xi = x_interp[i]
            var idx = 0
            for (j in 0..(n - 1)) {
                if (xi >= x[j] && xi <= x[j + 1]) {
                    idx = j
                    break
                }
            }
            let x0 = x[idx]
            let x1 = x[idx + 1]
            let y0 = y[idx]
            let y1 = y[idx + 1]
            let yi = y0 + (y1 - y0) * (xi - x0) / (x1 - x0)
            res.add(yi)
        }
        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let m = x_interp.size
        let res = ArrayList<Float64>()
        for (k in 0..m) {
            let xi = x_interp[k]
            let yi = y_interp[k]

            // Find x interval
            var ix = 0
            for (i in 0..(x.size - 1)) {
                if (xi >= x[i] && xi <= x[i + 1]) {
                    ix = i
                    break
                }
            }

            // Find y interval
            var iy = 0
            for (j in 0..(y.size - 1)) {
                if (yi >= y[j] && yi <= y[j + 1]) {
                    iy = j
                    break
                }
            }

            // Bilinear interpolation
            let x0 = x[ix]
            let x1 = x[ix + 1]
            let y0 = y[iy]
            let y1 = y[iy + 1]

            let z00 = z[ix][iy]
            let z01 = z[ix][iy + 1]
            let z10 = z[ix + 1][iy]
            let z11 = z[ix + 1][iy + 1]

            let t = (xi - x0) / (x1 - x0)
            let u = (yi - y0) / (y1 - y0)

            let z0 = z00 * (1 - t) + z10 * t
            let z1 = z01 * (1 - t) + z11 * t
            let zi = z0 * (1 - u) + z1 * u

            res.add(zi)
        }
        return res
    }
}

import std.collection.ArrayList
import std.math.*

class Interpolation {

    /* ---------- 1-D linear interpolation ---------- */
    public static func interpolate_1d(x: ArrayList<Float64>,
                                      y: ArrayList<Float64>,
                                      x_interp: ArrayList<Float64>): ArrayList<Float64> {

        func findSegment(v: ArrayList<Float64>, t: Float64): Int64 {
            /* simple adjacent pair search */
            for (i in 0..(v.size - 1)) {
                if (t >= v[i] && t <= v[i + 1]) { return i }
            }
            return -1
        }

        let res = ArrayList<Float64>()

        for (xi in x_interp) {
            let idx = findSegment(x, xi)
            if (idx < 0) {            // outside domain -> constant extrapolation
                res.add(if (xi <= x[0]) { y[0] } else { y[y.size - 1] })
                continue
            }
            let x0 = x[idx]
            let x1 = x[idx + 1]
            let y0 = y[idx]
            let y1 = y[idx + 1]
            let t = (xi - x0) / (x1 - x0)
            res.add(y0 + t * (y1 - y0))
        }
        return res
    }

    /* ---------- 2-D bilinear interpolation ---------- */
    public static func interpolate_2d(x: ArrayList<Float64>,
                                      y: ArrayList<Float64>,
                                      z: ArrayList<ArrayList<Float64>>,
                                      x_interp: ArrayList<Float64>,
                                      y_interp: ArrayList<Float64>): ArrayList<Float64> {

        /* locate segment helper */
        func findSegment(v: ArrayList<Float64>, t: Float64): Int64 {
            for (i in 0..(v.size - 1)) {
                if (t >= v[i] && t <= v[i + 1]) { return i }
            }
            return -1
        }

        let res = ArrayList<Float64>()

        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            let ix = findSegment(x, xi)
            let iy = findSegment(y, yi)

            if (ix < 0 || iy < 0) {
                /* outside domain -> constant extrapolation with z[0][0] */
                res.add(z[0][0])
                continue
            }

            let x0 = x[ix]
            let x1 = x[ix + 1]
            let y0 = y[iy]
            let y1 = y[iy + 1]

            let fx = (xi - x0) / (x1 - x0)
            let fy = (yi - y0) / (y1 - y0)

            /* four surrounding z values */
            let z00 = z[iy][ix]
            let z10 = z[iy][ix + 1]
            let z01 = z[iy + 1][ix]
            let z11 = z[iy + 1][ix + 1]

            /* bilinear formula */
            let z0 = z00 + fx * (z10 - z00)
            let z1 = z01 + fx * (z11 - z01)
            let zi = z0  + fy * (z1  - z0)

            res.add(zi)
        }
        return res
    }
}

import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let n = x.size

        for (xi in x_interp) {
            if (xi <= x[0]) {
                result.add(y[0])
            } else if (xi >= x[n - 1]) {
                result.add(y[n - 1])
            } else {
                var i = 0
                while (i < n - 1 && x[i + 1] < xi) {
                    i += 1
                }
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[i]
                let y1 = y[i + 1]
                let yi = y0 + (xi - x0) * (y1 - y0) / (x1 - x0)
                result.add(yi)
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let nx = x.size
        let ny = y.size

        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x index
            var ix = 0
            if (xi <= x[0]) {
                ix = 0
            } else if (xi >= x[nx - 1]) {
                ix = nx - 2
            } else {
                while (ix < nx - 2 && x[ix + 1] < xi) {
                    ix += 1
                }
            }

            // Find y index
            var iy = 0
            if (yi <= y[0]) {
                iy = 0
            } else if (yi >= y[ny - 1]) {
                iy = ny - 2
            } else {
                while (iy < ny - 2 && y[iy + 1] < yi) {
                    iy += 1
                }
            }

            // Bilinear interpolation
            let x0 = x[ix]
            let x1 = x[ix + 1]
            let y0 = y[iy]
            let y1 = y[iy + 1]

            let z00 = z[iy][ix]
            let z01 = z[iy][ix + 1]
            let z10 = z[iy + 1][ix]
            let z11 = z[iy + 1][ix + 1]

            let wx = (xi - x0) / (x1 - x0)
            let wy = (yi - y0) / (y1 - y0)

            let z0 = z00 * (1.0 - wx) + z01 * wx
            let z1 = z10 * (1.0 - wx) + z11 * wx
            let zi = z0 * (1.0 - wy) + z1 * wy

            result.add(zi)
        }
        return result
    }
}

