class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>,
                                      x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size
        let m = x_interp.size
        var res = ArrayList<Float64>()
        for (i in 0..m) {
            let xi = x_interp[i]
            // binary search for the interval [x[k], x[k+1]]
            var lo = 0
            var hi = n - 1
            while (lo < hi - 1) {
                let mid = (lo + hi) / 2
                if (x[mid] >= xi) { hi = mid } else { lo = mid }
            }
            let k = lo
            let x0 = x[k]
            let x1 = x[k + 1]
            let y0 = y[k]
            let y1 = y[k + 1]
            let yi = y0 + (xi - x0) * (y1 - y0) / (x1 - x0)
            res.add(yi)
        }
        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>,
                                      z: ArrayList<ArrayList<Float64>>,
                                      x_interp: ArrayList<Float64>,
                                      y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let nx = x.size
        let ny = y.size
        let m = x_interp.size
        var res = ArrayList<Float64>()
        for (i in 0..m) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // locate x interval
            var xlo = 0
            var xhi = nx - 1
            while (xlo < xhi - 1) {
                let xm = (xlo + xhi) / 2
                if (x[xm] >= xi) { xhi = xm } else { xlo = xm }
            }
            let ix = xlo
            let x0 = x[ix]
            let x1 = x[ix + 1]

            // locate y interval
            var ylo = 0
            var yhi = ny - 1
            while (ylo < yhi - 1) {
                let ym = (ylo + yhi) / 2
                if (y[ym] >= yi) { yhi = ym } else { ylo = ym }
            }
            let iy = ylo
            let y0 = y[iy]
            let y1 = y[iy + 1]

            // corner values
            let q11 = z[ix][iy]
            let q12 = z[ix][iy + 1]
            let q21 = z[ix + 1][iy]
            let q22 = z[ix + 1][iy + 1]

            // bilinear interpolation
            let t = (xi - x0) / (x1 - x0)
            let u = (yi - y0) / (y1 - y0)
            let zi = (1 - t) * (1 - u) * q11 +
                     t * (1 - u) * q21 +
                     (1 - t) * u * q12 +
                     t * u * q22
            res.add(zi)
        }
        return res
    }
}

