import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = this.ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            let num = Int64.parse(part)
            if (num is None || num.getOrThrow() < 0 || num.getOrThrow() > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!this.is_valid()) {
            return ArrayList<String>()
        }
        return ArrayList<String>(this.ip_address.split("."))
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let parts = this.ip_address.split(".")
        let binParts = ArrayList<String>()
        for (part in parts) {
            let num = Int64.parse(part).getOrThrow()
            let bin = String.format("{:08b}", num)
            binParts.append(bin)
        }
        return binParts.join(".")
    }
}

