    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) { return false }
        for (p in parts) {
            match (Int64.parse(p)) {
                case Some(n) => if (n < 0 || n > 255) { return false }
                case None    => return false
            }
        }
        true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) { return ArrayList<String>() }
        ArrayList<String>(ip_address.split("."))
    }

    public func get_binary(): String {
        if (!is_valid()) { return "" }
        let parts = ip_address.split(".")
        let bin   = ArrayList<String>()
        for (p in parts) {
            let n = Int64.parse(p).getOrThrow()
            bin.add(String().format("08b", n))
        }
        bin.join(".")
    }
}

