import std.collection.ArrayList

class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            if (part.size == 0 || part.size > 3) {
                return false
            }
            for (c in part) {
                if (c < '0' || c > '9') {
                    return false
                }
            }
            let num = Int64.parse(part)
            if (num < 0 || num > 255) {
                return false
            }
            if ((num == 0 && part != "0") || (num != 0 && part[0] == '0')) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) {
            return ArrayList<String>()
        }
        return ArrayList<String>(ip_address.split("."))
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let parts = ip_address.split(".")
        let binParts = ArrayList<String>()
        for (part in parts) {
            let num = Int64.parse(part)
            let bin = String.format("%08d", Int64.parse(Int64.toBinaryString(num)))
            binParts.append(bin)
        }
        return binParts.join(".")
    }
}

