class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts: Array<String> = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            let v = part.toUInt8()
            match (v) {
                case None<UInt8> => return false
                case Some<UInt8>(x) => continue
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) {
            return ArrayList<String>([])
        }
        let parts: Array<String> = ip_address.split(".")
        let res = ArrayList<String>()
        for (p in parts) {
            res.append(p)
        }
        return res
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let parts: Array<String> = ip_address.split(".")
        var bins: ArrayList<String> = ArrayList<String>()
        for (p in parts) {
            let v = p.toUInt8().getOrThrow()
            bins.append(v.toString(base: 2, width: 8))
        }
        return bins.join(".")
    }
}

