class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = this.ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (p in parts) {
            let v = Int64.parse(p)
            if (v is None || v.getOrThrow() < 0 || v.getOrThrow() > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!this.is_valid()) {
            return ArrayList<String>([])
        }
        return ArrayList<String>(this.ip_address.split("."))
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let parts = this.ip_address.split(".")
        let buf = StringBuilder()
        for (i in 0..4) {
            let v = Int64.parse(parts[i]).getOrThrow()
            let bin = String.format("%08d", Int64.parse(Long.toBinaryString(v)).getOrThrow())
            buf.append(bin)
            if (i < 3) {
                buf.append(".")
            }
        }
        buf.toString()
    }
}

