import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) { return false }
        for (p in parts) {
            let opt = UInt8.tryParse(p)
            if (opt is None<UInt8>) { return false }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) { return ArrayList<String>() }
        return ArrayList<String>(ip_address.split("."))
    }

    public func get_binary(): String {
        if (!is_valid()) { return "" }
        let parts = ip_address.split(".")
        var res: ArrayList<String> = ArrayList<String>()
        for (p in parts) {
            let n = UInt8.parse(p)
            let s = Formattable.format("00000000", n)
            res.add(s[s.size - 8..s.size])
        }
        return res.join(".")
    }
}

