import std.net.IPAddress
import std.posix.gethostname
import std.collection.*

class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split('.')
        if (parts.size != 4) { return false }
        for (part in parts) {
            if (part.size == 0 || part.size > 3) { return false }
            for (c in part.runes()) {
                if (c < r'0' || c > r'9') { return false }
            }
            let num = Int64.parse(part)
            if (num < 0 || num > 255) { return false }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        let pieces = ip_address.split(':')
        let doubleColon = ip_address.contains("::")
        if (doubleColon) {
            if (ip_address.split("::").size > 2) { return false }
        }
        let expected = if (doubleColon) { 8 - 1 } else { 8 }
        if (pieces.size > expected + 1) { return false }
        for (piece in pieces) {
            if (piece.size > 4) { return false }
            for (c in piece.runes()) {
                let valid = (c >= r'0' && c <= r'9') ||
                            (c >= r'a' && c <= r'f') ||
                            (c >= r'A' && c <= r'F')
                if (!valid) { return false }
            }
        }
        return true
    }

    public static func get_hostname(ip_address: String): Option<String> {
        try {
            let addr = IPAddress.ip(ip_address)
            let host = addr.getHostname()
            return Some<String>(host)
        } catch (_) {
            return None<String>
        }
    }
}

import std.net.*
import std.net.IPAddress.*
import std.regex.*
import std.collection.*

class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (p in parts) {
            let num = Int64.parse(p) ?? -1
            if (num < 0 || num > 255) {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        let parts = ip_address.split(":")
        if (parts.size > 8) {
            return false
        }
        let empty = 0
        for (p in parts) {
            if (p == "") {
                empty += 1
            } else if (p.size > 4) {
                return false
            } else {
                let _ = Int64.parse(p, base: 16) ?? return false
            }
        }
        return empty <= 1
    }

    public static func get_hostname(ip_address: String): Option<String> {
        match (IPAddress.parse(ip_address)) {
            case Some(addr) => {
                let host = addr.getHostName()
                return host == ip_address ? None<String> : Some<String>(host)
            }
            case None => None<String>
        }
    }
}

