import std.net.IPAddress
import std.collection.*
import std.regex.*

class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            let num = part.toInt64OrNull()
            if (num == None<Int64> || num! < 0 || num! > 255) {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        let parts = ip_address.split(":")
        if (parts.size > 8) {
            return false
        }
        var empty_found = false
        for (part in parts) {
            if (part.isEmpty()) {
                if (empty_found) {
                    return false
                }
                empty_found = true
            } else {
                if (part.size > 4) {
                    return false
                }
                for (c in part) {
                    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                        return false
                    }
                }
            }
        }
        return true
    }

    public static func get_hostname(ip_address: String): Option<String> {
        match (IPAddress.parse(ip_address)) {
            case None<IPAddress> => None<String>
            case Some<IPAddress>(ip) =>
                match (ip.reverseLookup()) {
                    case None<String> => None<String>
                    case Some<String>(host) => Some<String>(host)
                }
        }
    }
}

