class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // row sums
        let rowSum = ArrayList<Int64>()
        for (i in 0..k) {
            var sum = 0
            for (j in 0..k) {
                sum += testData[i][j]
            }
            rowSum.add(sum)
        }

        // column sums
        let colSum = ArrayList<Int64>()
        for (j in 0..k) {
            var sum = 0
            for (i in 0..k) {
                sum += testData[i][j]
            }
            colSum.add(sum)
        }

        // total
        var total = 0
        for (rs in rowSum) {
            total += rs
        }

        // observed agreement
        var obs = 0.0
        for (i in 0..k) {
            obs += Float64(testData[i][i])
        }
        obs = obs / Float64(total)

