class KappaCalculator {

    /*  Cohen’s κ for a k×k contingency table  */
    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // --- sanity checks ----------------------------------------------------
        if (k <= 0 || testData.size != k) { return 0.0 }
        for (row in testData) { if (row.size != k) { return 0.0 } }

        // --- observed agreement (Po) -----------------------------------------
        var total: Float64 = 0.0
        var diag:  Float64 = 0.0
        for (i in 0..k) {
            for (j in 0..k) {
                let v = Float64(testData[i][j])
                total += v
                if (i == j) { diag += v }
            }
        }
        if (total == 0.0) { return 0.0 }
        let po = diag / total

        // --- expected agreement (Pe) ------------------------------------------
        var pe = 0.0
        for (i in 0..k) {
            var rowSum = 0.0
            var colSum = 0.0
            for (j in 0..k) {
                rowSum += Float64(testData[i][j])
                colSum += Float64(testData[j][i])
            }
            pe += (rowSum * colSum)
        }
        pe /= (total * total)

        // --- κ -----------------------------------------------------------------
        return if (pe >= 1.0) { 0.0 } else { (po - pe) / (1.0 - pe) }
    }

    /*  Fleiss’ κ for an N×k matrix of category counts  */
    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>,
                                    N: Int64, k: Int64, n: Int64): Float64 {
        // --- sanity checks ----------------------------------------------------
        if (N <= 0 || k <= 1 || n <= 1 || testData.size != N) { return 0.0 }
        for (row in testData) { if (row.size != k) { return 0.0 } }

        // --- proportion of assignments to each category -----------------------
        var p: Array<Float64> = Array<Float64>(k, item: 0.0)
        for (j in 0..k) {
            for (i in 0..N) { p[j] += Float64(testData[i][j]) }
            p[j] /= Float64(N * n)
        }

        // --- observed agreement for each subject ------------------------------
        var po = 0.0
        for (i in 0..N) {
            var sumSq = 0.0
            for (j in 0..k) {
                let c = Float64(testData[i][j])
                sumSq += c * c
            }
            po += (sumSq - Float64(n)) / Float64(n * (n - 1))
        }
        po /= Float64(N)

        // --- expected agreement -----------------------------------------------
        var pe = 0.0
        for (j in 0..k) { pe += p[j] * p[j] }

        // --- κ -----------------------------------------------------------------
        return if (pe >= 1.0) { 0.0 } else { (po - pe) / (1.0 - pe) }
    }
}

