import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>,
                                    ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let rn = Random()
        var res = ArrayList<ArrayList<String>>()
        for (_ in 0..rows) {
            var row = ArrayList<String>()
            for (_ in 0..cols) {
                let idx = rn.nextInt64(ICONS.size)
                row.append(ICONS[idx])
            }
            res.append(row)
        }
        return res
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        if (x1 < 0 || y1 < 0 || x2 < 0 || y2 < 0) { return false }
        if (x1 >= BOARD_SIZE[0] || y1 >= BOARD_SIZE[1] ||
            x2 >= BOARD_SIZE[0] || y2 >= BOARD_SIZE[1]) { return false }
        if (pos1 == pos2) { return false }
        if (board[x1][y1] != board[x2][y2]) { return false }
        return has_path(pos1, pos2)
    }

    /* ---------- path finding helpers ---------- */
    private let directions = ArrayList<(Int64, Int64)>([(0, 1), (1, 0), (0, -1), (-1, 0)])

    private func dfs(pos: (Int64, Int64),
                     target: (Int64, Int64),
                     visited: ArrayList<(Int64, Int64)>,
                     bends: Int64): Bool {
        if (pos == target) { return bends <= 2 }
        if (bends > 2) { return false }
        for (d in directions) {
            let nx = pos[0] + d[0]
            let ny = pos[1] + d[1]
            if (nx < 0 || ny < 0 ||
                nx >= BOARD_SIZE[0] || ny >= BOARD_SIZE[1]) { continue }
            if (board[nx][ny] != " " && (nx, ny) != target) { continue }
            let newBends = if (visited.size > 0) {
                let (lx, ly) = visited[visited.size - 1]
                if ((lx - pos[0], ly - pos[1]) != d) { bends + 1 } else { bends }
            } else { bends }

            if (contains(visited, (nx, ny))) { continue }
            visited.append((nx, ny))
            if (dfs((nx, ny), target, visited, newBends)) { return true }
            visited.remove(at: visited.size - 1)
        }
        return false
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        var visited = ArrayList<(Int64, Int64)>()
        visited.append(pos1)
        return dfs(pos1, pos2, visited, 0)
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>,
                                pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) { return true }
        }
        return false
    }

    /* ---------- game play operations ---------- */
    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        board[pos1[0]][pos1[1]] = " "
        board[pos2[0]][pos2[1]] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != " ") { return false }
            }
        }
        return true
    }
}

