    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let iconCount = ICONS.size
        var newBoard = ArrayList<ArrayList<String>>()

        let rand = Random()

        for (_ in 0..rows) {
            var row = ArrayList<String>()
            for (_ in 0..cols) {
                let idx = rand.nextUInt64() % iconCount
                row.append(ICONS[idx])
            }
            newBoard.append(row)
        }
        return newBoard
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols ||
            x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols) {
            return false
        }
        if (x1 == x2 && y1 == y2) {
            return false
        }
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        var visited = ArrayList<(Int64, Int64)>()
        visited.append((x1, y1))

        func dfs(x: Int64, y: Int64, turns: Int64, lastDir: Int64): Bool {
            if (turns > 2) {
                return false
            }
            if (x == x2 && y == y2) {
                return true
            }
            for (d in 0..4) {
                let (dx, dy) = dirs[d]
                let nx = x + dx
                let ny = y + dy
                if (nx < -1 || nx > rows || ny < -1 || ny > cols) {
                    continue
                }
                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                    if (board[nx][ny] != " " && (nx != x2 || ny != y2)) {
                        continue
                    }
                }
                if (contains(visited, (nx, ny))) {
                    continue
                }
                let newTurns = if (d != lastDir && lastDir != -1) { turns + 1 } else { turns }
                visited.append((nx, ny))
                if (dfs(nx, ny, newTurns, d)) {
                    return true
                }
                visited.remove(at: visited.size - 1)
            }
            return false
        }

        return dfs(x1, y1, 0, -1)
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}

