    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let left  = center - diff
        let right = center + diff
        if (left < 0 || right >= string.size || string[left] != string[right]) {
            return diff - 1
        }
        return palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        if (input_string.size == 0) {
            return ""
        }

        // Build transformed string s with separators '|'
        var s = ""
        for (c in input_string.runes()) {
            s += "|"
            s += String(c)
        }
        s += "|"

        let n = s.size
        var p = Array<Int64>(n, item: 0)
        var center: Int64 = 0
        var right:  Int64 = 0

        for (i in 0..n) {
            let mirror = 2 * center - i
            if (i < right) {
                p[i] = if (right - i < p[mirror]) { right - i } else { p[mirror] }
            }

            let len = palindromic_length(i, p[i] + 1, s)
            p[i] = len

            if (i + len > right) {
                center = i
                right  = i + len
            }
        }

        // Find max element
        var maxLen: Int64 = 0
        var idx:    Int64 = 0
        for (i in 0..n) {
            if (p[i] > maxLen) {
                maxLen = p[i]
                idx    = i
            }
        }

        // Extract substring
        let start = (idx - maxLen) / 2
        let runes = input_string.toRuneArray()
        var res = ""
        for (i in start..start + maxLen) {
            res += String(runes[i])
        }
        return res
    }
}

