    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        let n = predicted_labels.size
        if (n != true_labels.size) {
            return // lengths differ – silently ignore; caller should guarantee consistency
        }
        for (i in 0..n) {
            let pred = predicted_labels[i]
            let true_ = true_labels[i]
            if (pred == 1) {
                if (true_ == 1) {
                    this.true_positives += 1
                } else { // true_ == 0
                    this.false_positives += 1
                }
            } else { // pred == 0
                if (true_ == 1) {
                    this.false_negatives += 1
                } else { // true_ == 0
                    this.true_negatives += 1
                }
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let denom = this.true_positives + this.false_positives
        return if (denom == 0) { 0.0 } else { this.true_positives.toFloat64() / denom.toFloat64() }
