    private static func singleMrr(pred: ArrayList<Int64>, totalRelevant: Int64): Float64 {
        var rank = 0
        for (i in 0..pred.size) {
            if (pred[i] == 1) {
                rank = i + 1
                break
            }
        }
        if (rank == 0) { return 0.0 }
        return 1.0 / Float64(rank)
    }

    /* helper: single AP */
    private static func singleAp(pred: ArrayList<Int64>, totalRelevant: Int64): Float64 {
        var hits = 0
        var sumPrec = 0.0
        for (i in 0..pred.size) {
            if (pred[i] == 1) {
                hits += 1
                sumPrec += Float64(hits) / Float64(i + 1)
            }
        }
        if (totalRelevant == 0) { return 0.0 }
        return sumPrec / Float64(totalRelevant)
    }

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        /* handle single tuple */
        if (data is (ArrayList<Int64>, Int64)) {
            let (pred, total) = data as (ArrayList<Int64>, Int64)
            let score = singleMrr(pred, total)
            let list = ArrayList<Float64>([score])
            return (score, list)
        }
        /* handle list of tuples */
        if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let list = data as ArrayList<(ArrayList<Int64>, Int64)>
            var scores = ArrayList<Float64>()
            var sum: Float64 = 0.0
            for (item in list) {
