class MetricsCalculator2 {

    public init() {}

    /* ----------------------------------------------------------
     *  Mean Reciprocal Rank (MRR)
     * ---------------------------------------------------------- */
    public static func mrr(data: Any):
            (Float64, ArrayList<Float64>) {
        let mrrOne = { t: (ArrayList<Int64>, Int64) -> Float64
            let (l, _) = t
            for (k in 0 .. l.size) {
                if (l[k] == 1) {
                    return 1.0 / (Float64(k) + 1.0)
                }
            }
            return 0.0
        }

        if (data is (ArrayList<Int64>, Int64)) {
            let v = mrrOne(data.as<(ArrayList<Int64>, Int64)>())
            let ls = ArrayList<Float64>()
            ls.add(v)
            (v, ls)
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let a = data.as<ArrayList<(ArrayList<Int64>, Int64)>>()
            let ls = ArrayList<Float64>()
            var sum: Float64 = 0.0
            for (e in a) {
                let v = mrrOne(e); ls.add(v); sum = sum + v
            }
            (sum / Float64(a.size), ls)
        } else {
            panic("mrr: input must be (ArrayList<Int64>, Int64) or ArrayList of those")
        }
    }

    /* ----------------------------------------------------------
     *  Mean Average Precision (MAP)
     * ---------------------------------------------------------- */
    public static func map(data: Any):
            (Float64, ArrayList<Float64>) {
        let apOne = { t: (ArrayList<Int64>, Int64) -> Float64
            let (l, gt) = t
            var relSoFar: Int64 = 0
            var sumPrec: Float64  = 0.0
            for (k in 0 .. l.size) {
                if (l[k] == 1) {
                    relSoFar = relSoFar + 1
                    sumPrec = sumPrec
                           + Float64(relSoFar) / Float64(k + 1)
                }
            }
            if (relSoFar == 0) {
                0.0
            } else {
                sumPrec / Float64(gt)
            }
        }

        if (data is (ArrayList<Int64>, Int64)) {
            let v = apOne(data.as<(ArrayList<Int64>, Int64)>())
            let ls = ArrayList<Float64>()
            ls.add(v)
            (v, ls)
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let a = data.as<ArrayList<(ArrayList<Int64>, Int64)>>()
            let ls = ArrayList<Float64>()
            var sum: Float64 = 0.0
            for (e in a) {
                let v = apOne(e); ls.add(v); sum = sum + v
            }
            (sum / Float64(a.size), ls)
        } else {
            panic("map: input must be (ArrayList<Int64>, Int64) or ArrayList of those")
        }
    }
}

