        let (pred, _) = pair
        for (i in 0..pred.size) {
            if (pred[i] == 1) {
                return 1.0 / Float64(i + 1)
            }
        }
        0.0
    }

    private static func _singleMap(pair: (ArrayList<Int64>, Int64)): Float64 {
        let (pred, total) = pair
        if (total <= 0) { return 0.0 }

        var relSoFar = 0
        var apAcc = 0.0

        for (k in 1..pred.size + 1) {
            if (pred[k - 1] == 1) {
                relSoFar += 1
                apAcc += Float64(relSoFar) / Float64(k)
            }
        }
        if (relSoFar == 0) { 0.0 } else { apAcc / Float64(total) }
    }

