            case (p: (ArrayList<Int64>, Int64)) => {
                let v = _singleMrr(p)
                scores.add(v)
                return (v, scores)
            }
            case (lst: ArrayList<(ArrayList<Int64>, Int64)>) => {
                if (lst.size == 0) { return (0.0, scores) }
                for (p in lst) { scores.add(_singleMrr(p)) }
