import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // 1. 初始化 n x n 的空白图，全填 '0'
        var grid = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("0")
            }
            grid.add(row)
        }
        // 2. 随机埋 k 个雷
        let rng = Random()
        var placed: Int64 = 0
        while (placed < k) {
            let x = rng.nextInt64(n)
            let y = rng.nextInt64(n)
            if (grid[x][y] != "X") {
                grid[x][y] = "X"
                placed += 1
            }
        }
        // 3. 计算每个非雷格周围雷数
        let dx = [-1, -1, -1, 0, 0, 1, 1, 1]
        let dy = [-1, 0, 1, -1, 1, -1, 0, 1]
        for (i in 0..n) {
            for (j in 0..n) {
                if (grid[i][j] == "X") { continue }
                var cnt: Int64 = 0
                for (d in 0..8) {
                    let ni = i + dx[d]
                    let nj = j + dy[d]
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == "X") {
                        cnt += 1
                    }
                }
                grid[i][j] = "${cnt}"
            }
        }
        return grid
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-" && minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map
        }
        if (player_map[x][y] != "-") {
            return player_map
        }
        if (minesweeper_map[x][y] == "X") {
            // 踩雷，直接判负（返回 false）
            return false
        }
        // BFS 展开空白区域
        var q = ArrayList<(Int64, Int64)>()
        q.add((x, y))
        let dx = [-1, -1, -1, 0, 0, 1, 1, 1]
        let dy = [-1, 0, 1, -1, 1, -1, 0, 1]
        while (q.size > 0) {
            let (i, j) = q.remove(at: 0)
            if (player_map[i][j] != "-") { continue }
            player_map[i][j] = minesweeper_map[i][j]
            if (minesweeper_map[i][j] == "0") {
                for (d in 0..8) {
                    let ni = i + dx[d]
                    let nj = j + dy[d]
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && player_map[ni][nj] == "-") {
                        q.add((ni, nj))
                    }
                }
            }
        }
        if (check_won(player_map)) {
            return true
        }
        return player_map
    }
}

