class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let grid = ArrayList<ArrayList<String>>([])
        var r = 0
        while (r < n) {
            let row = ArrayList<String>([])
            var c = 0
            while (c < n) {
                row.add("0")
                c += 1
            }
            grid.add(row)
            r += 1
        }

        let rng = Random()
        var placed = 0
        while (placed < k) {
            let x = rng.nextInt64(n)
            let y = rng.nextInt64(n)
            if (grid[x][y] == "X") {
                continue
            }
            grid[x][y] = "X"
            let dx = [-1, -1, -1, 0, 0, 1, 1, 1]
            let dy = [-1, 0, 1, -1, 1, -1, 0, 1]
            var i = 0
            while (i < 8) {
                let nx = x + dx[i]
                let ny = y + dy[i]
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] != "X") {
                    let cnt = grid[nx][ny].toInt64()
                    grid[nx][ny] = "${cnt + 1}"
                }
                i += 1
            }
            placed += 1
        }
        return grid
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let pm = ArrayList<ArrayList<String>>([])
        var r = 0
        while (r < n) {
            let row = ArrayList<String>([])
            var c = 0
            while (c < n) {
                row.add("-")
                c += 1
            }
            pm.add(row)
            r += 1
        }
        return pm
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        var r = 0
        while (r < n) {
            var c = 0
            while (c < n) {
                if (minesweeper_map[r][c] != "X" && map[r][c] == "-") {
                    return false
                }
                c += 1
            }
            r += 1
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            player_map[x][y] = "X"
            return false
        }
        if (player_map[x][y] != "-") {
            return player_map
        }

        var toReveal = ArrayList<(Int64, Int64)>([])
        toReveal.add((x, y))
        while (toReveal.size > 0) {
            let (cx, cy) = toReveal.remove(at: 0)
            if (player_map[cx][cy] != "-") {
                continue
            }
            player_map[cx][cy] = minesweeper_map[cx][cy]
            if (minesweeper_map[cx][cy] == "0") {
                let dx = [-1, -1, -1, 0, 0, 1, 1, 1]
                let dy = [-1, 0, 1, -1, 1, -1, 0, 1]
                var i = 0
                while (i < 8) {
                    let nx = cx + dx[i]
                    let ny = cy + dy[i]
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && player_map[nx][ny] == "-") {
                        toReveal.add((nx, ny))
                    }
                    i += 1
                }
            }
        }

        if (check_won(player_map)) {
            return true
        }
        return player_map
    }
}

