    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // 1. place k mines randomly
        let rng = Random()
        var minePos = HashSet<Int64>()
        while (minePos.size < k) {
            let pos = rng.nextInt64(n * n)  // 0 .. n*n-1
            minePos.add(pos)
        }

        // 2. build base grid
        var grid = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.append("0")
            }
            grid.append(row)
        }

        // 3. mark mines and increment neighbours
        for (pos in minePos) {
            let r = pos / n
            let c = pos % n
            grid[r][c] = "X"
            for (dr in -1..2) {
                for (dc in -1..2) {
                    if (dr == 0 && dc == 0) {
                        continue
                    }
                    let nr = r + dr
                    let nc = c + dc
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != "X") {
                        let cnt = String.parse(grid[nr][nc])
                        grid[nr][nc] = String(cnt + 1)
                    }
                }
            }
        }
        return grid
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var pm = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.append("-")
            }
            pm.append(row)
        }
        return pm
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            return false            // lose immediately
        }
        player_map[x][y] = minesweeper_map[x][y]
        if (check_won(player_map)) {
            return true             // win
        }
        return player_map           // continue
    }
}

