import std.random.*
import std.collection.*

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None<String>
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        let idx = this.playlist.indexOf(song)
        if (idx >= 0) {
            this.playlist.remove(at: idx)
            if (this.current_song == Some<String>(song)) {
                this.current_song = None<String>
            }
        }
    }

    public func play(): Option<String> {
        if (this.current_song is None<String> && this.playlist.size > 0) {
            this.current_song = Some<String>(this.playlist[0])
        }
        this.current_song
    }

    public func stop(): Bool {
        if (this.current_song is None<String>) {
            false
        } else {
            this.current_song = None<String>
            true
        }
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let cur = this.current_song ?? ""
        let idx = this.playlist.indexOf(cur)
        let next = idx + 1
        if (next >= this.playlist.size) {
            false
        } else {
            this.current_song = Some<String>(this.playlist[next])
            true
        }
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let cur = this.current_song ?? ""
        let idx = this.playlist.indexOf(cur)
        let prev = idx - 1
        if (prev < 0) {
            false
        } else {
            this.current_song = Some<String>(this.playlist[prev])
            true
        }
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            true
        } else {
            false
        }
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let rng = Random()
        for (i in this.playlist.size - 1..0:-1) {
            let j = rng.nextInt(i + 1)
            let tmp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = tmp
        }
        true
    }
}

