        }
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song is None) {
            return false
        }
        let idx = this.playlist.indexOf((this.current_song as Some).getOrThrow())
        let next = (idx + 1) % this.playlist.size
        this.current_song = Some(this.playlist[next])
        true
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song is None) {
            return false
        }
        let idx = this.playlist.indexOf((this.current_song as Some).getOrThrow())
        let prev = if (idx == 0) { this.playlist.size - 1 } else { idx - 1 }
        this.current_song = Some(this.playlist[prev])
        true
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            true
        } else {
