import std.collection.*
import std.regex.*
import std.sort.*

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        // keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        let words_list = ArrayList<ArrayList<String>>()
        let pattern = Regex("[a-zA-Z ]+")

        for (item in string_list) {
            let filtered = ""
            let matches = pattern.match_all(item)
            for (m in matches) {
                filtered += m.get() + " "
            }
            let lower = filtered.toLowerCase()
            let words = ArrayList<String>(lower.split(" ").filter{ w => w.size > 0 })
            words_list.add(words)
        }
        words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq = HashMap<String, Int64>()
        for (words in words_list) {
            for (w in words) {
                if (freq.contains(w)) {
                    freq[w] = freq[w] + 1
                } else {
                    freq.add(w, 1)
                }
            }
        }
        // sort by descending frequency
        let entries = ArrayList<(String, Int64)>()
        for (k in freq.keySet()) {
            entries.add((k, freq[k]))
        }
        let cmp = {l: (String, Int64), r: (String, Int64) => l[1] < r[1]}
        sort(entries, lessThan: cmp, descending: true)

        // take top 5
        let top5 = HashMap<String, Int64>()
        for (i in 0..min(5, entries.size)) {
            let (k, v) = entries[i]
            top5.add(k, v)
        }
        top5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        this.calculate_word_frequency(words_list)
    }
}

