class NumberConverter {
    public static func decimal_to_binary(decimal_num: Int64): String {
        if (decimal_num == 0) { return "0" }
        let n = decimal_num
        var num = n
        var res = ArrayList<Rune>()
        while (num > 0) {
            let bit = (num % 2).toRune()
            res.add(bit)
            num = num / 2
        }
        res.reverse()
        return String(res.toArray())
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        var dec: Int64 = 0
        let runes = binary_num.toRuneArray()
        for (r in runes) {
            dec = dec * 2 + (r - r'0')
        }
        return dec
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        if (decimal_num == 0) { return "0" }
        let n = decimal_num
        var num = n
        var res = ArrayList<Rune>()
        while (num > 0) {
            let digit = (num % 8).toRune()
            res.add(digit)
            num = num / 8
        }
        res.reverse()
        return String(res.toArray())
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        var dec: Int64 = 0
        let runes = octal_num.toRuneArray()
        for (r in runes) {
            dec = dec * 8 + (r - r'0')
        }
        return dec
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        if (decimal_num == 0) { return "0" }
        let n = decimal_num
        var num = n
        var res = ArrayList<Rune>()
        while (num > 0) {
            let rem = num % 16
            let digit = if (rem < 10) { (r'0' + rem) } else { (r'a' + (rem - 10)) }
            res.add(digit)
            num = num / 16
        }
        res.reverse()
        return String(res.toArray())
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        var dec: Int64 = 0
        let runes = hex_num.toRuneArray()
        for (r in runes) {
            let val = if (r >= r'0' && r <= r'9') { r - r'0' }
                      else if (r >= r'a' && r <= r'f') { 10 + (r - r'a') }
                      else if (r >= r'A' && r <= r'F') { 10 + (r - r'A') }
                      else { 0 }
            dec = dec * 16 + val
        }
        return dec
    }
}

