        let parts = x.split(".")
        let intPart = parts[0]
        let decPart = if (parts.size == 2) { parts[1] } else { "" }

        var words = trans_integer(intPart)
        if (decPart != "" && decPart != "0") {
            words += " POINT " + trans_decimal(decPart)
        }
        words + " ONLY"
    }

    func trans_integer(s: String): String {
        if (s == "0") {
            return "ZERO"
        }
        let n = s.size
        var res = ""
        var i = 0
        while (i < n) {
            let group = n - i > 3 ? s[i..i+3] : s[i..]
            let word = trans_three(group)
            if (word != "") {
                let more = parse_more((n - i - 1) / 3)
                res = (res == "" ? "" : res + " ") + word + (more == "" ? "" : " " + more)
            }
            i += 3
        }
        res
    }

    func trans_decimal(s: String): String {
        var res = ""
        for (c in s.runes()) {
            let d = Int64.parse(c.toString())
            res = res + (res == "" ? "" : " ") + NUMBER[d]
        }
        res
    }

    public func trans_two(s: String): String {
        let n = Int64.parse(s)
        if (n < 10) {
            NUMBER[n]
        } else if (n < 20) {
            NUMBER_TEEN[n - 10]
        } else {
            let ten = n / 10
            let one = n % 10
            NUMBER_TEN[ten - 1] + (one == 0 ? "" : " " + NUMBER[one])
        }
    }

    public func trans_three(s: String): String {
        let n = Int64.parse(s)
        if (n < 100) {
            return trans_two(s)
        }
        let hundred = n / 100
        let rem = n % 100
        let hundredWord = NUMBER[hundred] + " HUNDRED"
        let remWord = trans_two(rem.toString())
        hundredWord + (remWord == "" ? "" : " AND " + remWord)
    }

    public func parse_more(i: Int64): String {
        NUMBER_MORE[i]
    }
}

