        var i = s.size - 3
        while (i >= 0) {
            groups.add(s.slice(i, i + 3))
            i -= 3
        }
        if (i > -3) { groups.add(s.slice(0, i + 3)) }
        var res = ""
        for (j in 0..groups.size) {
            let g = groups[groups.size - 1 - j]
            let words = this.trans_three(g)
            if (words != "") {
                if (res != "") { res += " " }
                res += words
                let suffix = this.parse_more(j)
                if (suffix != "") { res += " " + suffix }
            }
        }
        res
    }

