        let n = Int64.parse(s)
        if (n < 10) { return this.NUMBER[n] }
        if (n < 20) { return this.NUMBER_TEEN[n - 10] }
        let ten = n / 10
        let one = n % 10
        let tenWord = this.NUMBER_TEN[ten - 1]
