        let intPart = parts[0]
        let decPart = if (parts.size == 2) { parts[1] } else { "" }
        var words = trans_integer(intPart)
        if (decPart.size > 0) {
            words = "${words} POINT ${trans_decimal(decPart)}"
        }
        "${words} ONLY"
    }

    func trans_integer(s: String): String {
        if (s == "0") { return "ZERO" }
        let groups = split_into_three(s)
        var result = ""
        for (i in 0..groups.size) {
            let g = groups[i]
            if (g == "000") { continue }
            let idx = groups.size - i - 1
            let suffix = parse_more(idx.toInt64())
            let part = trans_three(g)
            result = if (result == "") { "${part} ${suffix}" }
                     else { "${result} ${part} ${suffix}" }
        }
        result.trim()
    }

    func trans_decimal(s: String): String {
        var res = ""
        for (c in s.runes()) {
            let d = Int64.parse(c.toString())
            res = "${res} ${NUMBER[d]}"
        }
        res.trim()
    }

    func split_into_three(s: String): Array<String> {
        var padded = s
        let rem = s.size % 3
        if (rem != 0) {
            padded = "0" * (3 - rem) + s
        }
        var groups = Array<String>([])
        for (i in 0..padded.size by 3) {
            groups.append(padded[i..i+3])
        }
        groups
    }

