    }

    public func trans_three(s: String): String {
        let n = Int64.parse(s)
        if (n == 0) { return "" }
        let hundred = n / 100
        let rem = n % 100
        var res = ""
        if (hundred > 0) { res = "${NUMBER[hundred]} HUNDRED" }
        if (rem > 0) {
            let two = trans_two(rem.toString())
            res = if (res == "") { two } else { "${res} AND ${two}" }
        }
        res
    }

    public func parse_more(i: Int64): String {
        if (i >= NUMBER_MORE.size) { return "" }
        NUMBER_MORE[i]
    }
