    public func format_string(x: String): String {
        let parts = x.split(".")
        let integerPart = parts[0]
        let word = this.trans_integer(integerPart)
        if (parts.size > 1 && parts[1].size > 0) {
            let decimalPart = parts[1]
            word += " POINT " + this.trans_decimal(decimalPart)
        }
        return word + " ONLY"
    }

    private func trans_integer(s: String): String {
        if (s == "0") {
            return "ZERO"
        }
        let digits = s.split("").filter({c: String => c != ""})
