        let groups = ArrayList<String>()
        var i = n
        while (i > 0) {
            let start = if (i >= 3) { i - 3 } else { 0 }
            let grp = digits[start..i].reduce("", {a: String, b: String => a + b})
            groups.insert(grp.padStart(3, '0'), at: 0)
            i = start
        }
        var words = ""
        let m = groups.size
        for (j in 0..m) {
            let g = groups[j]
            if (g == "000") {
                continue
            }
            let w = this.trans_three(g)
            let suffix = this.parse_more((m - j - 1).toInt64())
            words += w + (if (suffix != "") { " " + suffix } else { "" }) + " "
        }
        return words.trimEnd()
    }

    private func trans_decimal(s: String): String {
        let sb = StringBuilder()
        for (c in s.runes()) {
            let d = Rune(c).toString().parseInt().getOrThrow()
            sb.append(this.NUMBER[d])
            sb.append(" ")
        }
