        let integerPart = parts[0]
        let intWords = trans_integer(integerPart)
        let decWords = if (parts.size == 2) { trans_decimal(parts[1]) } else { "" }
        let result = if (decWords == "") { intWords } else { "${intWords} POINT ${decWords}" }
        return "${result} ONLY"
    }

    func trans_integer(s: String): String {
        if (s == "0") { return "ZERO" }
        let groups = ArrayList<String>()
        var i = s.size - 3
        while (i >= 0) {
            groups.add(s[i..i+3])
            i -= 3
        }
        if (i + 3 > 0) { groups.add(s[0..i+3]) }
        var words = ""
        for (j in 0..groups.size) {
            let g = groups[groups.size - 1 - j]
            if (g != "000") {
                let w = trans_three(g)
                let suffix = parse_more(j)
                words = if (words == "") { "${w} ${suffix}" } else { "${w} ${suffix} ${words}" }
            }
        }
        return words
    }

    func trans_decimal(s: String): String {
        var res = ""
        for (c in s) {
            let d = Int64.parse(c.toString())
            res = "${res} ${NUMBER[d]}"
        }
        return res.trim()
    }

    public func trans_two(s: String): String {
