        let n = Int64.parse(s)
        if (n < 100) { return trans_two(s) }
        let hundred = n / 100
        let rest = n % 100
        if (rest == 0) { return "${NUMBER[hundred]} HUNDRED" }
        return "${NUMBER[hundred]} HUNDRED AND ${trans_two(rest.toString())}"
    }

    public func parse_more(i: Int64): String {
        if (i < NUMBER_MORE.size) { return NUMBER_MORE[i] }
        return ""
    }
}

