class NumericEntityUnescaper {
    public init() {}

    public func replace(string: String): String {
        let runes = string.toRuneArray()
        let out = ArrayList<Rune>()
        let n = runes.size
        var i = 0
        while (i < n) {
            if (runes[i] == r'&' && i + 2 < n && runes[i + 1] == r'#') {
                var base = 10
                var start = i + 2
                if (runes[start] == r'x' || runes[start] == r'X') {
                    base = 16
                    start += 1
                }
                var j = start
                while (j < n && NumericEntityUnescaper.is_digit(runes[j], base)) {
                    j += 1
                }
                if (j < n && runes[j] == r';') {
                    let digits = String(runes[start..j])
                    match (base) {
                        case 10 => match (UInt32.parse(digits)) {
                            case Some(code) => {
                                out.append(Rune.fromUInt32(code))
                                i = j + 1
                                continue
                            }
                            case _ => {}
                        }
                        case 16 => match (UInt32.parse(digits, radix: 16)) {
                            case Some(code) => {
                                out.append(Rune.fromUInt32(code))
                                i = j + 1
                                continue
                            }
                            case _ => {}
                        }
                    }
                }
            }
            out.append(runes[i])
            i += 1
        }
        String(out)
    }

    private static func is_digit(r: Rune, base: Int32): Bool {
        let c = r.toUInt32()
        switch (base) {
            case 10 => (c >= 48 && c <= 57)  // '0'..'9'
            case 16 => (c >= 48 && c <= 57) || (c >= 65 && c <= 70) || (c >= 97 && c <= 102)
            case _ => false
        }
    }

    public static func is_hex_char(char: Rune): Bool {
        is_digit(char, 16)
    }
}

