                if (runes[start] == r'x' || runes[start] == r'X') {
                    base = 16
                    start += 1
                }
                var value = 0
                var j = start
                while (j < n && NumericEntityUnescaper.is_hex_char(runes[j])) {
                    let digit = match (runes[j]) {
                        case r'0' => 0
                        case r'1' => 1
                        case r'2' => 2
                        case r'3' => 3
                        case r'4' => 4
                        case r'5' => 5
                        case r'6' => 6
                        case r'7' => 7
                        case r'8' => 8
                        case r'9' => 9
                        case r'a' | r'A' => 10
                        case r'b' | r'B' => 11
                        case r'c' | r'C' => 12
                        case r'd' | r'D' => 13
                        case r'e' | r'E' => 14
                        case r'f' | r'F' => 15
                        case _ => 0
                    }
                    value = value * base + digit
                    j += 1
                }
                if (j < n && runes[j] == r';') {
                    out.append(Rune.fromInt(value))
                    i = j + 1
                    continue
                }
            }
            out.append(runes[i])
            i += 1
        }
        return String.fromRunes(out)
    }

    public static func is_hex_char(char: Rune): Bool {
        match (char) {
            case r'0'..r'9' | r'a'..r'f' | r'A'..r'F' => true
            case _ => false
        }
    }
}

