        if (phoneNumber.size != 11) {
            return None<String>
        }
        for (c in phoneNumber.runes()) {
            if (c < r'0' || c > r'9') {
                return None<String>
            }
        }
        return Some<String>(phoneNumber)
    }
}

import std.collection.ArrayList
import std.sort.*

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            let rows = map.size
            for (i in 0..rows) {
                let row = map[i]
                let cols = row.size
                for (j in 0..cols) {
                    let c = row[j]
                    if (c == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (c == "G") {
                        let pos = ArrayList<Int64>([i, j])
                        this.targets.add(pos)
                        this.target_count += 1
                    } else if (c == "X") {
                        let pos = ArrayList<Int64>([i, j])
                        this.boxes.add(pos)
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var on_target = 0
        for (box in boxes) {
            let br = box[0]
            let bc = box[1]
            for (tg in targets) {
                if (br == tg[0] && bc == tg[1]) {
                    on_target += 1
                    break
                }
            }
        }
        this.is_game_over = (on_target == target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dirs = HashMap<String, (Int64, Int64)>([("w", (-1, 0)), ("s", (1, 0)), ("a", (0, -1)), ("d", (0, 1))])
        let (dr, dc) = dirs[direction]
        let nr = player_row + dr
        let nc = player_col + dc

        // Boundary and wall check
        if (nr < 0 || nr >= map.size || nc < 0 || nc >= map[0].size || map[nr][nc] == "#") {
            return check_win()
        }

        // Check if next cell is a box
        var box_idx = -1
        for (i in 0..boxes.size) {
            let b = boxes[i]
            if (b[0] == nr && b[1] == nc) {
                box_idx = i
                break
            }
        }

        if (box_idx >= 0) {
            let br2 = nr + dr
            let bc2 = nc + dc
            // Check if box can be pushed
            if (br2 < 0 || br2 >= map.size || bc2 < 0 || bc2 >= map[0].size || map[br2][bc2] == "#") {
                return check_win()
            }
            // Check if another box is in the way
            var blocked = false
            for (b in boxes) {
                if (b[0] == br2 && b[1] == bc2) {
                    blocked = true
                    break
                }
            }
            if (blocked) {
                return check_win()
            }
            // Move box
            boxes[box_idx][0] = br2
            boxes[box_idx][1] = bc2
        }

        // Move player
        player_row = nr
        player_col = nc
        return check_win()
    }

    public func print_map(): Unit {
        let display = ArrayList<ArrayList<String>>()
        for (row in map) {
            display.add(ArrayList<String>(row))
        }
        // Place targets
        for (tg in targets) {
            let r = tg[0]
            let c = tg[1]
            display[r][c] = "G"
        }
        // Place boxes
        for (bx in boxes) {
            let r = bx[0]
            let c = bx[1]
            display[r][c] = "X"
        }
        // Place player
        display[player_row][player_col] = "O"
        // Print
        for (row in display) {
            for (cell in row) {
                print("${cell} ")
            }
            println("")
        }
    }
}

