import std.collection.ArrayList

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    let cell = map[i][j]
                    if (cell == "O") {
                        player_row = i
                        player_col = j
                        map[i][j] = " "   // clear player marker
                    } else if (cell == "G") {
                        targets.append(ArrayList<Int64>([i, j]))
                        target_count += 1
                        map[i][j] = " "   // clear target marker
                    } else if (cell == "X") {
                        boxes.append(ArrayList<Int64>([i, j]))
                        map[i][j] = " "   // clear box marker
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var covered = 0
        for (b in boxes) {
            let br = b[0]
            let bc = b[1]
            for (t in targets) {
                if (br == t[0] && bc == t[1]) {
                    covered += 1
                    break
                }
            }
        }
        is_game_over = (covered == target_count)
        return is_game_over
    }

    public func move(direction: String): Bool {
        // compute desired next player position
        var dr = 0
        var dc = 0
        if (direction == "w")      { dr = -1 }
        else if (direction == "s") { dr = 1  }
        else if (direction == "a") { dc = -1 }
        else if (direction == "d") { dc = 1  }
        else { return false }  // invalid direction

        let nr = player_row + dr
        let nc = player_col + dc

        // boundary & wall check
        if (nr < 0 || nr >= map.size || nc < 0 || nc >= map[0].size) { return false }
        if (map[nr][nc] == "#") { return false }

        // check if a box is in the way
        var box_idx = -1
        for (i in 0..boxes.size) {
            if (boxes[i][0] == nr && boxes[i][1] == nc) {
                box_idx = i
                break
            }
        }

        if (box_idx >= 0) {
            // compute box's next position
            let br = nr + dr
            let bc = nc + dc
            if (br < 0 || br >= map.size || bc < 0 || bc >= map[0].size) { return false }
            if (map[br][bc] == "#") { return false }
            // check if another box occupies the spot
            for (b in boxes) {
                if (b[0] == br && b[1] == bc) { return false }
            }
            // move the box
            boxes[box_idx][0] = br
            boxes[box_idx][1] = bc
        }

        // move the player
        player_row = nr
        player_col = nc

        return check_win()
    }

    /* helper to visualize the current board (not required but handy) */
    public func print_map(): Unit {
        for (i in 0..map.size) {
            var line = ""
            for (j in 0..map[i].size) {
                var ch = map[i][j]
                // player
                if (i == player_row && j == player_col) { ch = "O" }
                // box
                for (b in boxes) {
                    if (b[0] == i && b[1] == j) { ch = "X"; break }
                }
                // target (override if box is on target)
                for (t in targets) {
                    if (t[0] == i && t[1] == j) {
                        if (ch == "X") { ch = "*" }   // box on target
                        else if (ch == " ") { ch = "G" }
                        break
                    }
                }
                line = "${line}${ch} "
            }
            println(line)
        }
    }
}

