class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (row in 0..this.map.size) {
                for (col in 0..this.map[row].size) {
                    match (this.map[row][col]) {
                        case "O" => { this.player_row = row; this.player_col = col; this.map[row][col] = " " }
                        case "G" => { this.targets.add(ArrayList<Int64>([row, col])); this.target_count += 1 }
                        case "X" => { this.boxes.add(ArrayList<Int64>([row, col])); this.map[row][col] = " " }
                        default  => {}
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var boxes_on_target = 0
        for (box in this.boxes) {
            for (target in this.targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    boxes_on_target += 1
                    break
                }
            }
        }
        this.is_game_over = (boxes_on_target == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dr = match (direction) { case "w" => -1 case "s" => 1 case _ => 0 }
        let dc = match (direction) { case "a" => -1 case "d" => 1 case _ => 0 }
        let nr = this.player_row + dr
        let nc = this.player_col + dc

        if (this.map[nr][nc] == "#") { return this.check_win() }

        var is_pushing = false
        for (box in this.boxes) {
            if (box[0] == nr && box[1] == nc) { is_pushing = true; break }
        }

        if (is_pushing) {
            let br = nr + dr
            let bc = nc + dc
            if (this.map[br][bc] == "#") { return this.check_win() }
            for (box in this.boxes) {
                if (box[0] == br && box[1] == bc) { return this.check_win() }
            }
            for (box in this.boxes) {
                if (box[0] == nr && box[1] == nc) {
                    box[0] = br; box[1] = bc; break
                }
            }
        }

        this.player_row = nr
        this.player_col = nc
        return this.check_win()
    }
}

