class PushBoxGame {

    /*  Sokoban logic:
        '#' wall
        'O' player start
        'G' target
        'X' box start
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    let cell = map[i][j]
                    if (cell == "O") {
                        player_row = i
                        player_col = j
                    } else if (cell == "G") {
                        targets.append(ArrayList<Int64>([i, j]))
                        target_count += 1
                    } else if (cell == "X") {
                        boxes.append(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var onTarget = 0
        for (b in boxes) {
            for (t in targets) {
                if (b[0] == t[0] && b[1] == t[1]) {
                    onTarget += 1
                    break
                }
            }
        }
        is_game_over = (onTarget == target_count)
        return is_game_over
    }

    public func move(direction: String): Bool {
        let dr = direction == "w" ? -1 :
                 direction == "s" ? 1  : 0
        let dc = direction == "a" ? -1 :
                 direction == "d" ? 1  : 0

        let nr = player_row + dr
        let nc = player_col + dc

        // out of bounds or wall
        if (nr < 0 || nr >= map.size ||
            nc < 0 || nc >= map[0].size ||
            map[nr][nc] == "#") {
            return check_win()
        }

        // look for box at (nr,nc)
        var boxIdx = -1
        for (i in 0..boxes.size) {
            if (boxes[i][0] == nr && boxes[i][1] == nc) {
                boxIdx = i
                break
            }
        }

        if (boxIdx >= 0) {
            let br = nr + dr
            let bc = nc + dc
            // box target cell must be free and not wall
            if (br < 0 || br >= map.size ||
                bc < 0 || bc >= map[0].size ||
                map[br][bc] == "#") {
                return check_win()
            }
            // another box?
            for (b in boxes) {
                if (b[0] == br && b[1] == bc) {
                    return check_win()
                }
            }
            // push box
            boxes[boxIdx][0] = br
            boxes[boxIdx][1] = bc
        }

        // move player
        player_row = nr
        player_col = nc

        return check_win()
    }

    public func print_map(): Unit {
        for (i in 0..map.size) {
            for (j in 0..map[i].size) {
                var ch = map[i][j]
                // player overrides
                if (i == player_row && j == player_col) {
                    ch = "O"
                }
                // box overrides
                for (b in boxes) {
