import std.collection.ArrayList

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    let cell = map[i][j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.append(ArrayList<Int64>([i, j]))
                        this.target_count += 1
                    } else if (cell == "X") {
                        this.boxes.append(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var boxes_on_target = 0
        for (b in boxes) {
            for (t in targets) {
                if (b[0] == t[0] && b[1] == t[1]) {
                    boxes_on_target += 1
                    break
                }
            }
        }
        this.is_game_over = (boxes_on_target == target_count)
        return this.is_game_over
    }

    private func inside(pos: ArrayList<Int64>): Bool {
        pos[0] >= 0 && pos[0] < map.size && pos[1] >= 0 && pos[1] < map[0].size
    }

    private func blocked(pos: ArrayList<Int64>): Bool {
        map[pos[0]][pos[1]] == "#"
    }

    private func find_box(pos: ArrayList<Int64>): Int64 {
        for (i in 0..boxes.size) {
            if (boxes[i][0] == pos[0] && boxes[i][1] == pos[1]) {
                return i
            }
        }
        return -1
    }

    public func move(direction: String): Bool {
        if (is_game_over) { return true }

        let dr = if (direction == "w") { -1 } else if (direction == "s") { 1 } else { 0 }
        let dc = if (direction == "a") { -1 } else if (direction == "d") { 1 } else { 0 }
        let next = ArrayList<Int64>([player_row + dr, player_col + dc])

        if (!inside(next) || blocked(next)) { return false }
        let box_idx = find_box(next)

        if (box_idx >= 0) {
            let after = ArrayList<Int64>([next[0] + dr, next[1] + dc])
            if (!inside(after) || blocked(after) || find_box(after) >= 0) { return false }
            boxes[box_idx] = after
        }

        player_row = next[0]
        player_col = next[1]
        return check_win()
    }

    public func print_map(): Unit {
        for (i in 0..map.size) {
            for (j in 0..map[i].size) {
                let cell = map[i][j]
                if (i == player_row && j == player_col) {
                    print("O ")
                } else {
                    var found = false
                    for (b in boxes) {
                        if (b[0] == i && b[1] == j) {
                            print("X ")
                            found = true
                            break
                        }
                    }
                    if (!found) {
                        print(cell + " ")
                    }
                }
            }
            println("")
        }
    }
}

import std.collection.ArrayList

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    let ch = map[i][j]
                    if (ch == "O") {
                        this.player_row = i
                        this.player_col = j
                        this.map[i][j] = " "
                    } else if (ch == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count += 1
                        this.map[i][j] = " "
                    } else if (ch == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                        this.map[i][j] = " "
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var onTarget = 0
        for (b in this.boxes) {
            for (t in this.targets) {
                if (b[0] == t[0] && b[1] == t[1]) {
                    onTarget += 1
                    break
                }
            }
        }
        this.is_game_over = (onTarget == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dr = match (direction) {
            case "w" => -1
            case "s" => 1
            case _   => 0
        }
        let dc = match (direction) {
            case "a" => -1
            case "d" => 1
            case _   => 0
        }
        let nr = this.player_row + dr
        let nc = this.player_col + dc

        // out of bounds or wall
        if (nr < 0 || nr >= this.map.size ||
            nc < 0 || nc >= this.map[0].size ||
            this.map[nr][nc] == "#") {
            return this.check_win()
        }

        // check if there is a box
        var boxIdx = -1
        for (i in 0..this.boxes.size) {
            if (this.boxes[i][0] == nr && this.boxes[i][1] == nc) {
                boxIdx = i
                break
            }
        }

        if (boxIdx >= 0) {
            let br = nr + dr
            let bc = nc + dc
            // box destination must be empty and not a wall
            if (br < 0 || br >= this.map.size ||
                bc < 0 || bc >= this.map[0].size ||
                this.map[br][bc] == "#") {
                return this.check_win()
            }
            // check if another box is there
            var blocked = false
            for (b in this.boxes) {
                if (b[0] == br && b[1] == bc) {
                    blocked = true
                    break
                }
            }
            if (blocked) {
                return this.check_win()
            }
            // move box
            this.boxes[boxIdx][0] = br
            this.boxes[boxIdx][1] = bc
        }

        // move player
        this.player_row = nr
        this.player_col = nc
        return this.check_win()
    }

    public func print_map(): Unit {
        var disp = ArrayList<ArrayList<String>>()
        for (row in this.map) {
            disp.add(ArrayList<String>(row))
        }
        // draw targets
        for (t in this.targets) {
            disp[t[0]][t[1]] = "G"
        }
        // draw boxes
        for (b in this.boxes) {
            disp[b[0]][b[1]] = "X"
        }
        // draw player
        disp[this.player_row][this.player_col] = "O"

        for (r in disp) {
            for (c in r) {
                print("${c} ")
            }
            println("")
        }
    }
}

