class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            let rows = map.size
            for (i in 0..rows) {
                let cols = map[i].size
                for (j in 0..cols) {
                    let cell = map[i][j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                        this.map[i][j] = " "
                    } else if (cell == "G") {
                        let t = ArrayList<Int64>([i, j])
                        this.targets.add(t)
                        this.target_count += 1
                        this.map[i][j] = " "
                    } else if (cell == "X") {
                        let b = ArrayList<Int64>([i, j])
                        this.boxes.add(b)
                        this.map[i][j] = " "
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        this.is_game_over = true
        for (b in this.boxes) {
            let br = b[0]
            let bc = b[1]
            var onTarget = false
            for (t in this.targets) {
                if (br == t[0] && bc == t[1]) {
                    onTarget = true
                    break
                }
            }
            if (!onTarget) {
                this.is_game_over = false
                break
            }
        }
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var dr = 0
        var dc = 0
        if (direction == "w") {
            dr = -1
        } else if (direction == "s") {
            dr = 1
        } else if (direction == "a") {
            dc = -1
        } else if (direction == "d") {
            dc = 1
        } else {
            return this.is_game_over
        }

        let nr = this.player_row + dr
        let nc = this.player_col + dc
        if (nr < 0 || nr >= this.map.size || nc < 0 || nc >= this.map[0].size) {
            return this.is_game_over
        }
        if (this.map[nr][nc] == "#") {
            return this.is_game_over
        }

        var boxIndex = -1
        for (i in 0..this.boxes.size) {
            if (this.boxes[i][0] == nr && this.boxes[i][1] == nc) {
                boxIndex = i
                break
            }
        }

        if (boxIndex != -1) {
            let br = nr + dr
            let bc = nc + dc
            if (br < 0 || br >= this.map.size || bc < 0 || bc >= this.map[0].size) {
                return this.is_game_over
            }
            if (this.map[br][bc] == "#") {
                return this.is_game_over
            }
            for (b in this.boxes) {
                if (b[0] == br && b[1] == bc) {
                    return this.is_game_over
                }
            }
            this.boxes[boxIndex][0] = br
            this.boxes[boxIndex][1] = bc
        }

        this.player_row = nr
        this.player_col = nc
        return this.check_win()
    }

    public func print_map(): Unit {
        let rows = this.map.size
        let cols = this.map[0].size
        var display = ArrayList<ArrayList<String>>()
        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                row.add(this.map[i][j])
            }
            display.add(row)
        }
        for (b in this.boxes) {
            display[b[0]][b[1]] = "X"
        }
        for (t in this.targets) {
            let r = t[0]
            let c = t[1]
            if (display[r][c] == "X") {
                display[r][c] = "B"
            } else {
                display[r][c] = "G"
            }
        }
        display[this.player_row][this.player_col] = "O"
        for (row in display) {
            for (cell in row) {
                print("${cell} ")
            }
            println("")
        }
    }
}

