import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let re = Regex(pattern)
        let m = re.match(text)
        m.isSome()
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let re = Regex(pattern)
        let m  = re.matchAll(text)
        let out = ArrayList<String>()
        for (item in m) {
            if (item != None<String>) {
                out.append(item.getOrThrow())
            }
        }
        out
    }

    // We split on (keep) the matches, then split by them.
    // Using the pattern as the splitter keeps it simple and matches the test-case exactly.
    public func split(pattern: String, text: String): ArrayList<String> {
        let re = Regex(pattern)
        re.split(text)
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let re = Regex(pattern)
        re.sub(replacement, text)
    }

    //------------------------------------------------------------------
    // helpers
    //------------------------------------------------------------------
    public func generate_email_pattern(): String {
        r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b"
    }

    public func generate_phone_number_pattern(): String {
        r"\b\d{3}-\d{3}-\d{4}\b"
    }

    public func generate_split_sentences_pattern(): String {
        r"[.!?][\s]{1,2}(?=[A-Z])"
    }

    // Split on the generated sentence-end marker but:
    //   - keep the left part (the actual sentence) by a look-ahead.
    //   - trim the final empty fragment if it exists (common when last char is punctuation).
    public func split_sentences(text: String): ArrayList<String> {
        let pat = this.generate_split_sentences_pattern()
        let re  = Regex(pat)
        let tmp = re.split(text)
        if (tmp.size > 0 && tmp[tmp.size-1] == "") {
            tmp.remove(at: tmp.size-1)
        }
        tmp
    }

    //------------------------------------------------------------------
    // convenience wrappers
    //------------------------------------------------------------------
    public func validate_phone_number(phone_number: String): Bool {
        this.match_regex(generate_phone_number_pattern(), phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        this.findall(generate_email_pattern(), text)
    }
}

