        var remaining = amount
        while (remaining > 0) {
            let needed = this.level * 100 - this.exp
            if (remaining >= needed) {
                remaining -= needed
                this.level_up()
            } else {
                this.exp += remaining
                remaining = 0
            }
        }
    }

