        if (items.contains(item)) {
            let existing = items[item]!
            existing.quantity += quantity
            items.add(item, existing)
        } else {
            items.add(item, Item(price, quantity))
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if (!items.contains(item)) {
            return
        }
        let existing = items[item]!
        if (existing.quantity > quantity) {
            existing.quantity -= quantity
            items.add(item, existing)
        } else {
            items.remove(item)
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for (entry in items) {
            let it = entry[1]
            total += it.price * Float64(it.quantity)
