import std.collection.ArrayList
import std.regex.Regex

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Use negative look-behind to skip “Mr.” (case-insensitive)
        let pattern = r"(?i)(?<!Mr)\s*([.?!])\s+"
        let re = Regex(pattern)
        let parts = re.split(sentences_string)
        let marks = re.findAll(sentences_string).map({m => m.group(1)!})
        let res = ArrayList<String>()
        for (i in 0..parts.size) {
            let sent = parts[i].trim()
            if (sent.isEmpty()) { continue }
            if (i < marks.size) { sent += marks[i] }
            res.append(sent)
        }
        return res
    }

    public func count_words(sentence: String): Int64 {
        let words = sentence.split(" ").filter({w =>
            // keep only segments that contain at least one letter
            w.runes().any({r => (r >= r'a' && r <= r'z') || (r >= r'A' && r <= r'Z')})
        })
        return words.size
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords: Int64 = 0
        for (s in sentences) {
            let c = count_words(s)
            if (c > maxWords) { maxWords = c }
        }
        return maxWords
    }
}

import std.collection.ArrayList
import std.regex.Regex

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Regex to split on . or ? followed by a space, but not after "Mr."
        let re = Regex("(?<!Mr)[.!?]\\s+")
        let parts = re.split(sentences_string)
        let res = ArrayList<String>()
        for (p in parts) {
            let trimmed = p.trim()
            if (trimmed.size > 0) {
                res.add(trimmed)
            }
        }
        return res
    }

    public func count_words(sentence: String): Int64 {
        // Split by spaces, filter out tokens that are empty or contain only punctuation/digits
        let words = sentence.split(" ")
        var count = 0
        for (w in words) {
            let trimmed = w.trim()
            if (trimmed.size > 0 && Regex("^[a-zA-Z]+$").matches(trimmed)) {
                count++
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords = 0
        for (s in sentences) {
            let c = count_words(s)
            if (c > maxWords) {
                maxWords = c
            }
        }
        return maxWords
    }
}

import std.collection.ArrayList
import std.regex.Regex

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = r"(?<!Mr|Mrs|Dr|Prof|Sr|Jr|St|Gen|Rev|Hon|Ms)\.\s|\?\s"
        let re = Regex(pattern)
        let parts = re.split(sentences_string)
        let res = ArrayList<String>()
        for (part in parts) {
            let trimmed = part.trim()
            if (trimmed.size > 0) {
                if (!trimmed.endsWith(".") && !trimmed.endsWith("?")) {
                    if (sentences_string.contains("${trimmed}.")) {
                        res.add("${trimmed}.")
                    } else if (sentences_string.contains("${trimmed}?")) {
                        res.add("${trimmed}?")
                    } else {
                        res.add(trimmed)
                    }
                } else {
                    res.add(trimmed)
                }
            }
        }
        return res
    }

    public func count_words(sentence: String): Int64 {
        let words = sentence.split(" ")
        var count: Int64 = 0
        let wordRe = Regex("^[a-zA-Z]+$")
        for (word in words) {
            let w = word.trim()
            if (w.size > 0 && wordRe.matches(w)) {
                count += 1
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords: Int64 = 0
        for (sentence in sentences) {
            let c = count_words(sentence)
            if (c > maxWords) {
                maxWords = c
            }
        }
        return maxWords
    }
}

