class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let re = Regex("(?<!(Mr|Mrs|Dr|Ms))\\.[ ]|[?][ ]")
        let parts = sentences_string.split(re)
        let res = ArrayList<String>()
        for (i in 0..parts.size) {
            let part = parts[i].trim()
            if (part.size > 0) {
                if (i < parts.size - 1) {
                    let last = part[-1]
                    let nextChar = sentences_string[part.size + 1 + (i > 0 ? parts[i-1].size + 1 else 0)]
                    let suffix = if (nextChar == '.' || nextChar == '?') { nextChar } else { "" }
                    res.add("${part}${suffix}")
                } else {
                    res.add(part)
                }
            }
        }
        return res
    }

    public func count_words(sentence: String): Int64 {
