import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        // Split at every “.” or “?” that is NOT preceded by “Mr”.
        // The negative-look-behind (?<!Mr) ensures we do NOT split after “Mr.”.
        let re = Regex("(?<!Mr)[.?]\\s*")
        let raw = re.split(sentences_string)

        let res = ArrayList<String>()
        for (frag in raw) {
            let trimmed = frag.trim()
            if (trimmed.size > 0) {
                res.add(trimmed)
            }
        }
        return res
    }

    public func count_words(sentence: String): Int64 {
        let words = sentence.split(" ")
        var cnt: Int64 = 0
        for (tok in words) {
            if (is_alpha_word(tok)) {
                cnt = cnt + 1
            }
        }
        return cnt
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords: Int64 = 0
        for (s in sentences) {
            let w = count_words(s)
            if (w > maxWords) {
                maxWords = w
            }
        }
        return maxWords
    }

    /* ---------- private helpers ---------- */

    private func is_alpha_word(tok: String): Bool {
        // At least one alphabetic rune and no digits nor punctuation inside.
        let runes = tok.toRuneArray()
        if (runes.size == 0) {
            return false
        }
        for (r in runes) {
            let c = r
            if (!((c >= r'a' && c <= r'z') || (c >= r'A' && c <= r'Z'))) {
                return false
            }
        }
        return true
    }
}

