import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    /* ---------- helpers ---------- */
    private static func meanUnwrap(data: ArrayList<Int64>): Float64 {
        var sum: Float64 = 0.0
        for (v in data) { sum += Float64(v) }
        return sum / Float64(data.size)
    }

    private static func stdUnwrap(data: ArrayList<Int64>): Float64 {
        let m = meanUnwrap(data)
        var acc: Float64 = 0.0
        for (v in data) {
            let d = Float64(v) - m
            acc += d * d
        }
        return sqrt(acc / Float64(data.size))
    }

    /* ---------- public ---------- */
    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) { return 0.0 }
        let tmp = ArrayList<Int64>(data)
        sort(tmp)
        let mid = tmp.size / 2
        if (tmp.size % 2 == 1) {
            return Float64(tmp[mid])
        } else {
            return (Float64(tmp[mid-1]) + Float64(tmp[mid])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (v in data) {
            let c = freq.get(v) ?? 0
            freq.add(v, c + 1)
        }
        var maxC: Int64 = 0
        for (kv in freq) {
            if (kv.1 > maxC) { maxC = kv.1 }
        }
        let res = ArrayList<Int64>()
        for (kv in freq) {
            if (kv.1 == maxC) { res.add(kv.0) }
        }
        sort(res)
        return res
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) { return None<Float64> }
        return Some<Float64>(meanUnwrap(data))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) { return None<Float64> }
        return Some<Float64>(stdUnwrap(data))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        if (data.size == 0) { return None<ArrayList<Float64>> }
        let m = meanUnwrap(data)
        let s = stdUnwrap(data)
        if (s == 0.0) { return None<ArrayList<Float64>> }
        let zs = ArrayList<Float64>()
        for (v in data) {
            zs.add((Float64(v) - m) / s)
        }
        return Some<ArrayList<Float64>>(zs)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) { return None<Float64> }
        let mx = meanUnwrap(x)
        let my = meanUnwrap(y)
        var num: Float64 = 0.0
        var dx: Float64 = 0.0
        var dy: Float64 = 0.0
        for (i in 0..x.size) {
            let vx = Float64(x[i]) - mx
            let vy = Float64(y[i]) - my
            num += vx * vy
            dx += vx * vx
            dy += vy * vy
        }
        if (dx == 0.0 || dy == 0.0) { return None<Float64> }
        return Some<Float64>(num / sqrt(dx * dy))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let c = correlation(data[i], data[j]) ?? 0.0
                row.add(c)
            }
            mat.add(row)
        }
        return mat
    }
}

