import std.sort.sort

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let n = data.size
        if (n == 0) { return 0.0 }

        let sorted = data                    // sort a copy to keep caller intact
        sort(sorted)

        let mid = n / 2
        if (n % 2 == 1) {
            return Float64(sorted[mid])
        } else {                             // even length
            return (Float64(sorted[mid - 1]) + Float64(sorted[mid])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if (data.size == 0) { return ArrayList<Int64>() }

        var freq = HashMap<Int64, Int64>([])
        for (v in data) {
            freq[v] = freq.get(v) ?? 0 + 1    // build frequency map
        }

        var maxCount = Int64(0)
        for ((k, c) in freq) {
            if (c > maxCount) { maxCount = c }
        }

        var modes = ArrayList<Int64>([])
        for ((k, c) in freq) {
            if (c == maxCount) { modes.add(k) }
        }
        return modes
    }

    public static func mean(data: ArrayList<Int64>): ?Float64 {
        if (data.size == 0) { return None<Float64> }
        var sum: Int64 = 0
        for (v in data) { sum = sum + v }
        return Some<Float64>(Float64(sum) / Float64(data.size))
    }

    public static func standard_deviation(data: ArrayList<Int64>): ?Float64 {
        let mOpt = mean(data)
        if (mOpt is None) { return None<Float64> }
        let m = mOpt.getOrThrow()

        var sumSquares: Float64 = 0.0
        for (v in data) {
            let diff = Float64(v) - m
            sumSquares = sumSquares + diff * diff
        }
        let n = data.size
        return Some<Float64>(sqrt(sumSquares / Float64(n)))
    }

    public static func z_score(data: ArrayList<Int64>): ?ArrayList<Float64> {
        let mOpt  = mean(data)
        let sdOpt = standard_deviation(data)
        if (mOpt is None || sdOpt is None) { return None<ArrayList<Float64>> }

        let m  = mOpt.getOrThrow()
        let sd = sdOpt.getOrThrow()

        if (sd == 0.0) { return None<ArrayList<Float64>> }  // undefined std-dev

        var z = ArrayList<Float64>([])
        for (v in data) {
            z.add((Float64(v) - m) / sd)
        }
        return Some<ArrayList<Float64>>(z)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): ?Float64 {
        let n = x.size
        if (n != y.size || n < 2) { return None<Float64> }

        var sx: Int64 = 0
        var sy: Int64 = 0
        for (i in 0..n) {
            sx = sx + x[i]
            sy = sy + y[i]
        }
        let meanX = Float64(sx) / Float64(n)
        let meanY = Float64(sy) / Float64(n)

        var num: Float64 = 0.0
        var denX: Float64 = 0.0
        var denY: Float64 = 0.0
        for (i in 0..n) {
            let dx = Float64(x[i]) - meanX
            let dy = Float64(y[i]) - meanY
            num  = num  + dx * dy
            denX = denX + dx * dx
            denY = denY + dy * dy
        }
        let denom = sqrt(denX * denY)
        if (denom == 0.0) { return None<Float64> }  // undefined correlation
        return Some<Float64>(num / denom)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let dim = data.size
        var R = ArrayList<ArrayList<Float64>>([])
        for (i in 0..dim) {
            R.add(ArrayList<Float64>([]))
            for (j in 0..dim) {
                let cOpt = correlation(data[i], data[j])
                R[i].add(cOpt ?? 0.0)
            }
        }
        return R
    }
}

