import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) { return 0.0 }
        let sorted = data
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n/2])
        } else {
            return (Float64(sorted[n/2-1]) + Float64(sorted[n/2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if (data.size == 0) { return ArrayList<Int64>() }
        var freq = HashMap<Int64, Int64>()
        for (x in data) {
            let c = freq.get(x) ?? 0
            freq.add(x, c + 1)
        }
        var maxCount = 0
        for (kv in freq) {
            if (kv.1 > maxCount) { maxCount = kv.1 }
        }
        var modes = ArrayList<Int64>()
        for (kv in freq) {
            if (kv.1 == maxCount) { modes.add(kv.0) }
        }
        sort(modes)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) { return None<Float64> }
        var sum = 0
        for (x in data) { sum = sum + x }
        return Some<Float64>(Float64(sum) / Float64(data.size))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        match (m) {
            case None<Float64> => return None<Float64>
            case Some<Float64>(mu) => {
                var sum = 0.0
                for (x in data) {
                    let d = Float64(x) - mu
                    sum = sum + d * d
                }
                return Some<Float64>(sqrt(sum / Float64(data.size)))
            }
        }
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let sd = standard_deviation(data)
        match (m, sd) {
            case (Some<Float64>(mu), Some<Float64>(sigma)) => {
                if (sigma == 0.0) { return None<ArrayList<Float64>> }
                var zs = ArrayList<Float64>()
                for (x in data) {
                    zs.add((Float64(x) - mu) / sigma)
                }
                return Some<ArrayList<Float64>>(zs)
            }
            case _ => return None<ArrayList<Float64>>
        }
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) { return None<Float64> }
        let mx = mean(x)
        let my = mean(y)
        match (mx, my) {
            case (Some<Float64>(muX), Some<Float64>(muY)) => {
                var num = 0.0
                var denX = 0.0
                var denY = 0.0
                for (i in 0..x.size) {
                    let dx = Float64(x[i]) - muX
                    let dy = Float64(y[i]) - muY
                    num = num + dx * dy
                    denX = denX + dx * dx
                    denY = denY + dy * dy
                }
                if (denX == 0.0 || denY == 0.0) { return None<Float64> }
                return Some<Float64>(num / sqrt(denX * denY))
            }
            case _ => return None<Float64>
        }
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let k = data.size
        var mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..k) {
            var row = ArrayList<Float64>()
            for (j in 0..k) {
                let c = correlation(data[i], data[j])
                match (c) {
                    case None<Float64> => row.add(0.0)
                    case Some<Float64>(v) => row.add(v)
                }
            }
            mat.add(row)
        }
        return mat
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let n = data.size
        if (n == 0) {
            return 0.0
        }
        var copy = ArrayList<Int64>(data)
        sort(copy)
        if (n % 2 == 1) {
            return Float64(copy[(n - 1) / 2])
        } else {
            let mid = n / 2
            return (Float64(copy[mid - 1]) + Float64(copy[mid])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (x in data) {
            let cnt = freq.get(x) ?? 0
            freq.add(x, cnt + 1)
        }
        var maxCnt = 0Int64
        for (v in freq.values) {
            if (v > maxCnt) {
                maxCnt = v
            }
        }
        var res = ArrayList<Int64>()
        for (kv in freq) {
            if (kv.1 == maxCnt) {
                res.add(kv.0)
            }
        }
        return res
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if (n == 0) {
            return None<Float64>
        }
        var sum = 0Int64
        for (x in data) {
            sum = sum + x
        }
        return Some<Float64>(Float64(sum) / Float64(n))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m is None) {
            return None<Float64>
        }
        let mu = (m as Some<Float64>).getOrThrow()
        let n = data.size
        var sqSum = 0.0
        for (x in data) {
            let diff = Float64(x) - mu
            sqSum = sqSum + diff * diff
        }
        return Some<Float64>(sqrt(sqSum / Float64(n)))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let sd = standard_deviation(data)
        if (m is None || sd is None) {
            return None<ArrayList<Float64>>
        }
        let mu = (m as Some<Float64>).getOrThrow()
        let sigma = (sd as Some<Float64>).getOrThrow()
        var res = ArrayList<Float64>()
        for (x in data) {
            let z = (Float64(x) - mu) / sigma
            res.add(z)
        }
        return Some<ArrayList<Float64>>(res)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>
        }
        let n = x.size
        var sx = 0Int64
        var sy = 0Int64
        for (i in 0..n) {
            sx = sx + x[i]
            sy = sy + y[i]
        }
        let mx = Float64(sx) / Float64(n)
        let my = Float64(sy) / Float64(n)
        var num = 0.0
        var denx = 0.0
        var deny = 0.0
        for (i in 0..n) {
            let dx = Float64(x[i]) - mx
            let dy = Float64(y[i]) - my
            num = num + dx * dy
            denx = denx + dx * dx
            deny = deny + dy * dy
        }
        if (denx == 0.0 || deny == 0.0) {
            return None<Float64>
        }
        return Some<Float64>(num / sqrt(denx * deny))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let k = data.size
        var mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..k) {
            var row = ArrayList<Float64>()
            for (j in 0..k) {
                let c = correlation(data[i], data[j])
                row.add(c ?? 0.0)
            }
            mat.add(row)
        }
        return mat
    }
}

