            let s = this.portfolio[i]
            if (s.name == stock.name && s.price == stock.price && s.quantity >= stock.quantity) {
                if (s.quantity == stock.quantity) {
                    this.portfolio.remove(at: i)
                } else {
                    s.quantity -= stock.quantity
                }
                this.cash_balance += stock.price * Float64(stock.quantity)
