class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        let index = this.find_stock_index(stock)
        if (index >= 0) {
            this.portfolio.remove(at: index)
            return true
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let totalCost = stock.price * Float64(stock.quantity)
        if (this.cash_balance >= totalCost) {
            this.cash_balance -= totalCost
            this.add_stock(stock)
            return true
        }
        return false
    }

    public func sell_stock(stock: Stock): Bool {
        let index = this.find_stock_index(stock)
        if (index >= 0) {
            let existing = this.portfolio[index]
            if (existing.quantity >= stock.quantity) {
                existing.quantity -= stock.quantity
                if (existing.quantity == 0) {
                    this.portfolio.remove(at: index)
                }
                this.cash_balance += stock.price * Float64(stock.quantity)
                return true
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var total: Float64 = 0.0
        for (s in this.portfolio) {
            total += s.price * Float64(s.quantity)
        }
        return total
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let total = this.calculate_portfolio_value()
        let summary = ArrayList<HashMap<String, Any>>()
        for (s in this.portfolio) {
            let item = HashMap<String, Any>()
            item.add("name", s.name)
            item.add("value", s.price * Float64(s.quantity))
            summary.add(item)
        }
        return (total, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }

    private func find_stock_index(stock: Stock): Int64 {
        for (i in 0..this.portfolio.size) {
            let s = this.portfolio[i]
            if (s.name == stock.name && s.price == stock.price) {
                return i
            }
        }
        return -1
    }
}

