        if (shouldHeat != isHeat) {
            this.auto_set_mode()
            return false
        }
        return true
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var time: Int64 = 0
        let step: Float64 = 1.0
        while (abs(this.current_temperature - this.target_temperature) > 0.01) {
            if (this.mode == "heat") {
                this.current_temperature += step
            } else {
                this.current_temperature -= step
            }
            time += 1
        }
        return time
    }
}

