    }

    public func get_mode(): String {
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        if (mode == "heat" || mode == "cool") {
            this.mode = mode
            return true
        }
        return false
    }

    public func auto_set_mode(): Unit {
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        let conflict = (this.current_temperature < this.target_temperature && this.mode == "cool") ||
                       (this.current_temperature >= this.target_temperature && this.mode == "heat")
        if (conflict) {
            this.auto_set_mode()
            return false
        }
        return true
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var steps: Int64 = 0
        let delta = 1.0
        while (abs(this.current_temperature - this.target_temperature) > 0.0) {
            if (this.mode == "heat") {
                this.current_temperature += delta
                if (this.current_temperature > this.target_temperature) {
                    this.current_temperature = this.target_temperature
                }
            } else {
                this.current_temperature -= delta
                if (this.current_temperature < this.target_temperature) {
                    this.current_temperature = this.target_temperature
                }
            }
            steps += 1
        }
        return steps
    }
}

