            }
        } else {
            if (this.mode != "cool") {
                this.mode = "cool"
                return false
            }
        }
        true
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var time: Int64 = 0
        while (abs(this.current_temperature - this.target_temperature) > 0.01) {
            if (this.mode == "heat") {
