    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board.size || col < 0 || col >= board[0].size) {
            return false
        }
        if (board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = if (current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        let n = board.size
        // rows
        for (r in 0..n) {
            let first = board[r][0]
            if (first == " ") { continue }
            var win = true
            for (c in 1..n) {
                if (board[r][c] != first) {
                    win = false
                    break
                }
            }
            if (win) { return Some<String>(first) }
        }
        // columns
        for (c in 0..n) {
            let first = board[0][c]
            if (first == " ") { continue }
            var win = true
            for (r in 1..n) {
                if (board[r][c] != first) {
                    win = false
                    break
                }
            }
            if (win) { return Some<String>(first) }
        }
        // diagonal 1
        let first = board[0][0]
        if (first != " ") {
            var win = true
            for (i in 1..n) {
                if (board[i][i] != first) {
                    win = false
                    break
                }
            }
            if (win) { return Some<String>(first) }
        }
        // diagonal 2
        let first2 = board[0][n-1]
        if (first2 != " ") {
            var win = true
            for (i in 1..n) {
                if (board[i][n-1-i] != first2) {
                    win = false
                    break
                }
            }
            if (win) { return Some<String>(first2) }
        }
        None<String>
    }

    public func is_board_full(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell == " ") { return false }
            }
        }
        true
    }
}

import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board.size || col < 0 || col >= board[row].size) {
            return false
        }
        if (board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = if (current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        let N = board.size
        // rows
        for (r in 0..N) {
            let first = board[r][0]
            if (first == " ") { continue }
            var win = true
            for (c in 1..N) {
                if (board[r][c] != first) { win = false; break }
            }
            if (win) { return Some<String>(first) }
        }
        // cols
        for (c in 0..N) {
            let first = board[0][c]
            if (first == " ") { continue }
            var win = true
            for (r in 1..N) {
                if (board[r][c] != first) { win = false; break }
            }
            if (win) { return Some<String>(first) }
        }
        // diag1
        let first = board[0][0]
        if (first != " ") {
            var win = true
            for (i in 1..N) {
                if (board[i][i] != first) { win = false; break }
            }
            if (win) { return Some<String>(first) }
        }
        // diag2
        let last = board[0][N - 1]
        if (last != " ") {
            var win = true
            for (i in 1..N) {
                if (board[i][N - 1 - i] != last) { win = false; break }
            }
            if (win) { return Some<String>(last) }
        }
        return None<String>
    }

    public func is_board_full(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell == " ") {
                    return false
                }
            }
        }
        return true
    }
}

