import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs
import std.collection.*

class TriCalculator {
    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        taylor(x, 50)
    }

    public func factorial(a: Int64): Decimal {
        var res = Decimal(1)
        for (i in 1..a+1) {
            res = res * Decimal(i)
        }
        res
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = x / 180.0 * PI
        var sum = 0.0
        var term = 1.0
        for (k in 0..n) {
            sum += term
            term = -term * rad * rad / ((2*k+1) * (2*k+2))
        }
        sum
    }

    public func sin(x: Float64): Float64 {
        let rad = x / 180.0 * PI
        var sum = 0.0
        var term = rad
        for (k in 0..50) {
            sum += term
            term = -term * rad * rad / ((2*k+2) * (2*k+3))
        }
        sum
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) < 0.000001) {
            None<Float64>
        } else {
            Some<Float64>(sin(x) / c)
        }
    }
}

