class TriCalculator {

    let PI = 3.141592653589793

    public init() {}

    public func cos(x: Float64): Float64 {
        taylor(x, 50)
    }

    private func toRadian(deg: Float64): Float64 {
        deg * PI / 180.0
    }

    public func factorial(a: Int64): Decimal {
        var res = Decimal(1)
        for (i in 2..a+1) {
            res = res * Decimal(i)
        }
        res
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = toRadian(x)
        var sum = 0.0
        var term = 1.0
        var sign = 1.0
        for (k in 0..n) {
            sum += sign * term
