// ----------  Parser  ----------
class Parser {
    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(charToEat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == charToEat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parseExpression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parseExpression(): Int64 {
        var x = this.parseTerm()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parseTerm()
            } else if (this.eat(r'-')) {
                x -= this.parseTerm()
            } else {
                return x
            }
        }
        return x
    }

    public func parseTerm(): Int64 {
        var x = this.parseFactor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parseFactor()
            } else if (this.eat(r'/')) {
                x /= this.parseFactor()
            } else {
                return x
            }
        }
        return x
    }

    public func parseFactor(): Int64 {
        if (this.eat(r'+')) {
            return this.parseFactor()
        }
        if (this.eat(r'-')) {
            return -this.parseFactor()
        }
        var x = 0
        let startPos = this.pos
        if (this.eat(r'(')) {
            x = this.parseExpression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[startPos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

