        this.nums.clear()
        for (_ in 0..4) {
            this.nums.add(rng.nextInt64(1..10))
        }
    }

    public func getMyCards(): ArrayList<Int64> {
        this._generateCards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        // quick digit usage check
        let cnt = HashMap<Int64, Int64>()
        for (n in this.nums) {
            cnt[n] = (cnt.get(n) ?? 0) + 1
        }
        for (c in expression.runes()) {
            if (c.isAsciiNumber()) {
                let d = Int64(String(c))
                if ((cnt.get(d) ?? 0) == 0) {
                    return false
                }
                cnt[d] = cnt.get(d) ?? 0 - 1
            }
        }
        // evaluate
        try {
            let v = Parser(expression).parse()
            return v == 24
        } catch (_) {
            return false
        }
    }

    public func evaluateExpression(expression: String): Bool {
        try {
            return Parser(expression).parse() == 24
        } catch (_) {
            return false
        }
    }
