    }

    public func _generate_cards(): Unit {
        this.nums = ArrayList<Int64>()
        let rnd = Random()
        for (_ in 0..4) {
            this.nums.append(rnd.nextInt64(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        if (!this.validate_usage(expression)) {
            return false
        }
        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (_) {
            return false
        }
    }

    private func validate_usage(expr: String): Bool {
        let counts: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for (n in this.nums) {
            let key = n
            if (counts.contains(key)) {
                counts[key] = counts.get(key).getOrThrow() + 1
            } else {
                counts.add(key, 1)
            }
        }
        let used = HashMap<Int64, Int64>()
        let numBuffer = ArrayList<Rune>()
        let runes = expr.runes()
        for (r in runes) {
            if (r.isAsciiNumber()) {
                numBuffer.append(r)
            } else {
                if (numBuffer.size > 0) {
                    let numStr = String.fromRunes(numBuffer)
                    let num = Int64.parse(numStr)
                    if (!counts.contains(num) || (used.contains(num) && used[num] >= counts[num])) {
                        return false
                    }
                    if (used.contains(num)) {
                        used[num] = used.get(num).getOrThrow() + 1
                    } else {
                        used.add(num, 1)
                    }
                    numBuffer = ArrayList<Rune>()
                }
            }
        }
        if (numBuffer.size > 0) {
            let numStr = String.fromRunes(numBuffer)
            let num = Int64.parse(numStr)
            if (!counts.contains(num) || (used.contains(num) && used[num] >= counts[num])) {
                return false
            }
        }
        for (k in counts) {
            let expected = counts.get(k).getOrThrow()
            let actual = if (used.contains(k)) used.get(k).getOrThrow() else 0
            if (actual != expected) {
                return false
            }
        }
        return true
    }
}

