            if (c >= '0' && c <= '9') {
                var j = i
                while (j < expr.size && expr[j] >= '0' && expr[j] <= '9') {
                    j += 1
                }
                let num = Int64.parse(expr[i..j])
                used.add(num)
                i = j
            } else {
                i += 1
            }
        }
        if (used.size != 4) {
            return false
        }
        let sortedUsed = used
        sort(sortedUsed)
        let sortedNums = this.nums
        sort(sortedNums)
        for (k in 0..4) {
            if (sortedUsed[k] != sortedNums[k]) {
                return false
            }
        }
        return true
    }
}

