class TwentyFourPointGame {

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        // Generate four distinct random integers from 1 to 9
        let rng = Random()
        this.nums = ArrayList<Int64>()
        while (this.nums.size < 4) {
            let n = rng.nextInt64(1, 10) // upper bound exclusive
            if (!this.nums.contains(n)) {
                this.nums.add(n)
            }
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        // Return the current cards (generate new ones if none)
        if (this.nums.size == 0) {
            this._generate_cards()
        }
        // Return a shallow copy to prevent external mutation
        let copy = ArrayList<Int64>()
        for (v in this.nums) {
            copy.add(v)
        }
        return copy
    }

    public func evaluate_expression(expression: String): Bool {
        try {
            let p = Parser(expression.replace(" ", ""))
            return p.parse() == 24
        } catch (_) {
            return false
        }
    }

    public func answer(expression: String): Bool {
        // Basic validation
        let sanitized = expression.replace(" ", "")
        let available = this.get_my_cards().toArray()
        var counts: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for (v in available) {
            counts[v] = (counts.get(v) ?? 0) + 1
        }
        var seen_in_expr: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        var cur: String = ""
        var c: Rune
        for (i in 0..sanitized.size) {
            c = sanitized[i]
            if (c.isAsciiNumber()) {
                cur += "${c}"
            } else {
                if (!cur.isEmpty()) {
                    let n = Int64.parse(cur)
                    seen_in_expr[n] = (seen_in_expr.get(n) ?? 0) + 1
                    cur = ""
                }
            }
        }
        if (!cur.isEmpty()) {
            let n = Int64.parse(cur)
            seen_in_expr[n] = (seen_in_expr.get(n) ?? 0) + 1
        }
        // Check counts match
        for (entry in seen_in_expr) {
            if ((entry.value) != ((counts.get(entry.key) ?? 0))) {
                return false
            }
        }
        // Evaluate
        return evaluate_expression(expression)
    }
}

