class TwentyFourPointGame {
    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        this.nums.clear()
        let rng = Random()
        for (_ in 0..4) {
            this.nums.append(Int64(rng.nextUInt8(1, 10)))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums.clone()
    }

    public func answer(expression: String): Bool {
        if (!this.valid(expression)) {
            return false
        }
        try {
            return evaluate_expression(expression)
        } catch (_) {
            return false
        }
    }

    public func evaluate_expression(expression: String): Bool {
        let parser = Parser(expression)
        let res = parser.parse()
        return res == 24
    }

    private func valid(expr: String): Bool {
        var numsUsed = ArrayList<Int64>()
        var i = 0
        while (i < expr.size) {
            let ch = Rune(expr[i])
            if (ch.isAsciiDigit()) {
                var num = 0
                while (i < expr.size && Rune(expr[i]).isAsciiDigit()) {
                    num = num * 10 + Int64(expr[i]) - Int64('0')
                    i += 1
                }
                numsUsed.append(num)
            } else {
                i += 1
            }
        }
        sort(numsUsed)
        let orig = this.nums.clone()
        sort(orig)
        if (numsUsed.size != orig.size) {
            return false
        }
        for (j in 0..numsUsed.size) {
            if (numsUsed[j] != orig[j]) {
                return false
            }
        }
        return true
    }
