import std.collection.HashMap
import std.regex.*

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let re = Regex("^(https?)://")
        let m = re.match(url)
        if (m.hasMatch()) {
            return Some<String>(m.group(1).getOrThrow())
        }
        return None<String>
    }

    public func get_host(): Option<String> {
        let re = Regex("^https?://([^/]+)")
        let m = re.match(url)
        if (m.hasMatch()) {
            return Some<String>(m.group(1).getOrThrow())
        }
        return None<String>
    }

    public func get_path(): Option<String> {
        let re = Regex("^https?://[^/]+(/[^#]*)")
        let m = re.match(url)
        if (m.hasMatch()) {
            return Some<String>(m.group(1).getOrThrow())
        }
        return None<String>
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let re = Regex("\\?([^#]+)")
        let m = re.search(url)
        if (!m.hasMatch()) {
            return None<HashMap<String, String>>
        }
        let query = m.group(1).getOrThrow()
        let map = HashMap<String, String>()
        for (part in query.split("&")) {
            let kv = part.split("=")
            if (kv.size == 2) {
                map.add(kv[0], kv[1])
            }
        }
        return Some<HashMap<String, String>>(map)
    }

    public func get_fragment(): Option<String> {
        let re = Regex("#(.+)$")
        let m = re.search(url)
        if (m.hasMatch()) {
            return Some<String>(m.group(1).getOrThrow())
        }
        return None<String>
    }
}

