import std.regex.*

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let m = Regex("^(\\w+)://").match(this.url)
        match (m) {
            case None => None<String>
            case Some(m) => Some<String>(m.group(1))
        }
    }

    public func get_host(): Option<String> {
        let m = Regex("://([^/\\?#]+)").match(this.url)
        match (m) {
            case None => None<String>
            case Some(m) => Some<String>(m.group(1))
        }
    }

    public func get_path(): Option<String> {
        let m = Regex("://[^/\\?#]*(/[^#]*)").match(this.url)
        match (m) {
            case None => None<String>
            case Some(m) => Some<String>(m.group(1))
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let m = Regex("\\?([^#]*)").match(this.url)
        match (m) {
            case None => None<HashMap<String, String>>
            case Some(m) => {
                let query = m.group(1)
                let map = HashMap<String, String>()
                for (part in query.split("&")) {
                    let kv = part.split("=")
                    if (kv.size == 2) {
                        map.add(kv[0], kv[1])
                    }
                }
                Some<HashMap<String, String>>(map)
            }
        }
    }

    public func get_fragment(): Option<String> {
        let m = Regex("#(.*)$").match(this.url)
        match (m) {
            case None => None<String>
            case Some(m) => Some<String>(m.group(1))
        }
    }
}

import std.collection.HashMap
import std.regex.*

func extract_group(s: String, re: Regex): Option<String> {
    match (re.find(s)) {
        case Some(m) => Some(m.group(1))
        case _       => None
    }
}

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let re = Regex("^(https?)://")
        extract_group(url, re)
    }

    public func get_host(): Option<String> {
        let re = Regex("^https?://([^/]+)")
        extract_group(url, re)
    }

    public func get_path(): Option<String> {
        let re = Regex("^https?://[^/]+(/[^#]*)")
        extract_group(url, re)
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let re = Regex("\\?([^#]+)")
        match (re.find(url)) {
            case Some(m) =>
                let params = HashMap<String, String>()
                let query = m.group(1)
                let kv_re = Regex("([^=&]+)=([^&]*)")
                for (kv in kv_re.find_all(query)) {
                    params.add(kv.group(1), kv.group(2))
                }
                Some(params)
            case _ => None
        }
    }

    public func get_fragment(): Option<String> {
        let re = Regex("#(.+)$")
        extract_group(url, re)
    }
}

