class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let idx = this.url.indexOf("://")
        if (idx == -1) {
            return None<String>
        }
        Some<String>(this.url[0..idx])
    }

    public func get_host(): Option<String> {
        let start = this.url.indexOf("://")
        if (start == -1) {
            return None<String>
        }
        start = start + 3
        var end = this.url.indexOf("/", start)
        if (end == -1) {
            end = this.url.size
        }
        Some<String>(this.url[start..end])
    }

    public func get_path(): Option<String> {
        let start = this.url.indexOf("/", this.url.indexOf("://") + 3)
        if (start == -1) {
            return Some<String>("")
        }
        Some<String>(this.url[start..])
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let qmark = this.url.indexOf("?")
        if (qmark == -1) {
            return Some<HashMap<String, String>>(HashMap<String, String>([]))
        }
        var end = this.url.indexOf("#", qmark)
        if (end == -1) {
            end = this.url.size
        }
        let query = this.url[qmark + 1..end]
        let params = HashMap<String, String>([])
        for (part in query.split("&")) {
            let kv = part.split("=")
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            }
        }
        Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let hash = this.url.indexOf("#")
        if (hash == -1) {
            return None<String>
        }
        Some<String>(this.url[hash + 1..])
    }
}

