class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let idx = this.url.indexOf("://")
        if (idx < 0) {
            return None<String>
        }
        return Some<String>(this.url[0..idx])
    }

    public func get_host(): Option<String> {
        let base = match (this.get_scheme()) {
            case Some(scheme) => this.url[scheme.size + 3..]
            case _ => this.url
        }
        let slash = base.indexOf("/")
        if (slash < 0) {
            return Some<String>(base)
        }
        return Some<String>(base[0..slash])
    }

    public func get_path(): Option<String> {
        let base = match (this.get_scheme()) {
            case Some(scheme) => this.url[scheme.size + 3..]
            case _ => this.url
        }
        let slash = base.indexOf("/")
        if (slash < 0) {
            return Some<String>("")
        }
        let hash = base.indexOf("#")
        let queryEnd = if (hash < 0) { base.size } else { hash }
        return Some<String>(base[slash..queryEnd])
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pathPart = match (this.get_path()) {
            case Some(p) => p
            case _ => return None<HashMap<String, String>>
        }
        let qm = pathPart.indexOf("?")
        if (qm < 0) {
            return Some<HashMap<String, String>>(HashMap<String, String>([]))
        }
        let hash = pathPart.indexOf("#")
        let end = if (hash < 0) { pathPart.size } else { hash }
        let query = pathPart[qm + 1..end]
        let params = HashMap<String, String>([])
        for (pair in query.split("&")) {
            let kv = pair.split("=")
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            }
        }
        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let hash = this.url.indexOf("#")
        if (hash < 0) {
            return None<String>
        }
        return Some<String>(this.url[hash + 1..])
    }
}

