class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let idx = url.seekIndex("://")
        if (idx < 0) { return None<String> }
        Some<String>(url[0..idx])
    }

    public func get_host(): Option<String> {
        let idx = url.seekIndex("://")
        if (idx < 0) { return None<String> }
        let hostStart = idx + 3
        var hostEnd = url.seekIndex("/", hostStart)
        if (hostEnd < 0) { hostEnd = url.seekIndex("?", hostStart) }
        if (hostEnd < 0) { hostEnd = url.seekIndex("#", hostStart) }
        if (hostEnd < 0) { hostEnd = url.size }
        if (hostStart >= hostEnd) { return None<String> }
        Some<String>(url[hostStart..hostEnd])
    }

    public func get_path(): Option<String> {
        let idx = url.seekIndex("/", url.seekIndex("://") < 0 ? 0 : url.seekIndex("://") + 3)
        if (idx < 0) { return None<String> }
        let pathEnd = url.seekIndex("#") < 0 ? url.size : url.seekIndex("#")
        Some<String>(url[idx..pathEnd])
    }

    public func get_fragment(): Option<String> {
        let idx = url.seekIndex("#")
        if (idx < 0) { return None<String> }
        Some<String>(url[idx+1..])
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let qIdx = url.seekIndex("?")
        if (qIdx < 0) { return None<HashMap<String, String>> }
        let fIdx = url.seekIndex("#")
        let query = fIdx < 0 ? url[qIdx+1..] : url[qIdx+1..fIdx]
        var map = HashMap<String, String>()
        for (part in query.split("&")) {
            let kv = part.split("=", 1)
            if (kv.size == 2) {
                map.add(kv[0], kv[1])
            }
        }
        Some<HashMap<String, String>>(map)
    }
}

import std.collection.ArrayList

class UrlPath {
    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixed = UrlPath.fix_path(path)
        if (fixed == "") { return }
        let arr = fixed.split("/")
        for (s in arr) {
            segments.add(s)
        }
    }

    public static func fix_path(path: String): String {
        var s = path
        while (s.size > 0 && s[0] == '/') {
            s = s[1..]
        }
        while (s.size > 0 && s[s.size - 1] == '/') {
            s = s[0..s.size - 1]
        }
        return s
    }
}

