            for (j in 0..vector_list_1[0].size) {
                let val = vector_list_1[i][j]
                dot += val * vector_list_2[i][j]
                norm1 += val * val
                norm2 += vector_list_2[i][j] * vector_list_2[i][j]
            }
        }
        if (norm1 == 0.0 || norm2 == 0.0) {
            return 0.0
        }
        dot / (sqrt(norm1) * sqrt(norm2))
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (key in number_dict) {
            let count = number_dict[key]!
            let weight = log((Float64(total_num) + 1.0) / (count + 1.0))
            result.add(key, weight)
        }
        result
    }
}

