class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dim = vector_1.size
        if (dim != vector_2.size) {
            return 0.0
        }
        var dot = 0.0
        var norm1 = 0.0
        var norm2 = 0.0
        for (i in 0..dim) {
            let a = vector_1[i]
            let b = vector_2[i]
            dot += a * b
            norm1 += a * a
            norm2 += b * b
        }
        let denom = sqrt(norm1) * sqrt(norm2)
        if (denom == 0.0) {
            return 0.0
        }
        dot / denom
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let res = ArrayList<Float64>()
        for (v in vectors_all) {
            res.add(similarity(vector_1, v))
        }
        res
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let n1 = vector_list_1.size
        let n2 = vector_list_2.size
        if (n1 == 0 || n2 == 0) {
            return 0.0
        }
        var sum1 = ArrayList<Float64>()
        let dim = vector_list_1[0].size
        for (i in 0..dim) {
            sum1.add(0.0)
        }
        for (v in vector_list_1) {
            for (i in 0..dim) {
                sum1[i] += v[i]
            }
        }
        for (i in 0..dim) {
            sum1[i] /= n1.toFloat64()
        }

        var sum2 = ArrayList<Float64>()
        for (i in 0..dim) {
            sum2.add(0.0)
        }
        for (v in vector_list_2) {
            for (i in 0..dim) {
                sum2[i] += v[i]
            }
        }
        for (i in 0..dim) {
            sum2[i] /= n2.toFloat64()
        }

        similarity(sum1, sum2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let res = HashMap<String, Float64>()
        for (kv in number_dict) {
            let count = kv[1]
            let weight = log((total_num.toFloat64() + 1.0) / (count + 1.0))
            res.add(kv[0], weight)
        }
        res
    }
}

