            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..this.scales.size) {
            let power = idx == 0 ? 2 : idx * 3
            this.numwords[this.scales[idx]] = (10 ** power, 0)
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])

        this.allValidWords = HashSet<String>()
        this.allValidWords.add("and")
        for (word in this.units) { if (word.size > 0) { this.allValidWords.add(word) } }
        for (word in this.tens) { if (word.size > 0) { this.allValidWords.add(word) } }
        for (word in this.scales) { this.allValidWords.add(word) }
        for (word in this.ordinal_words) { this.allValidWords.add(word.0) }
    }

    public func text2int(textnum: String): String {
        let tokens = this.tokenize(textnum)
        if (tokens.size == 0) { return "0" }

        var current = 0
        var result = 0

        for (token in tokens) {
            if (!this.numwords.contains(token)) { return "0" }
            let (scale, increment) = this.numwords[token]
            current = current * scale + increment
            if (scale > 100) {
                result += current
                current = 0
            }
        }
        result += current
        return result.toString()
    }

    public func is_valid_input(textnum: String): Bool {
        let tokens = this.tokenize(textnum)
        if (tokens.size == 0) { return false }
        for (token in tokens) {
            if (!this.allValidWords.contains(token)) { return false }
        }
        return true
    }

    private func tokenize(text: String): ArrayList<String> {
        let clean = Regex("-").replace(text, " ").lowercase()
        let parts = clean.split(" ")
        let result = ArrayList<String>()
        for (part in parts) {
            let trimmed = part.trim()
            if (trimmed.size > 0) { result.add(trimmed) }
        }
        return result
    }
}

